INSERT INTO `proposals` (`id`, `title`, `summary`, `full_text`, `category_id`, `candidate_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(403, 'Creación del Sistema Nacional contra la Macrocorrupción', 'Se propone una nueva arquitectura institucional que aborda la corrupción de manera integral bajo un enfoque sistémico, estructurada en cinco pilares: prevención, investigación, juzgamiento, presencia territorial y movilización social.', 'Propongo la creación del Sistema Nacional contra la Macrocorrupción, una arquitectura institucional coherente que actúe de principio a fin. Un sistema con cinco pilares que se refuerzan mutuamente: prevención e información, investigación especializada, juzgamiento eficaz con reparación, presencia decidida en los territorios y movilización ciudadana.', 1, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(404, 'Transparencia, prevención e información', 'Propuesta enfocada en la anticipación mediante el fortalecimiento técnico y presupuestal de la Secretaría de Transparencia y la UIAF, además de la puesta en marcha de un sistema de alertas tempranas y datos abiertos.', 'Pasaremos de reaccionar a anticiparnos. La transparencia y la información en tiempo real serán nuestra primera línea de defensa. Fortaleceremos la Unidad de Información y Análisis Financiero (UIAF) y daremos autonomía real —técnica, administrativa y presupuestal— a la Secretaría de Transparencia de la Presidencia, garantizando su independencia y su capacidad de investigación con enfoque sistémico. Pondremos a funcionar plenamente el Portal Anticorrupción de Colombia (PACO) como plataforma abierta y preventiva. Construiremos un sistema de alertas tempranas contra la macrocorrupción, articulando bases de datos, trazabilidad del gasto y señales de riesgo.', 1, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(405, 'Investigación y juzgamiento con enfoque de sistema', 'Creación de una unidad especializada en la Fiscalía y una instancia de juzgamiento de alto nivel que investigue la corrupción como estructuras criminales organizadas (macrocriminalidad) y no como delitos individuales aislados.', 'Crearemos en la Fiscalía General de la Nación la Unidad Nacional de Investigación de la Macrocorrupción. Las cadenas de corrupción no se investigan caso por caso: se investigan como sistemas, con procesos ágiles y coordinados. Esta unidad identificará los aparatos y estructuras de la macrocorrupción y a sus jefes o determinadores; develará los modus operandi, los planes y patrones de criminalidad a escala nacional, sectorial y regional; y rastreará las dimensiones económicas, incluido el lavado de activos y los mecanismos de impunidad. Aplicaremos metodologías de macrocriminalidad, como las usadas frente a crímenes de lesa humanidad o graves violaciones de derechos humanos. Crearemos una instancia de juzgamiento especial, al más alto nivel posible, para los casos de corrupción sistémica. Las sentencias incluirán medidas de reparación integral para víctimas individuales y colectivas. La macrocorrupción también deja víctimas y territorios heridos, y deben ser reparados.', 1, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(406, 'Fondo de Reparación de Víctimas de la Corrupción', 'Implementación de un fondo para canalizar bienes y capitales expropiados a los corruptos, asegurando que el dinero recuperado se reinvierta directamente en el sector afectado (como salud) y se utilice para reparar a las víctimas.', 'Canalizaremos al Fondo todos los capitales y recursos expropiados a los corruptos para reparar no solo el dinero público malgastado, sino también los daños materiales e inmateriales causados a víctimas individuales, colectivas y a la sociedad. Cuando la corrupción golpee un sector, como la salud, los recursos recuperados se destinarán a fortalecer ese sistema y a reparar a sus víctimas. Cada peso recuperado debe convertirse en un derecho restituido. Fortaleceremos la Sociedad de Activos Especiales (SAE) para que la recuperación de bienes ilícitos se traduzca en obras y servicios para la gente. Evaluaremos, además, la aplicación de modelos de justicia restaurativa en este campo.', 1, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(407, 'Presencia decidida en los territorios', 'Descentralización de la lucha anticorrupción para llevar la capacidad judicial directamente a las regiones con mayores índices de impunidad, promoviendo alianzas entre el Estado y la ciudadanía local.', 'Llevaremos la acción coordinada del sistema de justicia a los lugares con mayores índices de corrupción e impunidad, con capacidad real de investigación y juzgamiento en el terreno. Donde más roban lo público, más presente debe hacerse el Estado. Trabajaremos para que surjan alianzas territoriales anticorrupción, que integren a los movimientos sociales, las ciudadanías, el sector privado con la acción del Estado de derecho.', 1, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(408, 'Impulso de un movimiento nacional de vigilancia y control social', 'Impulso de un movimiento nacional de vigilancia y control social, fomentando una cultura de integridad desde la educación y el rechazo moral colectivo hacia los actos de corrupción.', 'Ningún país derrota la macrocorrupción solo desde los despachos. Necesitamos ciudadanía vigilante y organizada. Junto con movimientos sociales, organizaciones comunitarias, academia y sector privado, promoveremos un gran movimiento nacional de participación, control y fiscalización social. Impulsaremos una cultura de integridad que empiece en la escuela y llegue a cada oficina pública, a cada empresa y a cada familia. La transparencia debe ser una práctica cotidiana, no un discurso. La sociedad debe sostener una estrategia de rechazo moral y ético frente a los corruptos y a todo acto ilícito relacionado con la corrupción. La participación ciudadana será vínculo y motor: veeduría, seguimiento, denuncia responsable. Acompañaremos a las víctimas de la corrupción cuya memoria, exigencia de verdad y reivindicación de justicia son definitivas para triunfar en esta causa.', 1, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(409, 'Construcción de paz integral', 'La paz se entiende como un proceso amplio que va más allá del conflicto armado e implica transformar las causas estructurales como desigualdad, exclusión y violencia.', 'Creo en la paz como camino y en el diálogo como herramienta para cerrar el ciclo de violencia que ha marcado nuestra historia. Debemos avanzar con decisión en otras reformas sociales, en la construcción integral de la paz...', 2, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(410, 'Diálogo como herramienta central', 'Se plantea el diálogo político y social como el principal mecanismo para lograr la paz, rechazando enfoques basados solo en la fuerza.', 'Creo en la paz como camino y en el diálogo como herramienta para cerrar el ciclo de violencia que ha marcado nuestra historia.', 2, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(411, 'Centralidad de las víctimas', 'Las víctimas deben ser protagonistas del proceso de paz, garantizando verdad, justicia y reparación.', 'Creo en el poder de las víctimas para derrotar la impunidad, dignificar a las comunidades lesionadas por la violencia y construir una verdadera reconciliación nacional.', 2, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(412, 'Justicia y lucha contra la impunidad', 'La paz requiere justicia efectiva, investigación de crímenes y combate a la impunidad.', 'La reconciliación nacional, los acuerdos —uno o múltiples—, el fin de todas las violencias, la verdad y la justicia, deben ser los principios rectores de cualquier proyecto político...', 2, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(413, 'Política internacional orientada a la paz', 'Se propone una política exterior basada en la paz, la solidaridad y la autonomía.', 'Por una política exterior de paz, autónoma y solidaria con los migrantes.', 2, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(414, 'Reconciliación nacional', 'La paz requiere unión nacional, inclusión y superación de la polarización.', 'Creo en la necesidad de unirnos como sociedad... construir puentes que nos acerquen a un Pacto Nacional que incluya a todos los sectores de la sociedad.', 2, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(415, 'Política internacional orientada a la paz', 'Se propone una política exterior basada en la paz, la solidaridad y la autonomía.', 'Por una política exterior de paz, autónoma y solidaria con los migrantes.', 12, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(416, 'La política social como centro del modelo económico', 'El programa plantea que la economía debe estar orientada a garantizar derechos y bienestar, poniendo la política social en el centro del desarrollo.', 'El centro de nuestro programa es la política social.', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(417, 'Economía para superar la pobreza y la desigualdad', 'Se propone un modelo económico enfocado en reducir la pobreza, especialmente en territorios urbanos, mediante políticas de igualdad sustantiva.', 'Hacia una política de igualdad sustantiva y de superación de la pobreza en los territorios urbanos.', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(418, 'Fortalecimiento de la economía campesina y productiva', 'Se busca fortalecer la economía rural y popular como base del desarrollo, sin descuidar el aparato productivo general ni el sector empresarial.', '...el impulso a la economía campesina y popular, sin descuidar el conjunto del aparato productivo ni al sector empresarial.', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(419, 'Defensa del salario vital', 'El modelo económico incluye garantizar condiciones dignas de ingreso y protección para la población, especialmente frente a crisis.', 'Solidaridad y apoyo a las poblaciones damnificadas y en defensa del salario vital.', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(420, 'Transformación del modelo económico y social', 'Se propone cambiar las estructuras económicas que generan desigualdad, integrando reformas sociales profundas.', '...avanzar hacia una segunda etapa del cambio, capaz de profundizar las reformas, atacar las causas estructurales de los problemas nacionales...', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(421, 'Impuestos orientados a justicia social', 'No plantea una reforma tributaria detallada, pero sí deja claro que el sistema fiscal debe servir para reducir desigualdad y financiar la política social.', 'El centro de nuestro programa es la política social. ...avanzar hacia una segunda etapa del cambio, capaz de profundizar las reformas, atacar las causas estructurales de los problemas nacionales...', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(422, 'Fortalecimiento de la economía campesina y productiva', 'Se busca fortalecer la economía rural y popular como base del desarrollo, sin descuidar el aparato productivo general ni el sector empresarial.', '...el impulso a la economía campesina y popular, sin descuidar el conjunto del aparato productivo ni al sector empresarial.', 4, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(423, 'Revolución agraria para transformar el campo', 'Propone una transformación profunda del campo colombiano, superando la reforma agraria tradicional, con cambios estructurales en la distribución de la tierra y el modelo rural.', 'Vamos con la revolución agraria.', 4, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(424, 'Profundización de la reforma agraria existente', 'No se limita a continuar la reforma agraria, sino que plantea llevarla a un nivel más profundo, con organización campesina y movilización social.', 'De la reforma agraria a la revolución agraria con la organización y movilización del campesinado.', 4, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(425, 'El agua como derecho central del desarrollo rural', 'El acceso al agua es planteado como un elemento clave para el desarrollo agrario, la productividad y la vida digna en el campo.', 'El acceso al agua como eje de la revolución agraria.', 4, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(426, 'Protagonismo del campesinado en la transformación rural', NULL, '...con la organización y movilización del campesinado.', 4, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(427, 'Los territorios como eje del desarrollo nacional', 'El programa propone que el desarrollo del país debe construirse desde los territorios, reconociendo su diversidad, riqueza humana y natural, y superando el centralismo.', 'La revolución de los territorios de Colombia, el corazón vivo de nuestra riqueza humana y natural.', 14, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(428, 'Defensa de la soberanía sobre el territorio', 'Se plantea fortalecer el control y la protección del territorio nacional frente a intereses externos o dinámicas que lo afecten.', 'Por la soberanía de nuestro territorio.', 14, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(429, 'Desarrollo sostenible desde las regiones', 'El desarrollo debe adaptarse a las características de cada región, promoviendo sostenibilidad y equilibrio entre economía, sociedad y naturaleza.', 'Por el desarrollo territorial sostenible de la puerta de la Amazonía.', 14, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(430, 'Reconocimiento de pueblos y diversidad regional', 'Se reconoce la importancia de los pueblos indígenas y otras comunidades en la construcción territorial del país.', 'Hacia nuevos logros en el reconocimiento de los pueblos indígenas.', 14, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(431, 'Reconocimiento de pueblos y diversidad regional', 'Se reconoce la importancia de los pueblos indígenas y otras comunidades en la construcción territorial del país.', 'Hacia nuevos logros en el reconocimiento de los pueblos indígenas.', 7, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(432, 'Desarrollo sostenible desde las regiones', 'El desarrollo debe adaptarse a las características de cada región, promoviendo sostenibilidad y equilibrio entre economía, sociedad y naturaleza.', 'Por el desarrollo territorial sostenible de la puerta de la Amazonía.', 14, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(433, 'Los territorios como eje del desarrollo nacional', NULL, NULL, 14, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(434, 'La naturaleza como eje del proyecto de país', 'El programa plantea que la protección de la naturaleza es central para el desarrollo, entendiendo a Colombia como una \'potencia de la vida\'.', 'Somos la fuerza de la vida y de la naturaleza.', 15, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(435, 'Justicia ambiental y derechos de los animales', 'Se propone una visión de justicia ambiental que incluye tanto la protección de ecosistemas como el bienestar animal.', 'Por los animales y por la justicia ambiental.', 15, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(436, 'Superación de modelos que depredan la naturaleza', 'El programa critica el modelo económico que ha depredado el medio ambiente, lo que sugiere un cambio frente al extractivismo tradicional.', 'Al mismo tiempo, hemos depredado la naturaleza y puesto en riesgo la inmensa biodiversidad que forma parte esencial de lo que somos.', 15, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(437, 'Transición desde el modelo extractivo de hidrocarburos', 'No hay una propuesta explícita sobre petróleo o gas, pero el enfoque ambiental y la crítica al extractivismo sugieren una transición progresiva fuera de la dependencia de hidrocarburos.', '...hemos depredado la naturaleza y puesto en riesgo la inmensa biodiversidad...', 6, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(438, 'Impulso a un modelo energético sostenible', 'El enfoque en sostenibilidad, biodiversidad y transformación del modelo productivo implica una orientación hacia energías limpias.', NULL, 9, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(439, 'Igualdad real y superación de la pobreza', 'El programa plantea una política de igualdad sustantiva que no solo reduzca brechas formales, sino que transforme las condiciones reales de vida, especialmente en territorios urbanos.', 'Hacia una política de igualdad sustantiva y de superación de la pobreza en los territorios urbanos.', 7, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(440, 'Garantía de derechos a través de la política social', 'Los derechos sociales (salud, educación, bienestar) son el eje central del programa y del modelo de desarrollo.', 'El centro de nuestro programa es la política social.', 7, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(441, 'Inclusión de sectores marginados', 'Se busca integrar plenamente a comunidades que han sido excluidas: pueblos indígenas, afrodescendientes, campesinos y sectores populares.', '...las luchas de las víctimas, de las mujeres, de la juventud, de los pueblos indígenas, afrodescendientes y campesinos...', 7, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(442, 'Lucha antirracista y desarrollo de comunidades afro', 'El programa incorpora una visión antirracista y propone desarrollo territorial para comunidades afrodescendientes.', 'La rebelión antirracista y el desarrollo de Tumaco.', 7, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(443, 'Seguridad humana como base del modelo de seguridad', NULL, 'El programa redefine la seguridad más allá del orden público o lo militar, enfocándola en la protección de la vida, los derechos y las condiciones dignas de las personas.', 5, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(444, 'Seguridad a través de la garantía de derechos', 'La seguridad no se logra solo con fuerza pública, sino reduciendo pobreza, desigualdad y exclusión.', '...superar la pobreza y garantizar derechos...', 5, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(445, 'Seguridad como resultado de la paz', 'La seguridad está directamente relacionada con la construcción de paz y el fin de la violencia estructural.', NULL, 5, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(446, 'Enfoque desde la paz (no desde guerra contra drogas)', 'El narcotráfico se trataría indirectamente dentro de la política de paz, no como política criminal autónoma.', NULL, 5, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(447, 'No intervención y defensa de la paz regional', 'Se opone a acciones militares extranjeras en América Latina, especialmente en contextos como Venezuela.', 'Se opone a acciones militares extranjeras en América Latina, especialmente en contextos como Venezuela.', 12, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(448, 'Relación con EE. UU. basada en soberanía', NULL, NULL, 12, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(449, 'Soberanía y No Subordinación ante Potencias Extranjeras', 'Iván Cepeda propone una política de \'no alineamiento\' subordinado. Plantea que Colombia debe dejar de actuar bajo los intereses de potencias extranjeras para recuperar su autonomía. Esto incluye la revisión de tratados internacionales que afecten la producción nacional y una postura crítica frente a las imposiciones externas, defendiendo que Colombia no sea tratada como un \'patio trasero\'.', 'Nuestra política exterior dejará de ser un instrumento de confrontación para convertirse en una diplomacia para la paz y la vida. Colombia no volverá a ser el claver de los intereses de potencias extranjeras en la región, ni se alineará con bloques que promuevan la guerra. Reivindicamos nuestra autonomía y soberanía para dialogar con todas las naciones del mundo bajo principios de respeto mutuo. El Poder de la Verdad nos guía para decir con firmeza que Colombia no es el patio trasero de nadie, sino una nación digna que construye su propio destino. No aceptaremos imposiciones que vulneren nuestra soberanía económica o ambiental.', 12, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(450, 'Revisión de Tratados Comerciales y Protección Industrial', 'Propone la renegociación de tratados internacionales, con énfasis en el TLC con Estados Unidos, para frenar la importación masiva de productos que compiten de forma desleal con la industria y el agro nacional, buscando proteger la estabilidad de las empresas y productores colombianos.', 'Vamos a revisar o a renegociar los tratados comerciales, comenzando por el TLC con Estados Unidos, para impedir la importación indiscriminada de productos como la leche en polvo que arruina la producción nacional y el sustento de miles de familias productoras en nuestro país. La soberanía nacional empieza por proteger lo que producimos. Ejerceremos una diplomacia soberana que no acepte imposiciones que vulneren nuestra soberanía económica o ambiental; revisaremos los tratados y acuerdos internacionales que lesionen la producción nacional o el bienestar de nuestros trabajadores', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(451, 'Estado Comprador y Estabilización de Mercados', 'Plantea una intervención directa del Estado en la economía para actuar como comprador principal de la producción de pequeños y medianos empresarios del campo. El objetivo es eliminar la intermediación abusiva y asegurar que las empresas rurales tengan un mercado garantizado con precios que cubran sus costos y generen utilidad.', 'Necesitamos encontrar solución pronta para que la leche que se hace en este territorio pueda ser procesada aquí mismo y para que no se vaya a desperdiciar ni un solo litro, puesto que en Colombia todavía tenemos un gran problema y es que no ha desaparecido el hambre... Así que la leche que se produce aquí podría alimentar a muchos hogares en Colombia y es necesario que estudiemos, que el Gobierno y el Estado compre a los productores a precios justos lo que están produciendo aquí en este territorio, para entregarlo a otras familias en otros territorios.', 3, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(452, 'Educación Superior Pública y Territorializada', 'Propone fortalecer el acceso a la educación básica, media y superior en regiones históricamente olvidadas, como La Guajira, integrando la ciencia y el conocimiento en la transformación de los territorios. Incluye un enfoque especial en la educación intercultural para pueblos indígenas.', 'Fortalecer el acceso a la educación básica media y a la educación superior para que la juventud de La Guajira pueda participar con el conocimiento y la ciencia en la transformación del territorio para el bien de todo el pueblo guajiro. Vamos a fortalecer la universidad del pueblo Wayuu para que los jóvenes de los pueblos indígenas puedan educarse en su sistema de conocimiento y de visión del mundo.', 10, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(453, 'Educación como Pilar de la Revolución Ética', 'Plantea que la educación debe ser el vehículo para una \'Revolución Ética\' que transforme la conciencia colectiva, promoviendo la empatía, el pensamiento crítico y el respeto por la vida frente a décadas de violencia y deshumanización.', 'Una revolución que no se limite a denunciar estas formas de deshumanización, sino que transforme de raíz nuestra conciencia individual y colectiva. Una revolución que nos lleve hacia una nueva cultura política y social, profundamente sensible ante la vida, el sufrimiento y la dignidad de los demás... Son ellas las víctimas quienes pueden reactivar la conciencia colectiva, poner en evidencia la verdad silenciada y, sobre todo, recordarnos que la vida humana jamás debe ser negociable.', 10, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(454, 'Prioridad del Gasto Público: De lo Privado a lo Público', 'Iván Cepeda plantea que los recursos del Estado deben destinarse exclusivamente al fortalecimiento de la infraestructura y calidad de las universidades públicas. Esto implica poner fin a los programas que transfieren fondos públicos a universidades privadas, buscando que el presupuesto nacional garantice la gratuidad total en el sistema estatal en lugar de subsidiar cupos en instituciones privadas.', 'Poner fin a la transferencia de recursos públicos a las universidades privadas. Los recursos del Estado deben fortalecer la base presupuestal de las universidades públicas, garantizando la gratuidad y la excelencia académica en todo el territorio nacional, especialmente en las zonas históricamente excluidas. No seguiremos financiando la educación privada con recursos que le pertenecen al sistema público', 10, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(455, 'Centro de Ciencia e Innovación Tecnológica para Buenaventura y el Pacífico', 'Cepeda propone crear un centro de ciencia e innovación tecnológica en Buenaventura, señalando que la ciudad carece de este tipo de institución pese a su potencial. Argumenta que Colombia debe dejar de ser un país con débil desarrollo científico y que el Pacífico puede liderar la investigación científica y tecnológica nacional.', 'Buenaventura nos ha dado uno de los más destacados científicos que tenemos en el país, Raúl Cuero; sin embargo, no cuenta con un centro de ciencia e innovación tecnológica que impulse la producción de conocimiento para resolver sus propios problemas y contribuir a superar los grandes desafíos de la humanidad. Colombia no puede seguir siendo un país sin ciencia, sin tecnología o con débil o muy débil desarrollo científico, debemos corregir esto y el Pacífico es una región que puede encabezar el desarrollo de la investigación científica y tecnológica en Colombia. Debemos impulsarlo.', 13, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(456, 'Impulso a la innovación tecnológica en las economías populares afro', 'Como parte de las 14 acciones para Buenaventura, propone inversión estatal dirigida a las economías populares afrodescendientes en sectores que incluyen la innovación tecnológica y los servicios, junto con turismo y gastronomía.', 'Inversión real y estratégica en las economías afro en el Pacífico y en todo el país. Impulso estatal a las economías populares afro en turismo, gastronomía, innovación tecnológica y servicios.', 13, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(457, 'Ciencia y tecnología en la Amazonía como alternativa al reclutamiento juvenil', 'En el contexto del desarrollo territorial sostenible de la puerta de la Amazonía (Caquetá), Cepeda propone fortalecer la Universidad de la Amazonía y apostar por ciencia y tecnología como alternativa real para los jóvenes, evitando su reclutamiento por grupos armados.', 'Vamos a cuidar los recursos de la gente para poner esos recursos al servicio del desarrollo y del bienestar del pueblo colombiano, al servicio de la educación, necesitamos fortalecer la Universidad de la Amazonía para que haya ciencia, tecnología, para que los jóvenes no sigan siendo reclutados por los grupos armados, y puedan convertirse en científicos y científicas que ayuden al desarrollo social, cultural, económico de esta región tan importante y estratégica para el país.', 13, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(458, 'Reforma democrática al sistema de salud — Revertir la privatización de la Ley 100', 'Esta propuesta plantea una transformación profunda del modelo de salud en Colombia, enfocándose en eliminar la intermediación financiera privada impuesta por la Ley 100 de 1993. El objetivo es recuperar la administración pública de los recursos y garantizar que el acceso a la salud sea un derecho fundamental efectivo y universal, gestionado directamente por el Estado y con una fuerte base en la atención primaria y preventiva.', 'En el centro de nuestra propuesta de Revolución Social, impulsaremos la reforma democrática al sistema de salud para revertir de manera definitiva el modelo de privatización y de intermediación financiera impuesto por la Ley 100. La salud dejará de ser una mercancía para convertirse en un derecho humano fundamental garantizado por el Estado. Esto implica el fortalecimiento de la red pública de hospitales, la eliminación de las barreras de acceso creadas por las EPS, y la implementación de un modelo de atención primaria, preventiva y territorializada, que llegue a todos los rincones del país, especialmente a las zonas rurales y marginadas que han sido históricamente excluidas', 16, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(459, 'Reforma y Fortalecimiento del Sistema de Salud', 'Propone profundizar la transición hacia un modelo de salud que garantice el derecho fundamental de manera universal, reformando las estructuras actuales para priorizar la atención y eliminar la intermediación que afecta la prestación del servicio.', 'Vamos a garantizar el fortalecimiento y la reforma del sistema de salud e implementar el sistema indígena de salud propio e intercultural', 16, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(460, 'Enfoque de salud pública para el consumo de sustancias', NULL, NULL, 16, 5, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(461, 'Dignificación y Formalización del Talento Humano', 'Plan para eliminar la contratación por prestación de servicios en el sector salud, garantizando estabilidad laboral, pagos oportunos de nóminas atrasadas y protección jurídica para los profesionales.', 'Nuestra labor será dignificar estas profesiones, pasar de contratos de prestación de servicios y las garantías laborales, eliminar la tramitomanía y las barreras administrativas. El milagro de recuperar la salud será posible con nuestro plan de choque: a partir del 8 de agosto de 2026 redestinaré $4 BILLONES para el pago de nóminas y contratos de prestación de servicios atrasados; garantizaré el pago oportuno y trazable al talento en salud. El Estatuto del Talento Humano en Salud permitirá estabilidad, formalización de funciones, criterios de remuneración y protección jurídica del ejercicio profesional.', 16, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(462, 'Atención Prioritaria a Pacientes Crónicos y de Alto Costo', 'Inyección de recursos específicos para retomar y asegurar la continuidad de los tratamientos para personas con cáncer, enfermedades huérfanas y condiciones crónicas.', '$1,5 BILLONES para reactivar urgentemente los tratamientos de pacientes crónicos, oncológicos y de enfermedades huérfanas.', 16, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(463, 'Saneamiento de Deudas y Entrega Domiciliaria de Medicamentos', 'Pago a proveedores de insumos médicos y cambio en el modelo de logística para que los medicamentos lleguen directamente al hogar del paciente, combatiendo el desabastecimiento', 'Regresar a las épocas en las que recibían a tiempo sus medicamentos, y en la puerta de su casa!, por hoy, el 80 % de los enfermos no reciben sus fórmulas médicas a tiempo. $1,5 BILLONES para saldar deudas con proveedores de medicamentos e insumos esenciales, y llevaremos A LA CASA DEL PACIENTE ENFERMO esos medicamentos represados.', 16, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(464, 'Restablecimiento del Flujo Financiero (UPC y Presupuestos Máximos)', 'Fortalecimiento del sistema mediante el pago y ajuste de la Unidad de Pago por Capitación (UPC) y los Presupuestos Máximos para asegurar la operatividad de las entidades de salud.', NULL, 16, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(465, 'Plan Nacional de Becas para Especializaciones Médicas', 'Programa de becas integrales que cubren matrícula y manutención para médicos que deseen especializarse, con el compromiso de ejercer en zonas vulnerables o de alta necesidad.', 'Mientras que con el Plan Nacional de Becas para Especializaciones Médicas cubriremos matrícula, manutención y gastos asociados; los beneficiarios deberán prestar su servicio en la zona donde más se necesite.', 16, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(466, 'Innovación Tecnológica y Agencia Nacional de Compras', 'Implementación de herramientas digitales avanzadas (IA, Blockchain) para la auditoría de cuentas y creación de un ente centralizado para la compra eficiente de medicamentos.', 'Implementaré tecnologías avanzadas al servicio del paciente y el profesional, Inteligencia Artificial, Big Data y Blockchain para depurar cuentas, resolver glosas en plazos definidos, evitar acumulación crónica de deudas y le daré vida a la Agencia Nacional de Compras para medicamentos esenciales y de sofisticación.', 16, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(467, 'Ordenamiento Productivo y Zonificación', 'Creación y aplicación obligatoria del Mapa Nacional de Zonificación Agrícola, Pecuaria y Forestal para optimizar la productividad, reducir pérdidas y orientar la inversión pública en infraestructura y logística.', 'El ordenamiento productivo; la misión es ser más productivos y tener menos pérdidas gracias al Mapa Nacional de Zonificación Agrícola, Pecuaria y Forestal, liderado por la Unidad de Planificación Rural Agropecuaria. Esta es una herramienta con la que se puede definir qué producir, dónde y cuándo, y será obligatoria para orientar inversiones públicas en vías, riego, electrificación y logística y podremos implementarla a través de la cofinanciación Nación–territorios y participación de gremios y la UMATA.', 4, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(468, 'Educación y Emprendimiento Rural', 'Implementación de un programa piloto junto al SENA en 50 municipios pequeños para capacitar a una nueva generación de agricultores en técnicas modernas y competitividad empresarial.', 'La segunda base sobre la que cosecharemos el desarrollo será la educación y el emprendimiento rural que tendrá efectos directos en productividad, inclusión, arraigo territorial y reducción del subdesarrollo rural. Con el SENA iniciaré un programa piloto en 50 municipios con una población menor a 30.000 habitantes para formar una nueva generación de agricultores emprendedores, tecnificados y competitivos.', 4, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(469, 'Innovación y Desarrollo Científico Agrario', 'Alianza con centros de investigación y Agrosavia para aplicar biotecnología, agricultura de precisión y mejoramiento genético, buscando cultivos más resistentes y nuevas industrias como bioinsumos.', 'La innovación y el desarrollo. Porque es necesario que entendamos que es hora de tener una base científica para ser competitivos con los líderes agrícolas del mundo. Los centros de investigación gremial (CENI) y Agrosavia serán nuestros aliados para multiplicar recursos para mejoramiento genético, biotecnología, semillas élite, agricultura de precisión y sanidad agropecuaria. Solo así haremos el milagro de desarrollar cultivos resistentes a sequías, plagas y enfermedades, reducir agroquímicos, aumentar rendimientos y abrir nuevas industrias como biopolímeros, bioinsumos y agrofarma.', 4, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(470, 'Financiamiento de Fomento y Crédito Ágil', 'Modernización del sistema crediticio de Finagro para ofrecer préstamos con tasas del 8,7 % anual, procesos digitales simplificados y garantías del Estado de hasta el 80 %.', 'Financiamiento de fomento. Es decir, modernizaré el sistema crediticio mediante una gobernanza técnica en la Comisión Nacional de Crédito Agropecuario (CNCA) y la ampliación de la inversión obligatoria en Títulos de Desarrollo Agropecuario. Abriré la posibilidad de créditos con tasas del 8,7 % anual, plazos competitivos y garantías estatales hasta el 80 %. Voy a simplificar la normatividad de Finagro, digitalizar procesos y articular crédito con ordenamiento y tecnología.', 4, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(471, 'Seguridad Jurídica y Titulación de la Propiedad Rural', 'Formalización de la propiedad rural a través de un programa masivo de titulación de predios para brindar estabilidad a los proyectos de los campesinos.', 'Y para darle solidez a nuestros proyectos, voy a fomentar la seguridad jurídica a la propiedad rural. La historia no puede seguir siendo la misma. La Reforma Agraria sigue inconclusa, pero nosotros sí haremos el milagro y vamos a titular sus predios.', 4, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(472, 'Uso Eficiente y Tecnificación de Suelos', 'Propuesta para aprovechar las 400 especies nativas y la biodiversidad mediante tecnología de punta para alimentar al país y exportar.', 'Tenemos una tierra supremamente productiva: más de 400 especies nativas de frutales comestibles... Lo que necesitamos es darle un uso eficiente a los suelos, tecnificar los procesos, implementar tecnología de punta y lo que vamos a tener es un milagro productivo con el que vamos a poder alimentar tres veces al día a más de 50 millones de colombianos y tener alimentos para exportar.', 4, 6, '2026-05-18 16:48:24', '2026-05-18 16:48:24', NULL),
(473, 'Matar el Hambre: Alianza por la Nutrición', 'Una estrategia para erradicar la desnutrición mediante la tecnificación del campo y alianzas con la empresa privada para asegurar tres comidas diarias a los colombianos.', 'Matando el hambre vamos a erradicar la desnutrición y garantizar tres comidas al día. No es posible que en un país como Colombia con tierra tan fértil, la gente se siga acostando sin comer. Por ello: fomentaré alianzas entre los agricultores y la empresa privada y el beneficio será la reducción de impuestos a los empresarios, lo que representará mejores sueldos a los trabajadores y calidad de vida para las familias.', 7, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(474, 'Colombia País de Propietarios', 'Programa de acceso a vivienda propia específicamente diseñado para mujeres, con tasas de interés mínimas y plazos extendidos.', 'Haremos el milagro de poner en marcha el programa Colombia país de propietarios, en el que mujeres como ustedes podrán tener su casa propia con créditos al 2 % anual por 30 años.', 7, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(475, 'Programa Pase Mi Cultura', 'Entrega de una billetera virtual a jóvenes que cumplen la mayoría de edad para incentivar el consumo de libros, cine y teatro.', 'El primero, hacer el lanzamiento del programa Pase Mi Cultura, que busca entregar billeteras virtuales a jóvenes que cumplen la mayoría de edad para que la utilicen en compra de libros, entradas a cine, teatro, musicales, entre otros. La idea es que los nuevos ciudadanos se conviertan en audiencias activas que moldeen nuestra cultura y dinamicen estos sectores de la economía. La partida será de $120.000 millones anuales.', 7, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(476, 'Régimen Especial para el Ecosistema Digital', 'Marco legal con exenciones totales de impuestos y trámites simplificados para jóvenes emprendedores en tecnología, marketing e IA.', 'Para todos ellos crearé un régimen especial con exenciones totales, declaraciones de renta ultra simplificada para quienes facturen hasta $400 millones al año; deducción 100 % en inversiones en compras en equipos, Internet, cursos de capacitación, créditos de hasta $150 millones para equipos de tecnología con 0 % interés; internet fibra ilimitada, coworking, mentoría de élite y matchmaking.', 8, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(477, 'Régimen Empresarial Permanente para Creadores', 'Formalización de 20,000 unidades productivas creativas mediante un sistema de tributación simplificada y reducción de cargas iniciales.', 'A través de Acción Cultural vamos a generar un nuevo régimen empresarial permanente y especial para los creadores. El objetivo es hacer una tributación simplificada, con reducción de cargas iniciales (renta reducida) o permanentes (retefuente ajustado a la dinámica del sector), con incentivos a inversión cultural... Nuestra meta es formalizar 20.000 unidades productivas creativas en cuatro años.', 8, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(478, 'Incentivos Tributarios por Alianzas Agrarias', 'Reducción de impuestos para empresarios que se vinculen con el sector campesino para mejorar la productividad alimentaria.', 'Fomentaré alianzas entre los agricultores y la empresa privada y el beneficio será la reducción de impuestos a los empresarios, lo que representará mejores sueldos a los trabajadores y calidad de vida para las familias.', 8, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(479, 'Apoyo al Emprendedor y Círculo Virtuoso', 'Fortalecimiento de las empresas existentes mediante una visión donde el éxito del emprendedor garantiza salarios dignos y estabilidad para el trabajador.', 'Apoyar al emprendedor es apoyar al trabajador porque los emprendedores son generadores de riqueza, desarrollo y estabilidad para la nación. Y el círculo virtuoso nos invita a pensar que un emprendimiento estable ofrece salarios dignos, salarios dignos hacen trabajadores entusiastas y estos, a su vez, cumplen metas laborales que llevan a las empresas a ser estables... no creando empresas de manera desesperada, sino fortaleciendo las que ya tenemos.', 8, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(480, 'Alivio de Cargas y Digitalización Empresarial', 'Reducción de impuestos para el sector productivo, eliminación de trámites burocráticos y digitalización total de procesos para mejorar la competitividad.', 'Como emprendedor tengo claro que nos asfixia por eso, sé que hay que bajar las cargas impositivas, eliminar la tramitomanía, hacer procesos más digitales. Pero sobre todo, desterrar la corrupción porque mientras nosotros trabajamos, otros se roban nuestro esfuerzo.', 8, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(481, 'Acción Creadora en Foncultura', 'Inyección de $500.000 millones para financiar 5,000 emprendimientos creativos mediante capital semilla y coinversión.', 'La creación de la línea Acción Creadora en Foncultura que permitirá la financiación de cinco mil emprendimientos y proyectos creativos durante los cuatro años de mandato a través de CoCrea. Con $500.000 millones, generaremos instrumentos como capital semilla, coinversión público-privada, garantías financieras y convocatorias ágiles con menos trámites.', 3, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(482, 'Desarrollo del HUB GAMER LatAm', 'Inversión en infraestructura tecnológica para posicionar a Colombia como líder regional en la industria del software, hardware y videojuegos.', 'Vamos a desarrollar infraestructura en el país para convertirnos en el HUB GAMER más importante de LatAm. Esto nos permitirá transformar la economía en sectores como la industria del software y el hardware, el emprendimiento y el empleo juvenil, la economía digital y las exportaciones.', 3, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(483, 'Capitalismo Popular y Ciudadano-Accionista', 'Implementación de un modelo donde los ciudadanos dejen de ser solo consumidores para convertirse en copropietarios de las empresas a través de acciones, bonos e instrumentos de propiedad.', 'Nuestro milagro gira en torno al capitalismo popular que busca que el ciudadano-accionista sea co-propietario real de acciones, participaciones, bonos o instrumentos de propiedad... Buscaremos que el ciudadano sea accionista productivo, no solo consumidor, beneficiario o contribuyente.', 3, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(484, 'Plan Colombia Exportadora y Soberanía Económica', 'Estrategia nacional para transitar hacia una economía de eficiencia enfocada en las exportaciones y la soberanía financiera.', 'Pasaremos de la economía del corrupto a la economía de la eficiencia y la exportación... Con el Plan Colombia Exportadora y Soberanía Económica, vamos a lograr el milagro, porque el objetivo no es solo traer crecimiento económico sino transformar ese crecimiento en estabilidad social y prosperidad sostenible.', 3, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(485, 'Conectividad, Navegabilidad y Suelos', 'Inversión masiva en vías, recuperación de la navegabilidad del Río Magdalena y otorgamiento de licencias para la explotación sostenible del suelo.', 'Colombia necesita obras con transparencia, inversión en infraestructura vial, navegabilidad del río Magdalena, corredores seguros, licencias de exploración y explotación sustentable y sostenible de los suelos, alianzas internacionales justas para que conozcan nuestra talentosa mano de obra.', 11, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(486, 'Anclaje Territorial y Cierre de Brechas', 'Estrategia para que la participación ciudadana en las empresas legitime su presencia en las regiones y se logre una redistribución para cerrar las brechas económicas entre los territorios.', 'Que su participación ancle la empresa en el territorio y le otorgue legitimidad social y política, que aporte ahorro productivo y paciente... Eso incluye de manera inexorable el respeto a la libre empresa, la redistribución de brechas regionales, megaproyectos productivos, inserción de cadenas de valor estratégicas globales, especialmente en la bioeconomía.', 14, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(487, 'Política de No Negociación y Sometimiento', 'Rechazo al modelo de \'Paz Total\' y establecimiento de la premisa de que la paz no es objeto de negociación, sino el resultado del sometimiento de los criminales a la autoridad.', 'El punto de partida es saber que la paz no se negocia. Ya vimos los resultados de un gobierno inoperante que pensó que con la Paz Total lograría desterrar a los bandidos y lo único que logró fue posicionarlos. La Paz Total no será una opción porque el milagro de vivir tranquilos solo es posible si sometemos a los criminales, garantizamos mayor pie de fuerza, garantías y respaldo para nuestros héroes.', 2, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(488, 'Acciones de Choque y Puestos de Mando Unificado (PMU)', 'Implementación de un plan de 90 días para capturar cabecillas regionales, reactivación de la erradicación con bioherbicidas y creación de centros de control operativo departamental.', 'En los primeros 90 días de mi gobierno implementaré acciones de choque que permitan capturar diez cabecillas de alto valor por cada región; iniciaré la aspersión con bioherbicidas para acabar con la invasión de cultivos ilícitos; pondré en acción Puestos de Mando Unificado en cada departamento para hacer control de los resultados operativos.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(489, 'Alianzas Estratégicas e Inteligencia Militar', 'Retorno a la cooperación militar y tecnológica con Estados Unidos e Israel para fortalecer la inteligencia y el armamento de las fuerzas nacionales.', 'Es necesario regresar a las alianzas estratégicas con Estados Unidos y el Estado de Israel para recuperar la inteligencia militar, la tecnología de las armas. De esta manera podremos lograr cinco objetivos específicos que tiene que ver con el control territorial... la modernización de las capacidades de la fuerza pública.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(490, 'Autoridad Democrática y Operaciones de Precisión', 'Fortalecimiento del pie de fuerza y uso de bombardeos tácticos de alta precisión contra campamentos criminales para desmantelar estructuras delictivas.', 'Debemos pasar de la carreta a los resultados a través de cinco enfoques claros: Autoridad democrática, legalidad y Derechos Humanos; resultados MEDIBLES, enfoque en desmonte de economías criminales, dirección civil, ejecución militar y una cooperación internacional PRAGMÁTICA. bombardeamos los campamentos que tengamos que bombardear con absoluta precisión y con inteligencia para garantizar la menor pérdida de vidas humanas y en especial de menores de edad.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(491, 'Objetivos de Control Territorial y Blindaje Institucional', 'Enfoque en la reducción de delitos de alto impacto (homicidio, extorsión, secuestro) y protección de las instituciones frente a la influencia política.', 'De esta manera podremos lograr cinco objetivos específicos que tiene que ver con el control territorial, la reducción del homicidio, la extorsión y el secuestro; el desmantelamiento TOTAL de las estructuras delictivas, la modernización de las capacidades de la fuerza pública y el blindaje a las instituciones de la politización.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(492, 'Cadena Perpetua para Violadores y Violentadores', 'Endurecimiento radical de las penas para quienes agredan físicamente a mujeres o menores de edad.', 'También impulsaré un proyecto para que cualquier persona que toque o violente a una mujer o a un menor de edad, pague cadena perpetua. No lo hago como un favor o como lo hacen los populistas; lo hago como una obligación moral.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(493, 'Creación del Bloque Anticorrupción Presidencial', 'Establecimiento de una fuerza de tarea de mando directo presidencial para perseguir redes criminales, bienes y capitales producto del saqueo estatal, integrando diversas agencias de inteligencia y control de forma unificada.', 'Al año se pierden en Colombia $70 billones por corrupción. Por eso uno de los ejes centrales de mi propuesta de gobierno es la creación de un bloque anticorrupción, con mando directo desde la Presidencia de la República, que funcione como una estructura operativa diseñada para perseguir el dinero, los bienes y las redes de quienes se benefician del saqueo al Estado y con ello afectan al pueblo. Con un Bloque Anticorrupción, que funcione como una fuerza de tarea permanente, buscaremos a estos delincuentes. Esto será posible a través de las entidades que hoy actúan de manera fragmentada, por lo que será necesario unir inteligencia financiera, inteligencia operativa, investigación penal, control fiscal y sanción disciplinaria bajo una sola estrategia.', 1, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL);
INSERT INTO `proposals` (`id`, `title`, `summary`, `full_text`, `category_id`, `candidate_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(494, 'Integración de Inteligencia y Control (Ciclo del Delito)', 'Coordinación de la UIAF, Policía, Ejército, Fiscalía, Procuraduría y Contraloría para rastrear movimientos sospechosos, ejecutar judicializaciones penales y asegurar la recuperación de recursos públicos.', 'El bloque estaría conformado por la Unidad de Información y Análisis Financiero (UIAF), que se encarga de rastrear movimientos sospechosos de dinero y detectar enriquecimientos injustificados; inteligencia de la Policía Nacional, para labores operativas y de investigación en terreno. También tendremos en este grupo inteligencia del Ejército, especialmente cuando existan vínculos con economías criminales o estructuras armadas; la Fiscalía General de la Nación, responsable de la judicialización penal; la Procuraduría General, para sanciones disciplinarias contra funcionarios públicos; y la Contraloría General, enfocada en el control fiscal y la recuperación de recursos. La lógica es cubrir todo el ciclo del delito: desde la detección del dinero hasta la sanción y la recuperación de bienes.', 1, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(495, 'Extinción de Dominio Acelerada y Ataque al Patrimonio', 'Enfoque operativo centrado en despojar a los corruptos, testaferros y familiares de sus bienes para eliminar el incentivo económico del robo al Estado mediante procesos legales rápidos.', 'El eje operativo del bloque es atacar el patrimonio de los corruptos porque las condenas tardías o las sanciones simbólicas no disuaden a nadie si los bienes permanecen intactos. Por eso la propuesta es una extinción de dominio acelerada, orientada no solo a los funcionarios corruptos, sino también a testaferros y entornos familiares que se benefician del delito. La idea es romper el incentivo económico: que robarle al Estado y al pueblo deje de ser rentable.', 1, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(496, 'Tecnología y Rastreo Internacional de Activos', 'Uso de herramientas tecnológicas para el cruce masivo de datos financieros y establecimiento de cooperación internacional para recuperar capitales fugados al exterior.', 'Otro componente clave es el uso intensivo de tecnología para cruzar información financiera, patrimonial y contractual. En la medida en que el dinero corrupto suele moverse fuera del país, el bloque también contemplaría cooperación internacional para rastrear activos y cerrar rutas de fuga de capitales. El enfoque es pragmático: seguir el rastro del dinero, sin importar dónde termine.', 1, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(497, 'Rescate de Ecopetrol y Reposición de Reservas', 'Despolitización de la estatal petrolera mediante una dirección técnica avalada por inversionistas, con el objetivo de reponer reservas por encima del 120 %.', 'Tercero, voy a rescatar a Ecopetrol de la politiquería porque este es el patrimonio de nuestros hijos. Convocaré una Asamblea Extraordinaria inmediata, nombraré un presidente técnico y avalado por inversionistas institucionales. Ecopetrol regresa a los mercados públicos de valores con fuerza, despolitizada y enfocada en reponer reservas con una meta superior al 120 %.', 6, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(498, 'Implementación de Fracking con Monitoreo Científico', 'Uso de fracturación hidráulica mediante pilotos integrales para reducir los costos industriales derivados de la importación de gas.', 'Cuarto. El fracking es una realidad porque importar gas sube el costo industrial un 45 %. Usaremos Pilotos Integrales con monitoreo científico de clase mundial y el gas en el subsuelo colombiano se usará para nuestro bienestar.', 6, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(499, 'Reactivación de la Exploración y Producción de Hidrocarburos', 'Lanzamiento de nuevas rondas de exploración en los primeros 90 días de gobierno para alcanzar una producción de 1,3 millones de barriles equivalentes.', 'Primero, visión y reindustrialización para que Colombia deje de exportar fósiles e innove con la exportación de valor agregado. Tenemos el potencial de producir 1,3 millones de barriles equivalentes, hoy desperdiciados por la desidia. En tres meses, Colombia ya estará haciendo su primera ronda de exploración de hidrocarburos.', 6, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(500, 'Seguridad Energética y Sala de Situación', 'Creación de un centro de monitoreo diario en la Presidencia para supervisar niveles de embalses y moléculas de gas, evitando apagones.', 'Segundo, le apostaré a la Seguridad Energética. Vine a recuperar el control, ya que la parálisis del actual gobierno nos dejó con reservas de gas solo para 5,9 años. Por ello, instalaremos una Sala de Situación Diaria en Presidencia para monitorear cada molécula de gas y cada embalse. Colombia no volverá a estar a oscuras.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(501, 'Plan Caribe: Reducción de Tarifas Eléctricas', 'Asunción de la deuda de $6 billones por parte del Estado para lograr una disminución inmediata en las facturas de energía de la región Caribe.', 'Quinto, la mirada al Caribe. El Estado debe responder por las deudas ($6B) con esta región para que pueda hacerse efectiva la disminución del valor de las facturas de inmediato.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(502, 'Precios Técnicos de Combustibles (Gasolina y ACPM)', 'Eliminación del componente de impuestos ideológicos (52 % del precio actual) para fijar el costo de los combustibles bajo parámetros puramente técnicos.', 'Sexto. El precio de la gasolina y el ACPM se fijará de acuerdo a parámetros técnicos, no políticos. El 52 % del precio, actualmente, equivale a impuestos; eliminaré el componente ideológico de los precios para aliviar el costo de vida.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(503, 'Reforma a las Leyes de Servicios Públicos y CREG', 'Modificación de las leyes 142 y 143 para asegurar que los comisionados de la CREG sean técnicos con periodos fijos y no nombramientos políticos.', 'Noveno. Someteré a una reforma profunda las leyes 142 y 143 para tener nombramientos de comisionados CREG por periodos fijos y técnicos y licenciamiento ambiental ágil para proyectos estratégicos de seguridad nacional.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(504, 'Lucha contra la Minería Ilegal y Formalización', 'Persecución frontal a la minería criminal que destruye ríos mediante un Escuadrón Especial, acompañada de una formalización masiva de pequeños mineros.', 'Octavo. Combatiré la minería ilegal, voy a formalizar de manera masiva al pequeño minero e iniciaré una persecución frontal con el Escuadrón Especial en contra del criminal que destruye ríos y extorsiona emprendedores. Defenderé el ambiente con autoridad, no con discursos.', 15, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(505, 'App Regalía Firme para Inversión Ambiental y Social', 'Redestinación de las regalías hacia proyectos de agua potable e infraestructura, permitiendo que el ciudadano audite los recursos mediante una aplicación.', 'Las regalías en 2024 sumaron $18 billones, en mi gobierno serán para el agua, las vías y los colegios, no para la burocracia. A través de la App Regalía Firme cada ciudadano podrá ser el interventor de su propia riqueza.', 15, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(506, 'Licenciamiento Ambiental Ágil', 'Agilización de los trámites de licencias ambientales y consultas previas para proyectos considerados de seguridad nacional.', 'Noveno. licenciamiento ambiental ágil para proyectos estratégicos de seguridad nacional. daré soluciones a la Consulta Previa y Licencias Ambientales.', 15, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(507, 'Salud: IA y Blockchain para la Transparencia', 'Aplicación de tecnologías de vanguardia para auditar las cuentas del sistema de salud, resolver glosas pendientes y evitar la acumulación de deudas mediante el seguimiento de datos en tiempo real.', 'Implementaré tecnologías avanzadas al servicio del paciente y el profesional, Inteligencia Artificial, Big Data y Blockchain para depurar cuentas, resolver glosas en plazos definidos, evitar acumulación crónica de deudas y le daré vida a la Agencia Nacional de Compras para medicamentos esenciales y de sofisticación.', 16, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(508, 'Agro: Biotecnología y Agricultura de Precisión', 'Alianza con centros científicos para implementar mejoramiento genético, semillas élite y agricultura de precisión, permitiendo desarrollar cultivos resistentes y nuevas industrias como bioinsumos.', 'Los centros de investigación gremial (CENI) y Agrosavia serán nuestros aliados para multiplicar recursos para mejoramiento genético, biotecnología, semillas élite, agricultura de precisión y sanidad agropecuaria. Solo así haremos el milagro de desarrollar cultivos resistentes a sequías, plagas y enfermedades, reducir agroquímicos, aumentar rendimientos y abrir nuevas industrias como biopolímeros, bioinsumos y agrofarma.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(509, 'Agro: Zonificación y Planificación Digital', 'Uso del Mapa Nacional de Zonificación como herramienta técnica y digital para determinar qué producir y dónde, optimizando la inversión pública en infraestructura.', 'El ordenamiento productivo; la misión es ser más productivos y tener menos pérdidas gracias al Mapa Nacional de Zonificación Agrícola, Pecuaria y Forestal, liderado por la Unidad de Planificación Rural Agropecuaria. Esta es una herramienta con la que se puede definir qué producir, dónde y cuándo.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(510, 'Startups: Régimen Especial para el Ecosistema Digital', 'Exenciones tributarias totales y créditos al 0 % de interés para emprendedores en IA, desarrollo de software y marketing digital, con el fin de fomentar la riqueza en sectores del siglo XXI.', 'Para todos ellos crearé un régimen especial con exenciones totales, declaraciones de renta ultra simplificada para quienes facturen hasta $400 millones al año; deducción 100 % en inversiones en compras en equipos, Internet, cursos de capacitación, créditos de hasta $150 millones para equipos de tecnología con 0 % interés; internet fibra ilimitada, coworking, mentoría de élite y matchmaking.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(511, 'Infraestructura: Colombia como HUB GAMER LatAm', 'Creación de infraestructura tecnológica de alto nivel para posicionar al país como líder en la industria global de videojuegos, software y hardware.', 'Vamos a desarrollar infraestructura en el país para convertirnos en el HUB GAMER más importante de LatAm. Esto nos permitirá transformar la economía en sectores como la industria del software y el hardware, el emprendimiento y el empleo juvenil, la economía digital y las exportaciones.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(512, 'Educación: Plataforma Nacional Universitaria Virtual', 'Implementación de una plataforma digital certificada y gratuita para ofrecer educación superior de calidad en todo el territorio nacional de forma remota.', 'Voy a respaldarlos con programas como la universidad en casa, una Plataforma Nacional de Educación Virtual Universitaria, certificada y gratuita.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(513, 'Corrupción: Inteligencia Financiera y Big Data', 'Cruce masivo de datos financieros y patrimoniales mediante tecnología para detectar el movimiento de capitales ilícitos y cerrar rutas de fuga de activos al exterior.', 'Uso intensivo de tecnología para cruzar información financiera, patrimonial y contractual. En la medida en que el dinero corrupto suele moverse fuera del país, el bloque también contemplaría cooperación internacional para rastrear activos y cerrar rutas de fuga de capitales.', 1, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(514, 'Energía: Sala de Situación y Monitoreo Digital', 'Creación de un centro de mando tecnológico en la Presidencia para supervisar en tiempo real los niveles de gas y embalses, garantizando la seguridad energética.', 'Instalaremos una Sala de Situación Diaria en Presidencia para monitorear cada molécula de gas y cada embalse. Colombia no volverá a estar a oscuras.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(515, 'Seguridad: Modernización y Tecnología Militar', 'Adquisición y desarrollo de tecnologías avanzadas de armamento e inteligencia estratégica mediante alianzas con líderes tecnológicos globales (Israel y EE. UU.).', 'Es necesario regresar a las alianzas estratégicas con Estados Unidos y el Estado de Israel para recuperar la inteligencia militar, la tecnología de las armas. De esta manera podremos lograr... la modernización de las capacidades de la fuerza pública.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(516, 'Alianzas Estratégicas de Seguridad e Inteligencia', 'Retorno a la cooperación militar y tecnológica de alto nivel con aliados tradicionales como Estados Unidos e Israel para fortalecer la inteligencia y capacidad de defensa nacional.', 'Es necesario regresar a las alianzas estratégicas con Estados Unidos y el Estado de Israel para recuperar la inteligencia militar, la tecnología de las armas. De esta manera podremos lograr cinco objetivos específicos que tiene que ver con el control territorial... la modernización de las capacidades de la fuerza pública.', 12, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(517, 'Cooperación Internacional contra la Corrupción', 'Uso de la diplomacia y acuerdos internacionales para rastrear, congelar y recuperar activos producto de la corrupción que hayan sido desviados fuera de las fronteras colombianas.', 'En la medida en que el dinero corrupto suele moverse fuera del país, el bloque también contemplaría cooperación internacional para rastrear activos y cerrar rutas de fuga de capitales. El enfoque es pragmático: seguir el rastro del dinero, sin importar dónde termine.', 1, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(518, 'Plan Colombia Exportadora y Alianzas Laborales', 'Estrategia de inserción en mercados globales a través de la bioeconomía y la promoción del talento nacional mediante acuerdos internacionales que reconozcan la mano de obra colombiana.', 'Eso incluye de manera inexorable el respeto a la libre empresa... inserción de cadenas de valor estratégicas globales, especialmente en la bioeconomía. alianzas internacionales justas para que conozcan nuestra talentosa mano de obra. Con el Plan Colombia Exportadora y Soberanía Económica, vamos a lograr el milagro.', 12, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(519, 'Liderazgo Regional: HUB GAMER de LatAm', 'Posicionamiento de Colombia como el principal centro de tecnología, software y videojuegos de América Latina para atraer inversión extranjera y fomentar exportaciones digitales.', 'Vamos a desarrollar infraestructura en el país para convertirnos en el HUB GAMER más importante de LatAm. Esto nos permitirá transformar la economía en sectores como la industria del software y el hardware, el emprendimiento y el empleo juvenil, la economía digital y las exportaciones.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(520, 'Soberanía Energética y Mercados de Valores', 'Búsqueda de independencia energética para evitar la dependencia de suministros extranjeros y retorno de Ecopetrol a los mercados de valores globales para atraer inversionistas institucionales internacionales.', 'Mi misión es rescatar la soberanía: volver a explorar, volver a producir y volver a crecer para que la energía sea el motor de la libertad y no el grillete de la pobreza. Ecopetrol regresa a los mercados públicos de valores con fuerza, despolitizada y enfocada en reponer reservas con una meta superior al 120 %.', 6, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(521, 'Universidad en Casa: Plataforma Virtual Gratuita', 'Creación de una plataforma nacional de educación superior virtual, certificada y sin costo para facilitar el acceso desde cualquier lugar.', 'Voy a respaldarlos con programas como la universidad en casa, una Plataforma Nacional de Educación Virtual Universitaria, certificada y gratuita.', 10, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(522, 'Nuevo Modelo de Crédito ICETEX', 'Transformación de la financiación educativa con créditos a tasas del 2 % anual, plazos de 10 años y periodo de gracia tras graduarse.', 'Restableceré la financiación de las becas y del Icetex con un nuevo modelo de créditos educativos, justo y sostenible, que incluya créditos al 2 % anual, a diez años y con un periodo de gracia de un año una vez el beneficiario concluya sus estudios.', 10, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(523, 'Modernización del Estado y Gobierno Abierto', 'Propone eliminar la corrupción y el exceso de burocracia mediante un sistema de \'Gobierno Abierto\' donde la ciudadanía pueda vigilar directamente la inversión de los recursos públicos.', 'La corrupción le cuesta al país cerca de $50 billones de pesos al año, recursos que pertenecen a las regiones. Cero tolerancia a la corrupción y menos burocracia Implementaremos un Gobierno Abierto donde tú mismo vigiles en qué se invierte cada peso.', 1, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(524, 'Eficiencia en el gasto público', 'Enfatiza la necesidad de mejorar la administración de los recursos públicos.', 'hay que mejorar la eficiencia del gasto público.', 3, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(525, 'Seguridad Integral y Construcción de Paz', 'Busca recuperar la tranquilidad en los territorios afectados por el conflicto para evitar la deserción escolar y garantizar el control territorial.', 'Se estima que 6 de cada 10 niños en zonas de conflicto abandonan la escuela por falta de seguridad. El camino inicia recuperando la tranquilidad, fortaleciendo la Fuerza Pública con inteligencia y respeto a los DD.HH. para retomar el control del territorio.', 2, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(526, 'Inversión Social y Reforma Tributaria Progresiva', 'Propone atraer inversión con impacto social y realizar una reforma tributaria que elimine exenciones injustas para generar equidad.', 'Atraeremos inversión con sello social e impulsaremos marcas colectivas para que el emprendedor local compita y gane en los mercados del mundo... Impulsaremos una reforma tributaria progresiva para eliminar exenciones injustas y garantizar que el gasto público genere equidad social real.', 3, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(527, 'Comercio Justo para Pequeños Productores', 'Impulsa la venta directa sin intermediarios y la creación de marcas colectivas para mejorar las ganancias del campesino.', 'Menos del 25% de los pequeños productores agrícolas logran vender sus productos sin intermediarios que castigan su ganancia. Atraeremos inversión con sello social e impulsaremos marcas colectivas para que el emprendedor local compita y gane en los mercados del mundo.', 4, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(528, 'Sustitución de Economías Ilícitas', 'Plantea reemplazar los cultivos de coca por economías legales, aunque manteniendo la erradicación.', 'Hay que aumentar la erradicación forzada eh de coca eh por mecanismos incluso como la fumigación con drones, etcétera. Hay que yo creo que hay que reemplazar economías ilícitas, pero sí hay que tener todas las herramientas a la mano.', 4, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(529, 'Fortalecimiento de la Fuerza Pública', 'Enfoque en inteligencia y respeto a los Derechos Humanos para retomar el control del territorio.', 'El camino inicia recuperando la tranquilidad, fortaleciendo la Fuerza Pública con inteligencia y respeto a los DD.HH. para retomar el control del territorio.', 5, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(530, 'Inclusión y Reducción de la Pobreza', 'Implementación de un ingreso mínimo de emergencia y reformas enfocadas en los grupos más vulnerables.', 'Reduciremos la pobreza con un ingreso mínimo de emergencia y reformas en salud y educación que prioricen a jóvenes, mujeres y adultos mayores vulnerables.', 7, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(531, 'Competitividad y Marcas Colectivas', 'Fomento del emprendimiento local para que pueda competir globalmente.', 'Atraeremos inversión con sello social e impulsaremos marcas colectivas para que el emprendedor local compita y gane en los mercados del mundo.', 8, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(532, 'Transición Energética y Revolución Verde', 'Liderar una respuesta al cambio climático mediante la transición hacia energías limpias.', 'Aunque Colombia emite solo el 0.6% de CO2 global, somos uno de los países más vulnerables al cambio climático; lideraremos la revolución verde.', 9, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(533, 'Conexión Educativa y Mercado Laboral', 'Implementar modelos de colegios comunitarios que preparen a los jóvenes directamente para el trabajo o la universidad, evitando que sean reclutados por la delincuencia.', 'agarraba el colegio comunitario y los preparaba o para ir al mercado laboral, no al SENA, o para seguir en la universidad y eso funciona muy bien... Esos modelos hay que implementarlo en Colombia porque estamos perdiendo la mayoría de los jóvenes aquí se los pierden, que se los llevan los bandidos.', 10, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(534, 'Vías Terciarias y Sostenibilidad', 'Mejorar la red vial secundaria y terciaria involucrando a las comunidades como socias de los proyectos.', 'Llevaremos el progreso a tu puerta con vías y tecnología convirtiendo a las comunidades en socias de los proyectos respetando nuestra biodiversidad.', 11, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(535, 'Carrera Diplomática por Mérito', 'Priorizar el profesionalismo sobre el clientelismo político en la representación internacional.', 'Fortaleceremos la carrera diplomática para que sea el mérito profesional y no el favor político quien represente nuestra soberanía ante el mundo.', 12, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(536, 'Coalición Regional para Venezuela', 'Liderar un grupo de países para buscar una transición democrática en Venezuela y participar en su reconstrucción económica.', 'Colombia arma una coalición con Panamá y va pensando en otros y Panamá le va trayendo a otros... Yo sí creo que ya tienen que prepararse para poder apoyar la reconstrucción en Venezuela... Con quién va a reconstruir Venezuela a Estados Unidos o lo que pretende Estados Unidos? pues con Colombia y hay una enorme hay enormes oportunidades para crecer.', 12, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(537, 'Tecnología para la Seguridad y el Desarrollo', 'Uso de herramientas tecnológicas como drones para la erradicación y tecnología aplicada a la infraestructura vial.', 'Hay que aumentar la erradicación forzada eh de coca eh por mecanismos incluso como la fumigación con drones, etcétera... Llevaremos el progreso a tu puerta con vías y tecnología.', 5, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(538, 'Infraestructura Biodiversa', 'Garantizar que el desarrollo de infraestructura respete la riqueza natural del país.', 'Llevaremos el progreso a tu puerta con vías y tecnología convirtiendo a las comunidades en socias de los proyectos respetando nuestra biodiversidad.', 15, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(539, 'Reforma a la Salud Prioritaria', 'Transformar el sistema de salud para que deje de ser un privilegio y se enfoque en las poblaciones más vulnerables.', 'el acceso a salud de calidad sigue siendo un privilegio de pocos... Reduciremos la pobreza con un ingreso mínimo de emergencia y reformas en salud y educación que prioricen a jóvenes, mujeres y adultos mayores vulnerables.', 16, 12, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(540, 'Programa Estudia y Gana (Ingreso por estudiar)', 'Creación de un sistema de transferencias directas mensuales para estudiantes de secundaria (grado 10 y 11) y universidad para evitar la deserción escolar y garantizar que \'la gente coma\'. Propone pagar medio SMMLV a bachilleres y hasta un 75% o 100% a universitarios.', 'Por eso yo creo que hay que pagarles por estudiar... al asignar un ingreso por estudiar a los estudiantes de grado 10 y 11, que es donde mira, se va al 50%... luego a la universidad... es la oportunidad de hacer una redistribución de ingresos para que la gente coma, para que también haya un ahorro programado para mejorar vivienda o emprendimiento. Los estudiantes de secundaria recibirán medio SMMLV, mientras que los universitarios podrán recibir hasta un 75% del sueldo o uno completo', 10, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(541, 'Gratuidad en Servicios Básicos Educativos y Reforma a la Ley 30', 'Implementar gratuidad total en transporte y alimentación para todos los estudiantes del sistema público. Además, propone una reforma constitucional a la Ley 30 para asegurar la universidad gratuita.', 'Yo creo que hay que darle gratuidad en el transporte a los estudiantes... y hay que darle alimentación a todos los que están en el sistema educativo público. Mantendría la gratuidad en la universidad pública... pero modificaría integralmente la Ley 30, haciendo una reforma constitucional.', 10, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(542, 'Tránsito hacia un Modelo Federal', 'Realizar una gran consulta nacional para transformar la estructura del Estado de un régimen centralista a uno federalista, otorgando autonomía real a las regiones.', 'Impulsaremos un proceso de federalización para hacer posible la autonomía y la capacidad de decisión de las regiones en torno a su propio futuro. Yo creo que después la discusión del federalismo que la veremos desde la presidencia siendo una gran consulta en el país porque yo te digo tiene todas las bondades.', 14, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(543, 'Reformulación del modelo de seguridad y paz', 'Crítica al modelo de \'Paz Total\' por falta de resultados y propuesta de usar la educación como principal herramienta para evitar que los jóvenes ingresen a grupos armados o al sicariato.', 'El modelo de paz total no está funcionando... propuso un modelo enfocado en la educación como herramienta para alejar a los jóvenes de la violencia. Son las causas de por qué se retira y se terminan yendo, obviamente, muchos al sicariato y luego terminan en las cárceles.', 2, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(544, 'Reorganización del sistema de subsidios y Banca Pública', 'Financiar el gasto social mediante la eliminación de la ineficiencia estatal, la creación de una banca pública cooperativa y el uso de mecanismos financieros como un modelo similar al 4x1000.', 'Estos recursos tienen que salir de la reorganización del sistema de subsidios y del control de la ineficiencia estatal... crearíamos la banca pública cooperativa... implementar un modelo similar al 4x1000 en las transacciones financieras.', 3, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(545, 'Reforma Agraria Integral', 'Convertir a Colombia en potencia agrícola mediante una reforma agraria de derechos, que incluye la compra y redistribución de tierras para los campesinos.', 'Impulsaremos una reforma agraria de derechos para campesinos que garantice que Colombia sea una potencia agrícola... haría una reforma agraria integral.', 4, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(546, 'Aprovechamiento de Hidrocarburos y Soberanía Energética', 'No frenar la explotación de hidrocarburos actual para financiar la educación y fortalecer las \'comunidades energéticas\' para crear empresas de servicios públicos estatales.', 'Aprovechar las reservas de hidrocarburos de Colombia también sería clave para financiar la educación del futuro... no se debe seguir jugando a la transición energética sin aprovechar los recursos actuales. Mantendría comunidades energéticas... pero trabajaríamos en la creación de empresas de servicios públicos.', 9, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(547, 'Modelo de Salud Pública Universal', 'Establecer un modelo de salud gestionado por el Estado que garantice cubrimiento universal.', 'Impulsaremos los servicios públicos por el Estado, un modelo de salud pública con cubrimiento universal.', 16, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(548, 'Industrialización Planificada y Derechos Laborales', 'El Estado debe intervenir como planificador en la industrialización del país y retomar la reforma laboral para proteger derechos.', 'El Estado intervenga planificando y jugando como un actor importante en la industrialización del país... hay que retomar la reforma laboral.', 7, 13, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(549, 'Plan Muralla Digital 4.0', 'Estrategia integral basada en tecnología, transparencia y sanciones severas para erradicar el clientelismo y garantizar la trazabilidad del gasto público.', 'Cero favores políticos. Tecnología para la Transferencia Total (TTT): blockchain e inteligencia artificial para trazabilidad absoluta en la ejecución de recursos públicos. Regla 70-30: 70% de la contratación será por licitación pública. SECOP 2 al 100%. Sistema Unificado Anticorrupción. Red de cooperantes anticorrupción. Regla 40-40: 40 años de prescripción para delitos de corrupción y 40 años de inhabilidad.', 1, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(550, 'Paz con Seguridad y Justicia para las Víctimas', 'Enfoque de paz basado en la legalidad, el rechazo a la impunidad negociada y la protección efectiva de las víctimas del conflicto.', 'Rechazo total a la impunidad negociada. Justicia real para las víctimas: protección efectiva, verdad, reparación y garantías de no repetición sin revictimización ni impunidad para los agresores.', 2, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(551, 'Plan de Crecimiento Económico y Austeridad Responsable', 'Propuesta de reactivación económica mediante el recorte del gasto público innecesario, el fortalecimiento de Ecopetrol y el fomento a la inversión privada sin nuevas reformas tributarias.', 'Austeridad: Recorte de 20 billones de pesos en el gasto público. Ecopetrol: Elevar utilidades a 20 billones de pesos para 2027. Lucha contra la evasión estimada en 100 billones de pesos mediante tecnología, sin nuevas reformas tributarias. Turismo: Disminuir el IVA de los tiquetes aéreos del 19% al 5%. Banca de Oportunidades 2.0.', 3, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(552, 'Potencia Agrícola: Seguridad y Desarrollo Rural', 'Fortalecimiento del campo a través de la lucha contra la extorsión, mejora de infraestructura (vías terciarias) y programas de emprendimiento para jóvenes rurales.', 'Seguridad en el Campo: Lucha frontal contra la extorsión y el contrabando. Mi Idea Mi Ingreso Rural: Capital semilla, crédito con garantía estatal. Vías Terciarias: Mejoramiento de los 142.284 km de vías. Mercado Joven Rural. Incentivos arroceros.', 4, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(553, 'Seguridad Democrática 2.0 y Diplomacia de Seguridad Total', 'Recuperación del control territorial, fortalecimiento de la Fuerza Pública y lucha frontal contra el narcotráfico y el crimen organizado.', 'Control Territorial: Reactivación de la seguridad democrática. Creación de 3 nuevos batallones en Valle del Cauca, Jamundí y Buenaventura. Protección a la Fuerza Pública. Narcotráfico: Retomar aspersión con tecnología de precisión. Inteligencia: Inversión en helicópteros artillados. Cero Impunidad.', 5, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(554, 'Autonomía Energética y Aprovechamiento de Recursos', 'Explotación máxima de recursos naturales (petróleo, gas y carbón) para financiar la inversión social y la transición energética.', 'Producción Máxima: Dejar todos los proyectos en producción (gas, petróleo, carbón). Ecopetrol: Lograr que produzca un billón de barriles de petróleo. Fracking y Minería: Sí al fracking y sí a la minería legal con estándares ambientales exigentes. Proyecto Sirius 2. Exportación de Carbón.', 6, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(555, 'Bienestar Social: Vivienda Digna y Protección a la Juventud', 'Masificación de subsidios de vivienda, atención integral en salud mental y programas de ahorro para el futuro de los jóvenes.', 'Vivienda: Reactivación de Mi Casa Ya y créditos. Salud Mental: Programa Conecta Contigo. Pensiones: Fondo de Pensiones Juvenil. Inclusión Financiera: Programa Mi Plata Mi Futuro.', 7, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(556, 'Impulso al Emprendimiento y Seguridad Jurídica Empresarial', 'Reducción de trámites, acceso a crédito formal para microempresas y beneficios para empresas que generen empleo formal.', 'Reducción de Trámites: Bajar a la mitad los 120 trámites actuales. Apoyo a Tenderos: Plan De la mano con el tendero. Formalización Fintech. Incentivos: Reducción de impuestos a empresas que generen empleo formal.', 8, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(557, 'Plan de Choque Energético y Tarifas Justas', 'Reducción de costos de energía, garantía de suministro para evitar apagones e inversión en proyectos de energías renovables y transmisión.', 'Reducción de Tarifas: Inversión de 2.4 billones. Infraestructura Energética: Puesta en marcha de Hidroituango, Porce IV y Espíritu Santo. Energías Renovables: 2000 MW en La Guajira. Gas: Construcción de la regasificadora del Pacífico.', 9, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(558, 'Educación para la Libertad y el Trabajo', 'Reforma educativa enfocada en la calidad, eliminación del adoctrinamiento ideológico y formación técnica flexible para el empleo.', 'Cero Adoctrinamiento. No más Paros. Educación Multiformato: Red Nacional de Educación Multiformato Rural. Inglés con profesores nativos vía virtual. Reforma ICETEX. Infraestructura: Uso de colegios públicos como instituciones técnicas en las noches.', 10, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(559, 'Infraestructura para la Competitividad y el Bienestar', 'Finalización de megaproyectos frenados, modernización de la red hospitalaria y ejecución de obras mediante Alianzas Público-Privadas (APP).', 'Megaproyectos: Metro de Bogotá, Nuevo aeropuerto de Cartagena, Segunda pista de Rionegro, Tren de cercanías del Valle. Logística: Culminar vías 4G y concesionar 5G. Salud: Rescate y modernización de la red hospitalaria nacional.', 11, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(560, 'Diplomacia de Seguridad Total', 'Reorientación de las relaciones internacionales para fortalecer la seguridad nacional, combatir el terrorismo regional y atraer inversión tecnológica.', 'Aliados Estratégicos: Volver a ser el primer aliado de EE. UU. y restablecer alianza de confianza con Israel. Venezuela: Declarar oficialmente al régimen de Maduro y al Cartel de los Soles como grupo terrorista y narcotraficante. Embajadas: Cierre de embajadas que no promuevan negocios.', 12, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(561, 'Revolución Digital e Internet Permanente', 'Masificación de la conectividad rural, uso de tecnologías de vanguardia en el agro y digitalización de los servicios financieros.', 'Plan IPESI: Internet Permanente Sin Interrupción. Quantum Rural: Formación en agricultura de precisión (drones, sensores de suelo). Muralla Digital: Uso de IA y Blockchain para el control del erario. Fintech: Fondo público de innovación.', 13, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(562, 'Desarrollo Regional con Autonomía y Equidad', 'Fortalecimiento de las transferencias a los territorios, coordinación directa con alcaldes y compensación justa por regalías.', 'Transferencias: Cumplir el Acto Legislativo 3 de 2024. Gestión Local: Reunión con cada alcalde del país en los primeros 100 días. Regalías: Revisión integral para que las regiones productoras reciban compensación justa.', 14, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(563, 'Protección de la Amazonía y Minería Sostenible', 'Conservación del patrimonio ambiental mediante seguridad democrática, combate a la minería ilegal y transición energética responsable.', 'Amazonía: Recuperar el territorio frente a la deforestación. Estrategia trinacional (Colombia-Perú-Brasil). Minería Ilegal: Operaciones integrales en zonas críticas. Formalización Minera. Vigilancia Satelital.', 15, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(564, 'Salud en Territorio: Calidad y Formalización', 'Recuperación del sistema mediante un modelo mixto, formalización del talento humano y atención especializada en zonas remotas.', 'Modelo Mixto: Preservar el aseguramiento individual y colectivo. Talento Humano: Formalización progresiva. Soberanía Sanitaria en Amazonía: Brigadas médico-aeronáuticas permanentes. Transparencia: Sistema Unificado de Información Financiera en Salud.', 16, 3, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(565, 'IA contra la corrupción: Guardián Digital', 'Creación de un sistema digital ciudadano con inteligencia artificial y blockchain para vigilar el gasto público, controlar elecciones, detectar corrupción en tiempo real y permitir denuncias ciudadanas.', 'Este sistema será de acceso para cada ciudadano mayor de edad que inscriba su cédula para las votaciones. Con la misma tecnología bancaria, cada ciudadano tendrá en su celular la aplicación que le permitirá: Ser un Veedor Digital para cuidar el presupuesto local, regional y nacional. Tomar foto a su tarjetón y reportar su voto en tiempo real. Su funcionamiento se basará en tres pilares: Trazabilidad Total, Análisis Predictivo de Anomalías y Cero Sobornos.', 1, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(566, 'Eliminación de gobernaciones y asambleas departamentales', 'Supresión progresiva de gobernaciones y asambleas departamentales para reducir estructuras clientelistas y corrupción política.', 'Supresión progresiva de las 32 gobernaciones. Eliminación de asambleas departamentales. Traslado de competencias a las REGIONES. Se mantiene el municipio como base territorial, para devolverle el poder a la Gente.', 14, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(567, 'Reducción del Congreso', 'Disminución del número de congresistas para reducir burocracia y gasto público.', 'Menos congresistas, menos burocracia, menos gasto inútil. Ahorro estimado: $450 mil millones de pesos al año que irán directo a la gente, a las regiones.', 3, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(568, 'Infraestructura para la paz territorial', 'Desarrollo de infraestructura y sustitución de economías ilegales en la Región Pacífico.', 'REGIÓN PACÍFICO - EJE: PAZ, PUERTOS Y BIODIVERSIDAD. Buenaventura como eje global. Sustitución de economías ilegales. Protección étnica y cultural. Infraestructura para la paz territorial.', 2, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(569, 'La verdadera paz es el empleo', 'Industrialización agrícola como estrategia para evitar que jóvenes ingresen a grupos armados o criminales.', 'Esta expansión masiva de 5 millones de hectáreas cultivadas e industrializadas generará 3 millones de empleos directos e indirectos en el campo colombiano. Esa es la verdadera reforma agraria. Esa es la verdadera paz. Cuando un joven campesino tiene un empleo formal, bien pagado, en una agroindustria tecnológica, no se va a la guerrilla, no se va a las bandas criminales.', 3, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(570, 'Banco de las MIPYMES y la economía popular', 'Creación de un banco para otorgar créditos rápidos y accesibles a comerciantes informales, emprendedores y microempresarios.', 'Dar acceso a crédito legal, rápido y justo a: Comerciantes informales, Vendedores ambulantes, Microempresarios, Emprendedores. CARACTERÍSTICAS: Créditos rotativos de bajo monto inmediatos (48–72 horas), Tasas bajas reguladas, Sin trámites excluyentes, Evaluación alternativa (flujo diario, no historial bancario).', 3, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(571, 'Coca por Coco: revolución de las oleaginosas perennes', 'Industrialización masiva del campo mediante expansión del coco, aguacate y palma para generar empleo y riqueza rural.', 'Llevaremos al campo el Milagro de los aceites vegetales para la industrialización del COCO, EL AGUACATE Y LA PALMA. Coco: Pasar de 25.000 a 1.5 millones de hectáreas. Aguacate: Pasar de 80.000 a 500.000 hectáreas. Palma de Aceite: Pasar de 600.000 a 3 millones de hectáreas.', 5, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(572, 'Centro C5 de seguridad nacional', 'Creación de un centro nacional con inteligencia artificial para predecir delitos y coordinar fuerzas de seguridad.', 'Se creará un Centro de Comando, Control, Comunicaciones, Cómputo e Inteligencia (C5) bajo el mando directo de la Presidencia. El C5 integrará en tiempo real la información de todas las fuerzas, con Big Data e Inteligencia Artificial para: Predecir el Crimen, Desarticular Estructuras, Optimizar Recursos.', 5, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(573, 'Fronteras inteligentes', 'Uso de drones, sensores e IA para vigilancia permanente de fronteras.', 'Drones de alta capacidad de control de fronteras, sensores e Inteligencia Artificial para blindar nuestras fronteras del narcotráfico y el contrabando. Implementaremos un sistema de vigilancia 24/7 con drones de alto rango y sensores térmicos en los principales pasos fronterizos ilegales.', 5, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(574, 'Gas natural como energético de transición', 'Expansión del gas natural y fortalecimiento petrolero con valor agregado.', 'Gas natural como energético de transición: Expansión de exploración y producción, Infraestructura de transporte y regasificación. Petróleo con valor agregado: Refinación avanzada, Petroquímica, Exportación de derivados, no solo crudo.', 9, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(575, 'Seguridad social sin privilegios', 'Sistema de seguridad social para población informal, adultos mayores y trabajadores excluidos.', 'Colombia necesita un sistema de seguridad social que incluya a todos. Pensión universal desde los 70 años. Para campesinos desde los 65 años. Seguridad social para los 12 millones de informales.', 7, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(576, 'Soberanía minero-energética y energía nuclear', 'Modelo energético basado en energías tradicionales, renovables y energía nuclear modular.', 'Colombia no puede elegir entre desarrollo y sostenibilidad. Vamos a liderar una nueva era energética. Se propone implementar tecnología de: SMR (Small Modular Reactors), Capacidad: 50–300 MW por unidad.', 9, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(577, 'Tutor IA personalizado para cada niño', 'Implementación de tutores de inteligencia artificial para personalizar el aprendizaje.', 'Cada estudiante tendrá un Tutor IA gratuito que: Detecta fortalezas y debilidades, Adapta el aprendizaje al ritmo individual, Refuerza materias críticas, Convierte el estudio en experiencia interactiva.', 10, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(578, 'Universidad Digital de Colombia', 'Universidad virtual enfocada en habilidades del siglo XXI y conexión laboral.', 'Carreras virtuales accesibles y flexibles. Enfoque en habilidades del siglo XXI. Certificaciones modulares. Conexión directa con el mercado laboral.', 11, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(579, 'Transporte regional integrado', 'Desarrollo logístico y de transporte integrado en la Región Andina Centro.', 'REGIÓN ANDINA CENTRO - EJE: CENTRO PRODUCTIVO, DIGITAL Y LOGÍSTICO. Transporte regional integrado.', 11, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(580, 'Ministerio de Relaciones Internacionales y Comercio Exterior', 'Creación de ministerio enfocado en diplomacia, comercio exterior y posicionamiento global.', 'MINISTERIO DE RELACIONES INTERNACIONALES Y COMERCIO EXTERIOR: Diplomacia, Comercio Exterior, Posicionamiento Global.', 12, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(581, 'Pasaporte de habilidades extraordinarias', 'Documento especial para talentos colombianos con reconocimiento internacional.', 'Creación del Pasaporte de Habilidades Extraordinarias. Beneficios: Facilitación migratoria internacional mediante convenios multilaterales. Acceso preferencial a visas culturales, deportivas y de competencia.', 12, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(582, 'Colombia 5.0', 'Ecosistema nacional de seguridad tecnológica con IA, cámaras inteligentes y big data.', 'Convertiremos a Colombia en el primer país de América Latina donde la tecnología le gana al crimen. 1. Plataforma Nacional de Seguridad en Tiempo Real. 2. Red Nacional de Cámaras Inteligentes. 3. Identidad Digital Segura para Todos los Ciudadanos.', 14, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(583, 'Creación de 7 grandes regiones autónomas', 'Nuevo modelo territorial con autonomía presupuestal y gobiernos regionales.', 'CREACIÓN DE 7 GRANDES REGIONES AUTÓNOMAS\nCada región con:\n• Autonomía presupuestal\n• Autoridad regional elegida por voto popular\n• Parlamento regional\n• Sistema fiscal propio', 14, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(584, 'Región Amazonía como potencia ambiental', 'Desarrollo de economía verde y conservación ambiental en la Amazonía.', 'REGIÓN AMAZONÍA. Guardianes del bosque (pagos por conservación). Salud intercultural. Universidades amazónicas. Tokenización ambiental (bonos verdes). Se convierte en: Potencia ambiental y financiera verde del mundo.', 15, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(585, 'Salud sin filas', 'Sistema nacional digital de salud con historia clínica única, telemedicina y atención rápida.', 'SISTEMA ÚNICO NACIONAL: Historia clínica digital obligatoria. Integración total de EPS, IPS, Clínicas y Servicio Farmacéutico. Acceso desde el celular: TELEMEDICINA. CITAS EN 72 HORAS: Consulta general: máximo 72 horas. Especialistas: máximo 15 días. Clínicas móviles con internet satelital.', 16, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(586, 'Modelo de financiación basada en ingresos', 'Financiación educativa donde el beneficiario paga solo cuando tenga ingresos suficientes.', 'Complementamos esta política con un sistema de Financiación Basada en Ingresos: El Estado o fondos aliados financian la formación del talento. El beneficiario paga solo cuando genere ingresos suficientes. Sin deudas impagables ni presión financiera.', 10, 4, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(587, 'Agencia Anticorrupción y Tablero de Transparencia', 'Transformación de la Secretaría de Transparencia en una Agencia Anticorrupción con contratación por mérito y creación del Tablero de la Transparencia para rendición de cuentas.', 'Directiva Presidencial para transformar la Secretaría de Transparencia en una Agencia Anticorrupción, con contratación basada únicamente en mérito e integridad. Se ordenará la creación del Tablero de la Transparencia para rendir cuentas periódicas al país.', 1, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(588, 'Identificación de proponentes y persecución de evasores', 'Decreto para identificación pública de proponentes en licitaciones y persecución de los 100 mayores evasores.', 'Expedición de Decreto Presidencial que exija que todos los proponentes en licitaciones puedan ser identificados por la ciudadanía. El decreto ordenará a la DIAN y a las superintendencias que persigan a los 100 evasores más grandes.', 1, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(589, 'Fuerzas especiales anticorrupción y Unidad de Congelamiento de Activos', 'Mesas de trabajo de fuerzas especiales anticorrupción, Unidad de Congelamiento Urgente de Activos y Comité Presidencial de Auditoría.', 'Instalación de mesas de trabajo de fuerzas especiales anticorrupción, la Unidad de Congelamiento Urgente de Activos, y el Comité Presidencial de Auditoría a Riesgos de Corrupción, para hacer seguimiento a entidades de alto riesgo.', 1, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(590, '30 proyectos de inversión con control especial', 'Identificación y control especial de los 30 proyectos de inversión pública de mayor impacto.', 'Presentación de los 30 proyectos de inversión con control especial. Se identificarán y presentarán al país los 30 proyectos de inversión pública de mayor impacto económico y social, los cuales estarán sometidos a un régimen especial de transparencia y control preventivo.', 1, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(591, 'Ley del lobby y protección a denunciantes', 'Radicación ante el Congreso de Ley del lobby, protección a denunciantes y eliminación de beneficios a corruptos.', 'Radicación ante el Congreso de Ley del lobby, de protección a denunciantes y de eliminación de beneficios a corruptos. Presentaremos al Congreso una Ley de Lobby que obligue a registrar reuniones y relaciones entre funcionarios públicos y grupos de interés.', 1, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL);
INSERT INTO `proposals` (`id`, `title`, `summary`, `full_text`, `category_id`, `candidate_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(592, 'Cultura de integridad en el Estado', 'Política nacional de integridad pública con formación obligatoria a servidores y participación ciudadana.', 'Se promoverá una política nacional de integridad pública, con formación obligatoria para servidores del Estado, fortalecimiento de oficinas de control interno y participación ciudadana en la vigilancia de los recursos públicos.', 1, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(593, 'Garantías de no repetición y protección de líderes', 'Integración de la política de víctimas con seguridad, protección colectiva a líderes y presencia integral del Estado.', 'Integraremos la política de víctimas con la política de seguridad concebida en el Plan Guardián, priorizando territorios con mayor número de víctimas y nuevos hechos victimizantes. Aseguraremos esquemas de protección colectiva para líderes, reclamantes de tierras y organizaciones de víctimas.', 2, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(594, 'Aceleración de la reparación integral a víctimas', 'Rediseño de la política de reparación priorizando víctimas vulnerables y reduciendo tiempos de indemnización.', 'Rediseñaremos la política de reparación con base en el universo real de víctimas, ajustando metas, plazos y fuentes de financiación. Priorizaremos a víctimas en situación de mayor vulnerabilidad y simplificaremos los trámites y usaremos tecnologías y equipos móviles en zonas rurales.', 2, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(595, 'Reparación colectiva como transformación territorial', 'Convertir los Planes Integrales de Reparación Colectiva en planes de desarrollo local con enfoque en víctimas.', 'Convertiremos los Planes Integrales de Reparación Colectiva en verdaderos planes de desarrollo local con enfoque en las víctimas. Priorizaremos los sujetos colectivos en zonas de alta conflictividad y presencia de economías ilegales.', 2, 9, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(596, 'Pena de muerte para corruptos y venta de empresas estatales', 'Aplicar pena de muerte a corruptos, vender empresas del Estado en manos de políticos y castigar con pena de muerte a quienes roben en el sector salud.', 'Pena de muerte para corruptos, violadores y asesinos seriales. Vendiendo las empresas del Estado que hoy están en manos de políticos ladrones. Pena de muerte al que robe en salud.', 3, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(597, 'Inversión masiva, impuestos bajos y apertura económica', 'Inversión de $150 billones de dólares al año en infraestructura, reducción de impuestos (renta al 10%, IVA al 7%), legalización del dólar y bitcoin, y apertura del país a capital extranjero.', 'Colombia es rica, pero hay 27 MILLONES DE POBRES. INVERSIÓN DE $150 BILLONES DE DÓLARES POR AÑO: Carreteras y puertos, Servicios públicos, Aeropuertos. IMPUESTOS BAJOS: 10% RENTA, 7% IVA. Vendiendo las empresas del Estado que hoy están en manos de políticos ladrones. DÓLAR Y BITCOIN LEGALES.', 3, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(598, 'Aumento de productividad rural a $2.000.000 por hectárea', 'Pasar de $300.000 a $2.000.000 mensuales por hectárea mediante inversión en emprendedores agrarios, infraestructura productiva y enfoque en productos con ventaja comparativa como palma de aceite, coco y aguacate.', 'ACTUAL $300.000 por hectárea mensual → OBJETIVO $2.000.000 por hectárea mensual. Inversión especial para emprendedores en el agro. Construcción de infraestructura productiva. Enfocando a Colombia en lo que sí tenemos ventajas para producir: palma de aceite, coco, aguacate.', 4, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(599, 'Acabar con la impunidad: TEMPLARIOS y mega cárceles', 'Crear una fuerza especial de 100 mil hombres llamada TEMPLARIOS, construir 3 mega cárceles 100 años de soledad, aplicar cadena perpetua y pena de muerte, eliminar rebajas de penas y casa por cárcel, y reformar la justicia con jueces por mérito.', '95 DE CADA 100 BANDIDOS QUEDAN LIBRES. ESO SE LLAMA IMPUNIDAD. Jueces por mérito, no por rosca. 3 mega cárceles llamadas 100 años de soledad. Nada de rebajas de penas, ni casa por cárcel. Cadena perpetua para secuestradores, asesinos y extorsionistas. Pena de muerte para corruptos, violadores y asesinos seriales. 100 mil hombres para la fuerza especial TEMPLARIOS.', 5, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(600, 'Explotación de minas, petróleo y energía', 'Permitir la explotación de minas, petróleo y energía como motor económico del país.', 'Dejando que se exploten las minas, el petróleo y la energía, y abriendo el país para que lleguen bancos y plata de otros países.', 7, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(601, 'Plan Tu Techo Propio', 'Entregar 1 millón de lotes gratis con servicios y créditos con cuotas desde $600.000, financiados con lotes del Estado, bienes incautados a narcos y políticos corruptos, y el plan PLANTE Y PA LANTE.', '60% DE LOS COLOMBIANOS no tiene casa propia. PLAN TU TECHO PROPIO: 1 millón de lotes gratis con servicios, Créditos con cuotas desde $600.000. Utilizando los lotes del Estado y casas quitadas a narcos y políticos corruptos.', 7, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(602, 'Subsidios directos para colegios y universidad', 'Entregar $800.000 mensuales a las madres para que elijan colegio y $6 millones por semestre para 2.5 millones de jóvenes universitarios.', '85% de los jóvenes no puede acceder a la universidad pública por falta de cupo. $800.000 mensuales para que las mamás elijan el colegio. $6 millones por semestre para 2.5 millones de jóvenes universitarios. Usando la plata que hoy botan en esa tal Paz Total.', 11, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(603, 'Beneficios para conductores y libertades laborales en transporte', 'Rebajar la gasolina a la mitad, eliminar peajes y foto-multas, legalizar el mototrabajo y plataformas digitales, permitir porte legal de armas a taxistas y camioneros.', 'BENEFICIOS ECONÓMICOS: Rebajar el precio de la gasolina a la mitad, Rebajar y eliminar peajes. LIBERTADES LABORALES: Legalizar el moto trabajo, mototaxi, y plataformas digitales. ELIMINACIÓN DE MULTAS: Eliminar las foto-multas.', 11, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(604, 'Inversión en carreteras, puertos, aeropuertos y servicios', 'Destinar parte de los $150 billones de dólares anuales a infraestructura nacional.', 'INVERSIÓN DE $150 BILLONES DE DÓLARES POR AÑO: Carreteras y puertos, Servicios públicos, Aeropuertos.', 11, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(605, 'Política internacional enfocada en comercializar productos colombianos', 'Reorientar la política exterior hacia la comercialización de productos agrícolas colombianos y abrir el país a capitales extranjeros.', 'Enfocar la política internacional en comercializar los productos colombianos. Abriendo el país para que lleguen bancos y plata de otros países.', 13, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(606, 'Modernización digital de la salud y pagos digitales en educación', 'Modernizar el sistema de salud con tecnología e inteligencia artificial, y usar pagos digitales en educación para evitar la pérdida de recursos.', 'Modernizar la salud con tecnología e inteligencia artificial. Haciendo pagos digitales pa que la plata no se pierda y se use en lo que es. DÓLAR Y BITCOIN LEGALES.', 16, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(607, 'Ley Ángel reforzada y primer hospital público de mascotas', 'Imponer 25 años de cárcel para maltratadores de animales, prohibir el maltrato animal, crear el primer hospital público de mascotas.', '25 años de cárcel en cárcel 100 Años de Soledad, Primer hospital público de mascotas, Prohibido maltratar un animal. La ley Ángel debe ser más dura con el maltratador.', 7, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(608, 'Salud universal financiada con recursos robados recuperados', 'Implementar salud universal con los mismos recursos hoy robados, aplicar pena de muerte a quienes roben en salud, comprar medicinas a buen precio, pagar a tiempo y modernizar con tecnología e IA.', '90B PAGAMOS VS 60B SE ROBAN. Pena de muerte al que robe en salud. Comprar medicinas a buen precio. Pagar a tiempo. Salud universal con la misma plata que hoy se roban. Modernizar la salud con tecnología e inteligencia artificial.', 16, 2, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(609, 'Activación económica para generar renta de USD 10.000 anuales por colombiano', 'Plan económico en cuatro frentes: eliminar pobreza con desempleo del 5%, garantizar equilibrio fiscal, aumentar exportaciones y convertir a Colombia en país de ahorradores.', 'El 7 de agosto del 2026 propongo un empujón a la economía. Existen cuatro frentes: 1. Eliminar la pobreza y lograr una tasa de desempleo del 5%. 2. garantizar un equilibrio fiscal. Pasamos de 5 a 7 puntos del PIB. 3. aumentar las fuentes de crecimiento, principalmente las exportaciones. 4. hacer de Colombia y de cada colombiano un país de ahorradores.', 3, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(610, 'Reforma tributaria para equilibrio fiscal', 'Reforma con impuestos a juegos de azar e iglesias, eliminación de exenciones, tasa máxima de renta del 30% escalonada.', 'Reforma tributaria: Impuestos a los juegos de azar, impuestos a las iglesias, eliminar exenciones. Combinado con una tasa máxima de impuesto a la renta del 30% y escalonado por el tamaño de las empresas. 1% del PIB en mejora de ingresos por reforma tributaria y ajuste de gasto de otro 1%.', 3, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(611, 'Ajuste y calidad del gasto público', 'Recortes en personal (OPS) y transferencias, ley de competencias clara, impuestos a pensiones altas, y enfoque en inversión efectiva, equidad y sostenibilidad.', 'Ajuste al gasto público. Recortes en personal (OPS) y de transferencias. Por ejemplo: una ley de competencias clara que no aumente el gasto central; viceministerios y direcciones; e impuestos a pensiones altas.', 3, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(612, 'Aumentar fuentes de ingresos vía exportaciones', 'Nuevas fuentes de crecimiento sectorial en turismo, agricultura y remesas.', '¿cómo aumentar en la generación de ingresos? Avanzar en nuevas fuentes de crecimiento sectorial, aumentar las exportaciones. 1. Turismo 2. Agricultura 3. Remesas', 3, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(613, 'Colombia país de ahorradores', 'Destinar 10% de regalías al sistema de pensiones, cesantías y remesas como pilares del ahorro nacional.', '¿cómo hacer de Colombia un país de ahorradores? 1. 10% de las regalías para el sistema de pensiones. 2. Cesantias. 3. Remesas.', 3, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(614, 'Activación de demanda interna mediante vivienda y construcción', 'Reactivar el programa Mi Casa Ya y desarrollar proyectos de arrendamiento con CACP.', 'Activar la demanda interna, a través de la vivienda y la construcción. Activar el programa de Mi casa Ya y en proyectos para arrendamiento con cacp.', 3, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(615, 'Concesiones y APPs', 'Desactivar fiducias de las 5G y generar proyectos de Asociación Público-Privada en cárceles, salud y educación.', 'Consesiones. Desactivar fiducias de las 5G y generar proyectos de APP en cárceles, sector salud y educación.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(616, 'Exploración y producción de hidrocarburos con fracking responsable', 'Avanzar en hidrocarburos y minerales mediante fracking seguro, reemplazar consultas previas extensas con licencias sociales y reformar profundamente la ANLA.', 'avanzar en la exploración y producción de hidrocarburos y minerales. Para ello propongo un Fracking seguro y responsable, avanzar en licencias sociales que reemplacen las extensas consultas previas y en una reforma profunda de la ANLA.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(617, 'Estrategia Cero Extorsión', 'Convertir la lucha contra la extorsión en prioridad nacional con fortalecimiento del GAULA, unidades élite regionales tipo bloques de búsqueda, mecanismos de denuncia segura e inteligencia financiera.', 'Cero Extorsión: Estrategia integral contra la extorsión. Convertir la lucha contra la extorsión en prioridad nacional. Fortalecer las capacidades especializadas de la Policía Nacional en particular el GAULA. Crear unidades élite regionales anti-extorsión. Establecerán mecanismos para facilitar la denuncia. Inteligencia financiera para seguir el rastro del dinero.', 5, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(618, 'Recuperación del control territorial', 'Plan de recuperación con presencia permanente en territorios afectados por grupos ilegales, estrategia diferenciada por territorio y refuerzo de puestos militares y policiales rurales.', 'Recuperación del control territorial. Lanzar un plan de recuperación y presencia permanente en territorios afectados por grupos ilegales. Desplegar fuerzas de seguridad de manera permanente no solo operativos puntuales en las zonas rojas del país, priorizando al menos seis regiones críticas.', 5, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(619, 'Reestructuración de fuerzas y equipamiento', 'Modernizar Fuerzas Armadas y Policía recuperando bloques de búsqueda regionales, dotación tecnológica con drones y fortalecimiento de Fuerza Aérea y Armada contra narcotráfico.', 'Reestructuración de fuerzas y equipamiento: Modernizar y reorganizar las Fuerzas Armadas y la Policía. Recuperar los bloques de búsqueda regionales. Dotación tecnológica y movilidad: drones de vigilancia, equipos de intercepción. Fortalecer las capacidades de la Fuerza Aérea y Armada.', 5, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(620, 'Reforma al sistema de inteligencia y control del crimen desde las cárceles', 'Crear un Centro de Inteligencia Penitenciaria e invertir en inteligencia artificial y ciberseguridad para analizar big data delictiva.', 'Crear un Centro de Inteligencia Penitenciaria, dedicado a monitorear y bloquear las operaciones criminales que se dirigen desde el interior de las cárceles. Invertir en inteligencia artificial y ciberseguridad para la seguridad ciudadana.', 5, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(621, 'Política Nacional de Seguridad y Defensa', 'Implementar de inmediato una política nacional integral con marco legal sólido, con hoja de ruta detallada en 60 días.', 'Política Nacional de Seguridad y Defensa. Formular e implementar de inmediato una Política Nacional de Seguridad y Defensa integral. El Ministerio de Defensa estructurando en 60 días una hoja de ruta detallada. Creación de una Ley de Seguridad y Defensa Nacional.', 5, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(622, 'Fortalecer la cooperación internacional en seguridad', 'Restablecer y ampliar alianzas con EE.UU., UE, OTAN y países aliados para entrenamiento, inteligencia y financiación de operaciones contra narcotráfico y terrorismo.', 'Fortalecer la cooperación internacional. Colombia buscará una mayor cooperación con Estados Unidos, la Unión Europea, la OTAN y países aliados para apoyo en entrenamiento, inteligencia y financiación de operaciones contra el narcotráfico y el terrorismo.', 12, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(623, 'Plan Maestro DUAL de infraestructura en Salud (PMDS)', 'Plan dual con más Estado en regiones apartadas donde el sector privado no entra, y participación privada donde el sistema está establecido.', 'Desarrollar un plan maestro DUAL de infraestructura en salud. El plan dual consiste en ofrecer más Estado y capacidad de infraestructura pública, en las regiones más apartadas del país, y promover la participación privada donde el sistema está bien establecido.', 16, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(624, 'Plan de servicios de salud realista', 'Redefinir el Plan de Beneficios en Salud (PBS) para que sea más pequeño y acorde al presupuesto, basado en evidencia científica del IETS.', 'Se necesita redefinir el Plan de Beneficios en Salud (PBS) y la entrada de nuevas tecnologías sanitarias. El nuevo PBS debe ser más pequeño, acorde al presupuesto, pero en línea con la mayor evidencia científica recaudada por la agencia de tecnologías sanitarias del país (IETS).', 16, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(625, 'Datos claros y en tiempo real en salud', 'Digitalizar y unificar sistemas de información de salud, con inteligencia artificial para detectar patrones de gasto, fraudes y mejorar eficiencia.', 'Es urgente digitalizar y unificar los sistemas de información para garantizar que los datos sean accesibles y confiables en tiempo real. La inteligencia artificial juega un papel clave en el análisis de datos de salud, permitiendo detectar patrones de gasto, fraudes y mejorar la eficiencia del sistema.', 16, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(626, 'Rutas claras para mejor atención en salud', 'Implementar y fortalecer las Rutas Integradas de Atención en Salud (RIAS) y Guías de Práctica Clínica (GPC) con apoyo de IA para estandarizar tratamientos.', 'Implementar y fortalecer las Rutas Integradas de Atención en Salud (RIAS) y las Guías de Práctica Clínica (GPC). Esto garantizaría que los tratamientos sean uniformes y basados en evidencia científica.', 16, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(627, 'Fila única y transparente para medicamentos', 'Sistema unificado y estandarizado de dispensación de medicamentos donde cada paciente pueda reclamar en cualquier droguería autorizada sin depender de su EPS.', 'Se debe implementar un sistema unificado y estandarizado de dispensación de medicamentos. Así, cualquier paciente podría reclamar sus medicamentos en cualquier droguería autorizada, sin depender de su aseguradora. La inteligencia artificial podría ayudar a predecir la demanda de medicamentos.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(628, 'Diversificar la matriz energética con renovables y generación firme', 'Política agresiva de diversificación con energía solar y eólica a gran escala, exploración de energía nuclear civil, pequeñas hidroeléctricas y geotermia.', 'Acelerar la VERDADERA incorporación de energías solar y eólica a gran escala mediante subastas específicas e incentivos fiscales. Exploraremos fuentes de energía firme de largo plazo: retomar el estudio de energía nuclear civil, promover la construcción de pequeñas centrales hidroeléctricas y geotermia.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(629, 'Plan DUAL de Inversión en infraestructura energética', 'Inversión mixta con énfasis público en regiones de baja capacidad de pago promoviendo autogeneración comunitaria, y mercado regulado con incentivos privados en el SIN.', 'Se busca implementar un plan dual con inversión mixta donde la mayor fuerza de la inversión pública ocurre en regiones y comunidades con baja capacidad de pago. Por su parte, un mercado regulado con incentivos para la inversión privada en las zonas del sistema interconectado nacional SIN.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(630, 'Garantizar abastecimiento de gas y transición ordenada', 'Importación de GNL ampliando capacidad de regasificación, aceleración de exploración y producción de gas nacional incluyendo costa afuera y no convencionales.', 'En el corto plazo, promoveremos la importación de GNL ampliando la capacidad de regasificación. En paralelo, vamos a acelerar la exploración y producción de gas nacional. Fomentaremos el uso de GLP y biogás como complementos.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(631, 'Programa de Modernización de Redes Eléctricas', 'Reducción de pérdidas eléctricas con expansión de transmisión, digitalización con medición inteligente, microrredes off-grid y mantenimiento preventivo.', 'Lanzaremos un Programa de Modernización de Redes Eléctricas. Este incluirá proyectos prioritarios de expansión de transmisión. La digitalización de la red: promoveremos la instalación de sistemas de medición inteligente y monitoreo en tiempo real.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(632, 'Gobernanza energética y planeación de largo plazo', 'Creación de un Consejo Nacional de Política Energética, Política Energética de Estado 2026-2050, mesas de concertación regional y estabilidad jurídica para inversión.', 'Crearemos un Consejo Nacional de Política Energética liderado por Presidencia. Definir una Política Energética de Estado 2026-2050. Fortaleceremos la UPME. Fomentaremos la articulación temprana con autoridades locales y comunidades.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(633, 'Nuevas tecnologías y eficiencia energética', 'Almacenamiento con baterías, plan nacional de eficiencia energética, electromovilidad y autoconsumo solar con medición neta.', 'Apoyaremos proyectos piloto de almacenamiento con baterías a escala de red. Lanzaremos un plan nacional de eficiencia energética. Impulsaremos la electromovilidad vehículos eléctricos y el autoconsumo solar con esquemas de medición neta.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(634, 'Reforma del mercado eléctrico y estabilidad tarifaria', 'Mercado de contratos a futuro obligatorio, Fondo de Estabilización Tarifaria, monitoreo a metodología tarifaria, medidas antimonopolio y supervisión severa contra abusos.', 'Implementaremos un mercado de contratos a futuro obligatorio. Se fortalecerán los instrumentos de protección al usuario: creación de un Fondo de Estabilización Tarifaria. Se adoptarán medidas antimonopolio.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(635, 'Plan de salvamento y modernización de la Costa Caribe', 'Saneamiento de deuda tarifaria de $6,5 billones, subsidios focalizados, inversión masiva en infraestructura, lucha contra fraude eléctrico y régimen regulatorio especial.', 'Saneamiento financiero de la deuda tarifaria acumulada. Subsidios focalizados y transitorios. Inversión masiva en infraestructura: modernizar redes, cambiar transformadores, instalar medidores inteligentes. Lucha contra el fraude eléctrico. Régimen regulatorio especial para la Costa Caribe.', 9, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(636, 'Fortalecimiento de la formación para el trabajo', 'Estrategia de comunicaciones para valorar la formación técnica, creación del Viceministerio de Formación para el Trabajo y fortalecimiento de institutos técnicos privados.', 'Estrategia de comunicaciones para que la sociedad valore más la formación para el trabajo. Crear el Viceministerio de Formación para el Trabajo desde el Ministerio de Educación. Fortalecer la financiación y mejorar institutos técnicos privados y ampliar la cobertura.', 10, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(637, 'Ampliación de cobertura en educación superior', 'Plan de infraestructura con mantenimiento, ampliación de 750.000 cupos (250.000 privados, 250.000 públicos, 250.000 propedéuticos) y reestructuración del ICETEX.', 'Para alcanzar el 70% de cobertura de acuerdo con OCDE se necesitaría cerca de 750 mil cupos mas. 250.000 cupos del sector privado, 250 mil cupos del sector público y cursos propedéuticos y ciclos flexibles otros 250 mil cupos. Avanzar en una reestructuración financiera del ICETEX.', 10, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(638, 'Mejora de la calidad en educación básica', 'Construcción de colegios e infraestructura, transporte escolar, currículum nacional, definición del modelo de ciudadano y fortalecimiento de competencias docentes.', 'En educación básica se deben construir colegios e infraestructura y mejorar temas de transporte escolar. Estructurar un currículum nacional. Analizar el modelo del ciudadano que se quiere formar. Fortalecer las competencias educativas a los profesores.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(639, 'Consolidación de una estrategia nacional de transporte unificada', 'Integrar todos los modos de transporte bajo un solo marco regulador, dado que la dispersión actual entre Ministerio de Transporte, Secretarías de Movilidad, Invías, ANI, Aerocivil y Cormagdalena dificulta la coordinación.', 'Esta dispersión de responsabilidades dificulta la coordinación y planeación de una política de transporte unificada. Es necesario avanzar en la consolidación de una estrategia nacional que garantice la integración de todos los modos de transporte bajo un solo marco regulador y de gestión.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(640, 'Reforma del sistema de peajes', 'Reformar el esquema con tarifas diferenciadas, subsidios cruzados y modelo de cobro más equitativo.', 'Se requiere una reforma del esquema de peajes que contemple tarifas diferenciadas, subsidios cruzados y un modelo de cobro más equitativo que no impacte desproporcionadamente a las comunidades locales.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(641, 'Continuidad de concesiones aeroportuarias', 'Garantizar continuidad de proyectos como EdMax en Bogotá y la expansión del aeropuerto de Cali mediante planificación a largo plazo y participación del sector privado.', 'Es fundamental garantizar la continuidad de estos proyectos mediante una planificación a largo plazo y la participación del sector privado.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(642, 'Desarrollo ferroviario y fluvial como prioridad nacional', 'Estrategia de intermodalidad para conectar carreteras, ferrocarriles y ríos navegables, recuperando red férrea y Río Magdalena.', 'Para optimizar el sistema de transporte en Colombia, se debe impulsar una estrategia de intermodalidad que conecte carreteras, ferrocarriles y ríos navegables. Esto permitirá reducir costos logísticos, mejorar la competitividad y disminuir la huella de carbono del transporte en el país.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(643, 'Justicia expedita y fortalecida contra el crimen', 'Fortalecer la Fiscalía General con más recursos en zonas críticas, crear unidades especiales para extorsión y crimen organizado, e impulsar reformas procedimentales con jueces itinerantes.', 'Fortalecer la Fiscalía General con más recursos y talento humano en zonas críticas. Se crearán unidades especiales de fiscales e investigadores dedicadas exclusivamente a casos de extorsión y crimen organizado. Impulsar reformas procedimentales que reduzcan los tiempos de investigación y juicio.', 5, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(644, 'Planeación estratégica con Planes Maestros de Infraestructura', 'Fortalecer la planificación a largo plazo con Planes Maestros que trasciendan ciclos políticos.', 'Para mejorar la eficiencia del sector, es necesario fortalecer la planificación con Planes Maestros de Infraestructura que trasciendan los ciclos políticos y garanticen inversiones sostenibles a largo plazo.', 11, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(645, 'Fortalecimiento de la adopción de Inteligencia Artificial en el mercado laboral', 'Desarrollar políticas que aprovechen el potencial de la IA en Colombia.', 'Aproximadamente 33.8% de los trabajadores colombianos están altamente expuestos a tareas que pueden ser complementadas o sustituidas por IA. Prima salarial por exposición a IA: Los trabajadores altamente expuestos a IA ganan, en promedio, 21.8% más.', 13, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(646, 'Políticas para la transición hacia una economía baja en carbono y empleos verdes', 'Desarrollar formación, protección social y reconversión laboral para la transición verde.', 'Desarrollar políticas de formación, protección social y reconversión laboral que permitan el tránsito hacia una economía baja en carbono que puede generar hasta 15 millones de empleos en América Latina y el Caribe.', 7, 1, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(647, 'Funcionarios con vocación de servicio y cero cargos para corruptos', 'Establecer una línea roja absoluta en el nombramiento de funcionarios, rechazando personas condenadas por corrupción.', 'Funcionarios con vocación de servicio: buscaremos a los mejores, pero no solo a los más capaces técnicamente, sino a personas con sentido social y responsabilidad en la toma de decisiones. Cero cargos para quienes tengan las manos manchadas. Estableceremos una línea roja absoluta en el nombramiento de funcionarios y aliados políticos.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(648, 'Promoción de la integridad pública permanente', 'Implementar formación, evaluación continua y ejemplo desde el más alto nivel, con consecuencias para quienes no cumplan.', 'Promoveremos la integridad pública como una práctica permanente: con formación, evaluación continua y, sobre todo, con mi propio ejemplo desde el más alto nivel de gobierno. Y quien no cumpla, no permanece.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(649, 'Financiación política transparente', 'Reforma estructural a la financiación política con reglas obligatorias, control efectivo y sanciones reales.', 'Seguiremos impulsando una reforma estructural a la financiación política para que estas reglas sean obligatorias, con control efectivo y sanciones reales para todos.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(650, 'Lo robado vuelve al barrio', 'Recuperar los recursos perdidos por corrupción y devolverlos directamente a las comunidades afectadas.', 'Cuando el dinero se esfuma, las comunidades ven obras que no llegan, servicios que no mejoran y promesas que se incumplen. Recuperar esos recursos y devolverlos a la gente es una forma concreta de hacer justicia.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(651, 'Las empresas también responden / Auditoría forense', 'Combatir la corrupción tanto en lo público como en lo privado, con auditoría forense inmediata a entidades intervenidas como la Nueva EPS.', 'La corrupción es un asunto de todos, públicos y privados. No ocurre sola. Cuando una empresa paga por ganar, pierde el país, pierde la competencia y pierden los ciudadanos. Iniciar un arqueo de cuentas inmediato a entidades como la Nueva EPS.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(652, 'Contratación en vitrina: control en tiempo real', 'Llevar la contratación pública a un nuevo nivel de transparencia con blockchain, APIs públicos y analítica de datos con IA para detectar irregularidades.', 'Llevaremos la contratación pública a un nuevo nivel de transparencia y control en tiempo real. Cada etapa del proceso será visible, trazable y abierta al escrutinio ciudadano (blockchain). Implementaremos un sistema que registre la información de los contratos de forma segura y permanente (API). Desarrollaremos herramientas de analítica de datos que identifiquen riesgos en los contratos y generen alertas tempranas (IA y seguimiento).', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(653, 'Guardián de integridad en las entidades públicas', 'Crear una figura aliada del funcionario íntegro, con canales de denuncia, protección, incentivos y reconocimientos como el Premio Nacional de Integridad Pública.', 'Crearemos la figura del guardián de integridad en las entidades públicas. Fortaleceremos los mecanismos de denuncia, con canales directos y protección efectiva para quienes reporten irregularidades. Reconoceremos públicamente a los servidores ejemplares mediante un Premio Nacional de Integridad Pública.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(654, 'Correo personal presidencial para denuncias', 'Canal directo de la presidenta con la ciudadanía para recibir denuncias que ella misma perseguirá.', 'Seremos un gobierno que escuche a la ciudadanía. La presidente tendrá un correo personal para recibir las denuncias, que ella personalmente perseguirá para sacar a los corruptos del gobierno.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(655, 'Cárcel para corruptos y extinción de sus bienes', 'Promover sanciones penales severas y extinción patrimonial para los corruptos.', 'Cero impunidades: el que la hace, la paga. Promoveremos la cárcel para los corruptos y la extinción de sus bienes.', 1, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(656, 'Sustitución de cultivos forzosa y generosa', 'Reactivar la fumigación en zonas con cultivos ilícitos industriales y hacer que la legalidad sea más rentable que el crimen.', 'En las zonas donde hay cultivos ilícitos industriales, reactivaremos la fumigación sin afectar la salud ni los ecosistemas. Haremos que la legalidad sea más rentable que el crimen. El campesino deberá acabar los cultivos ilícitos y lo apoyaremos con cultivos lícitos; además, será socio de empresas que los transformen.', 2, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(657, 'Inversión en municipios no PDET ni ZOMAC con pobreza y víctimas', 'Ampliar la inversión estatal a municipios pobres con presencia de víctimas, aunque no estén en zonas PDET o ZOMAC.', 'Los municipios que no son PDET ni ZOMAC y que tienen pobreza y albergan víctimas también serán receptores de inversión amplia por parte del Estado.', 2, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(658, 'Crecimiento del 5% del PIB anual', 'Recuperar la productividad en sectores clave, con el sector exportador como motor de crecimiento.', 'Creceremos a una tasa del 5 % del PIB cada año. El sector exportador será motor de crecimiento, con 10 mil millones de USD adicionales en exportaciones.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(659, 'Inversión del 25% del PIB y seguridad jurídica', 'Garantizar respeto a los contratos y estabilidad para impulsar la inversión.', 'La inversión será de al menos 25 % del PIB. Daremos seguridad jurídica, respeto a los contratos y estabilidad.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(660, 'Retorno de la confianza inversionista', 'Atraer al menos 2 mil millones de dólares anuales en inversión extranjera directa.', 'Vuelve la confianza inversionista. Atraeremos y destrabaremos al menos 2 mil millones de dólares al año en nuevos proyectos de inversión extranjera directa.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(661, 'Reducción de impuestos y simplificación tributaria', 'Reducir tarifas del impuesto de renta empresarial, eliminar el impuesto al patrimonio, reducir el impuesto predial y simplificar el estatuto tributario.', 'Los impuestos no ahogarán a la economía: reduciremos las tarifas del impuesto de renta empresarial, eliminaremos el impuesto al patrimonio y reduciremos el impuesto predial. Simplificaremos el estatuto tributario.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(662, 'Desactivación de la crisis fiscal y respeto a la regla fiscal', 'Reducir el déficit en 50 billones sin afectar bienes y servicios del Estado.', 'Desactivaremos la crisis fiscal para que no disminuya el bienestar de los colombianos: volveremos a una senda que permita respetar la regla fiscal. Reduciremos el déficit en 50 billones sin afectar bienes y servicios del Estado.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(663, 'Líneas de crédito sin trámites para el campo', 'Otorgar créditos agrícolas a través de las casas de agroinsumos.', 'Otorgaremos líneas de crédito sin trámites a través de las casas de agroinsumos.', 4, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(664, 'Entrega de tierras con proyectos productivos', 'Entregar tierras junto con asociatividad, maquinaria y tecnología.', 'Entregaremos tierras con proyectos productivos y asociatividad para acceder a maquinaria y tecnología, y terminaremos los procesos de entrega ya iniciados.', 4, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(665, 'Formalización de 3 millones de hectáreas', 'Formalizar tierras para campesinos.', '3 millones de hectáreas formalizadas para que nuestros campesinos puedan aprovechar mejor sus tierras.', 4, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(666, '1 millón de nuevas áreas en cultivos y agroindustria', 'Crear zonas francas rurales y nuevas áreas productivas.', '1 millón de nuevas áreas en cultivos y agroindustria con zonas francas rurales.', 4, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(667, 'Títulos de tierra a nombre de mujeres', 'Otorgar mayoría de títulos a mujeres para empoderarlas y protegerlas de violencia intrafamiliar.', 'La gran mayoría de los títulos estarán a nombre de las mujeres, para empoderarlas y protegerlas de la violencia intrafamiliar.', 4, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(668, 'Modernización de las Fuerzas Armadas y de Policía', 'Aumentar el gasto en seguridad y defensa en 20 billones durante el cuatrienio, alcanzar el 4% del PIB en inversión, salto tecnológico con drones y ciberinteligencia, y Plan 30-30.', 'Aumentaremos el gasto en seguridad y defensa en cerca de $20 billones durante el cuatrienio, con el objetivo de alcanzar niveles de inversión en nuestras fuerzas cercanos al 4 % del PIB. Plan 30-30: incorporaremos 30 mil nuevos militares y 30 mil nuevos policías.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(669, 'Acción envolvente contra extorsionistas', 'Capturar extorsionistas mediante acción coordinada de la Fuerza Pública.', 'Acción envolvente de la Fuerza Pública para capturar a los extorsionistas.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(670, 'Asfixia financiera a ilegales y extinción de dominio exprés', 'Convertir bienes ilícitos en recursos para el Estado y programas sociales.', 'Asfixia financiera a los ilegales y extinción de dominio exprés. Convertiremos los bienes ilícitos en recursos para el Estado y los programas sociales.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(671, 'Fortalecimiento del sistema de justicia penal', 'Crear fiscales especializados, bloqueo de comunicaciones en cárceles, ley contra prácticas dilatorias, endurecimiento de penas para reincidentes y uso de IA en investigaciones.', 'Crearemos fiscales especializados por estructuras criminales. Promoveremos un bloqueo total de las comunicaciones en establecimientos de privación de la libertad. Capacitaremos y fortaleceremos las estructuras del Estado para que la captura derive en judicialización efectiva y se fomente el uso de IA en investigaciones criminales.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(672, 'Reactivación de combustibles fósiles y fracking', 'Producción de 1 millón de barriles de petróleo por día, exploración y explotación de gas costa adentro y afuera.', 'Reactivaremos la explotación de combustibles fósiles e impulsaremos el fracking. Garantizaremos la exploración y explotación de gas en nuestro territorio (costa adentro y costa afuera). Producción de petróleo de 1 millón de barriles por día.', 6, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(673, 'Subsidios a pipetas de gas', 'Otorgar subsidios en zonas con mayor consumo de leña, beneficiando a 1 millón de familias.', 'Daremos subsidios a pipetas de gas en zonas con mayor consumo de leña. 1 millón de familias dejarán de cocinar con leña.', 6, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(674, 'Fortalecimiento del gobierno corporativo de Ecopetrol', 'Restaurar la institucionalidad de Ecopetrol.', 'Fortalecimiento inmediato del gobierno corporativo de Ecopetrol.', 6, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(675, 'Regulación minera diferenciada', 'Formalización de la minería a pequeña escala con asociación, capacitación, financiamiento y buenas prácticas.', 'Entendemos que la regulación minera debe ser diferenciada en función del tipo de minería. Debemos dar una solución real para la formalización de la minería a pequeña escala en Colombia, que los asocie, capacite, financie, ayude a adoptar buenas prácticas sociales y ambientales.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(676, 'Lucha contra la minería ilegal', 'Combatir las redes criminales que se financian con minería ilegal.', 'Lucha decidida contra la minería ilegal, que hoy financia redes criminales y agobia a nuestros pequeños mineros.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(677, 'Acompañamiento a trabajadores informales', 'Créditos, cooperativas, formación, capital semilla y tecnología para informales.', 'Acompañaremos a los informales. Ser informal no debe ser una condena a ser pobre. Créditos, cooperativas, formación en oficio, capital semilla y tecnología.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(678, 'Cédula del Hogar y Registro Universal de Ingresos', 'Focalizar apoyos para reducir pobreza multidimensional de 12,7% a 7% y pobreza extrema de 11,7% a 6%.', 'Con la Cédula del Hogar aprovecharemos el Registro Universal de Ingresos (RUI) para focalizar apoyos adecuados y de esa manera reducir la pobreza multidimensional de 12,7 % a 7 % y la pobreza extrema de 11,7 % a 6 %.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(679, 'Escalera de la formalidad progresiva', 'Reducir impuesto de renta, facilitar formalización con crédito accesible, registro gratuito de Cámaras de Comercio e Invima, y mini régimen simple.', 'Reduciremos el impuesto de renta y facilitaremos la formalización del pequeño empresario con crédito accesible y trámites simplificados. Registro de Cámaras de Comercio gratuito, Invima gratuito y mini régimen simple de tributación.', 8, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(680, 'Billeteras digitales para informales y vendedores ambulantes', 'Crear historia crediticia y derrotar a los gota a gota con créditos garantizados.', 'Dotaremos a los trabajadores informales y vendedores ambulantes de billeteras digitales para generar una historia crediticia real y derrotar a los prestamistas gota a gota con créditos garantizados por el Estado.', 8, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(681, 'Acceso a energía confiable y barata por 20 años', 'Establecer bases de largo plazo para garantizar acceso energético.', 'Establecimiento de las bases para que los colombianos tengamos acceso a energía confiable y barata durante los próximos 20 años.', 9, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(682, 'Plan de choque para proyectos de generación y transmisión', 'Cerrar brecha de energía firme y evitar apagones o tarifas impagables.', 'Plan de choque para acelerar la entrada en operación de proyectos de generación y transmisión ya viabilizados. El objetivo es cerrar la brecha de energía firme y evitar apagones o aumentos impagables en las tarifas.', 9, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(683, 'Impulso a hidroeléctricas y energías alternativas', 'Embalses, PCH, eólica, solar, biomasa, geotérmica, hidrógeno y nuclear.', 'Impulsaremos nuevos proyectos de generación hidroeléctrica mediante embalses y a filo de agua (PCH). Impulsaremos energías alternativas y no convencionales como la eólica, solar, biomasa, geotérmica, hidrógeno y nuclear.', 9, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(684, 'Energía para inteligencia artificial', 'Optimizar recursos energéticos para centros de datos de bajo costo.', 'Optimizaremos los nuevos recursos energéticos para permitir que Colombia participe en la revolución de la inteligencia artificial, con centros de datos y de procesamiento de bajo costo.', 9, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(685, 'Ruta 3E - Estudiar, Emplearse o Emprender', 'Garantizar que ningún joven se quede sin avanzar.', 'Ruta 3E -Estudiar, Emplearse o Emprender- garantizará que ningún joven se quede sin avanzar.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(686, 'Libertad de elección de colegios y programas educativos', 'PTA 4.0, modelo PROMCE, 150.000 bonos educativos, 187.000 cupos gratuitos y 10 supercolegios públicos.', 'El futuro de un niño no puede depender del barrio donde nació. Habrá libertad de elección para estudiar en colegios de calidad. PTA 4.0 para mejorar la calidad académica adaptado a la revolución de la IA. 150.000 bonos educativos para los más vulnerables. 187.000 cupos gratuitos en colegios de calidad en concesión. 10 supercolegios públicos de excelencia.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(687, 'Reforma al ICETEX', 'Créditos contingentes al ingreso laboral.', 'El ICETEX dejará de ser una trampa de deuda: los créditos se pagarán solo cuando haya trabajo y según el salario.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(688, '1 millón de jóvenes formados en IA y habilidades digitales', 'Cursos gratuitos con internet incluido para trabajar con empresas internacionales desde cualquier municipio.', '1 millón de jóvenes formados en inteligencia artificial y habilidades digitales con cursos gratuitos e internet incluido, para trabajar con empresas internacionales desde cualquier municipio.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(689, 'Plan vial campesino', 'Intervención de 35.000 km de vías rurales: 10.000 km nuevas terciarias y 25.000 km de mantenimiento.', 'Plan vial campesino: intervendremos 35.000 km de vías rurales: 10.000 km de nuevas vías terciarias. 25.000 km de mantenimiento de emergencia, preventivo y rutinario con maquinaria amarilla que pagará el Gobierno nacional.', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(690, 'Continuidad a obras públicas y APP', 'Ejecutar al 100% la 4G y 5G y destrabar proyectos en otros modos de transporte.', 'Daremos continuidad a los contratos de obra pública y de asociaciones público-privadas (APP), y destrabaremos los proyectos actuales en ejecución (ejecutar al 100 % la 4G y la 5G).', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(691, 'Construcción de 1 millón de viviendas', '250 mil subsidios y relanzamiento de Mi Casa Ya 2.0, Casa Semilla y Semillero de Propietarios.', 'Apoyaremos la construcción de 1 millón de viviendas nuevas para las familias colombianas de menores ingresos, a través de la asignación de 250 mil subsidios de vivienda, y el relanzamiento de programas como Mi Casa Ya 2.0.', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(692, 'Agua potable para 1 millón de hogares', 'Construcción e intervención de acueductos con incentivos a inversión y fortalecimiento rural.', 'Apoyaremos la construcción e intervención de acueductos en todo el país, asegurando que 1 millón de hogares cuenten con nuevos accesos a agua potable y saneamiento básico.', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(693, 'Diplomacia Comercial de Resultados', 'Embajadores como agentes comerciales para vender productos nacionales.', 'Transformaremos el rol de nuestras misiones diplomáticas para que los embajadores actúen como agentes comerciales de la nación. Su prioridad será la venta activa de los productos nacionales en el mundo.', 12, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(694, 'Liderazgo en el Escudo de las Américas', 'Integración con apoyo de Estados Unidos para combatir narcotráfico, retomando la cooperación del Plan Colombia.', 'Solicitaremos la integración de Colombia en el Escudo de las Américas para combatir el narcotráfico con el apoyo tecnológico y de entrenamiento de los Estados Unidos. Retomaremos una cooperación profunda basada en el éxito del Plan Colombia.', 12, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(695, 'Firmeza democrática regional', 'Rechazo a dictaduras y apoyo a reconstrucción de Venezuela.', 'Adoptaremos una postura clara de rechazo a las dictaduras y regímenes autocráticos; buscaremos ser un aliado fundamental en la reconstrucción de Venezuela.', 12, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(696, 'Internet satelital y conectividad', 'Conexión en zonas marginadas con paneles solares para servicio eléctrico deficiente.', 'Internet satelital y conectividad para zonas marginadas: llevaremos conexión a los rincones apartados del país, complementados con paneles solares en aquellos lugares con un servicio eléctrico deficiente.', 13, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(697, 'Estado plataforma con tecnologías de última generación', 'Migrar a blockchain (títulos y contratación), IA (cuellos de botella) y big data (decisiones regulatorias).', 'Construcción de un Estado plataforma, interoperable, digital y orientado a resultados: migrar la administración pública hacia tecnologías de última generación (blockchain para títulos y contratación, IA para eliminar cuellos de botella burocráticos y big data para decisiones regulatorias).', 13, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(698, 'Plan Nacional de Inteligencia Artificial (PNIA)', 'Servicio público AI first para resolver trámites automáticamente.', 'Plan Nacional de Inteligencia Artificial (PNIA): diseñar todo un nuevo servicio público como AI first, usar IA para resolver trámites (afiliaciones, renovaciones) automáticamente.', 13, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(699, 'Reducción de ministerios y burocracia', 'Reducir 25% gastos de funcionamiento y congelar OPS en 30%.', 'Reduciremos al máximo el número de ministerios y entidades, liberando recursos para destinarlos a la inversión social y regional. Reducción de la burocracia en un 25 % de los gastos de funcionamiento.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL);
INSERT INTO `proposals` (`id`, `title`, `summary`, `full_text`, `category_id`, `candidate_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(700, 'Presupuesto de inversión regional participativo', 'Asignar en conversaciones públicas con autoridades locales y ciudadanía, eliminando la mermelada.', 'El presupuesto de inversión regional se asignará en conversaciones amplias y públicas con las autoridades locales, ciudadanía y congresistas. No más mermelada; programas con resultados medibles.', 14, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(701, 'El agua, el bosque y la tierra como patrimonio', 'Recuperar el territorio para la legalidad como política ambiental y económica.', 'El agua, el bosque y la tierra son nuestro patrimonio. Recuperar el territorio para la legalidad es, al mismo tiempo, la mejor política ambiental y la mejor política económica.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(702, 'Restauración de 1 millón de hectáreas', 'Frenar deforestación, plantaciones comerciales en 300.000 hectáreas, familias guardabosques y reforestación.', 'Restauraremos 1 millón de hectáreas, frenaremos la deforestación e incrementaremos las plantaciones comerciales en 300.000 hectáreas. Familias guardabosques con pago del Estado, pagos por servicios ambientales e incentivo forestal.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(703, 'Pagos por servicios ambientales (PSA)', 'Consolidación de programas PSA, incentivo forestal y beneficios tributarios.', 'Consolidación de los programas de pagos por servicios ambientales (PSA) y pago por resultados ambientales, el incentivo forestal y los 16 beneficios tributarios para actividades de conservación.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(704, 'Bioeconomía', 'Aumentar bioeconomía de 0,8% a 2% del PIB en 4 años.', 'Promoción de la biodiversidad como fuente de riqueza legal del país, aumentando la bioeconomía del 0,8 % al 2 % del PIB en 4 años, con enfoque territorial y comunitario.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(705, 'Puesto de Mando Unificado en Salud y choque a la crisis', 'PMU 24/7 en Presidencia, resolver 10 millones de atenciones represadas en 100 días, compras centralizadas, pago de deudas vía titularización y ajuste de UPC para 2027.', 'Tendremos un Puesto de Mando Unificado (PMU) 24/7 en Presidencia. Resolver 10 millones de atenciones represadas en medicamentos, citas y procedimientos en los primeros 100 días de gobierno. Pago de la deuda del Estado a prestadores vía titularización.', 16, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(706, 'Inyección de 9 billones para estabilizar el sistema', '3 billones para medicamentos y 6 billones para pago de deudas a clínicas, hospitales y EPS.', 'Inyectaremos 9 billones: 3 billones de pesos para garantizar el suministro oportuno de medicamentos. 6 billones de pesos para el pago de deudas acumuladas por falta de actualización a clínicas, hospitales y EPS.', 16, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(707, 'Sistema mixto y solidario de salud', 'Recuperar la participación de entidades públicas y privadas.', 'Recuperaremos el sistema mixto y solidario de salud para que entidades públicas y privadas puedan participar en el mejoramiento de la calidad y el servicio a los pacientes.', 16, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(708, 'Acabar con la corrupción y crear tribunal especializado en contratación pública', 'Eliminar la intermediación opaca, los fondos sin control y la contratación amañada por mafias políticas. Se creará un tribunal especializado para investigar procesos de contratación pública desde los pliegos hasta la ejecución, y los corruptos serán procesados bajo las reglas de la Fiscalía Antimafia.', 'Acabar con la corrupción: se eliminarán los espacios de intermediación opaca, los fondos sin control y la contratación hecha a la medida de mafias políticas. La contratación pública será transparente, competitiva y vigilada, con sanciones ejemplares para corruptos, y con recuperación efectiva de los recursos. Se fortalecerán las capacidades de investigación y judicialización de redes corruptas que se roban los impuestos de la gente. Los corruptos serán procesados y sometidos a las reglas y condiciones de la Fiscalía Antimafia. Además, se creará un tribunal especializado para investigar de manera expedita los procesos de contratación pública desde los pliegos hasta la ejecución, con capacidad para identificar procesos amarrados, corregir oportunamente y sancionar de manera efectiva a responsables públicos y privados.', 1, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(709, 'Transformar la Procuraduría hacia la prevención y vigilancia anticorrupción', 'Reorientar los funcionarios y recursos de la Procuraduría para fortalecer la Fiscalía Antimafia, la Fiscalía General en los territorios y el Sistema Nacional de Defensoría Pública, enfocándose en prevención disciplinaria, vigilancia de la contratación pública y lucha contra la corrupción.', 'Transformar la Procuraduría: destinar sus funcionarios y recursos a fortalecer la Fiscalía Antimafia, la Fiscalía General en los territorios y el Sistema Nacional de Defensoría Pública. Además se reorientarán hacia la prevención disciplinaria y la vigilancia de la contratación pública y la lucha contra la corrupción, con capacidad para identificar riesgos de corrupción, corregir irregularidades de manera oportuna y activar sanciones efectivas en coordinación con las entidades competentes.', 1, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(710, 'Cumplirle a las víctimas y honrar los acuerdos de paz', 'Garantizar la reparación integral a las víctimas y el cumplimiento efectivo de los acuerdos de paz, entendiendo que el conflicto político armado se acabó con la desmovilización de las FARC y que actualmente existen organizaciones criminales transnacionales.', 'Cumplirle a las víctimas: garantizar la reparación integral a las víctimas y el cumplimiento efectivo de los acuerdos de paz, asegurando el cumplimiento de lo pactado con la ciudadanía y las regiones. Cuidar el proceso de paz pasa por cumplir con los acuerdos, honrar a las víctimas, darle la grandeza a la fuerza pública y entender que el conflicto político armado se acabó con la desmovilización de las FARC. Desde el 2016, hace 10 años, independientemente de su nombre, solo quedan organizaciones criminales transnacionales que se disputan rentas ilícitas y control territorial para maximizarlas. Insistir en tratamiento político y mesas de paz a esas organizaciones solo produce su crecimiento y fortalecimiento a expensas de la vida de la gente en las regiones, como ha quedado evidenciado con el desastre de la paz total.', 2, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(711, 'Recuperar la confianza y reactivar la economía', 'Fortalecer entidades técnicas, implementar política fiscal responsable, establecer diálogo con sector privado y comunidades. Hacer un plan estable y predecible de 4 años para reactivar la economía con regla fiscal y de crecimiento.', 'Recuperar la confianza: fortalecer las entidades técnicas, implementar una política fiscal responsable y creíble y establecer canales de diálogo abiertos y constructivos con el sector privado, los gremios y las comunidades para acordar las políticas públicas y proyectos de desarrollo regional y nacional. Además tendremos reglas claras, estabilidad y condiciones para que el sector privado y el empresariado invierta, genere empleo y crezca en todo el país. Vamos a devolverle a la clase media la capacidad de progresar, ahorrar y mejorar su calidad de vida. Construir credibilidad: haremos un plan estable y predecible para 4 años para reactivar la economía. La regla fiscal y una regla de crecimiento económico guiarán las decisiones. Los gastos totales no pueden seguir creciendo más que los ingresos del país. El Gobierno nacional tendrá recortes de gasto burocrático y búsquedas de eficiencia.', 3, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(712, 'Crear reglas predecibles de impuestos atadas al crecimiento', 'Las reglas tributarias serán predecibles y atadas a resultados macroeconómicos. La tasa de tributación empresarial de renta bajará 2 puntos por cada punto adicional de crecimiento del PIB y cuando la tasa de inversión privada supere el 20% del PIB.', 'Crear reglas predecibles de impuestos: las reglas de impuestos serán predecibles y atadas a resultados macroeconómicos. La tasa de tributación empresarial de renta bajará 2 puntos por cada punto adicional de crecimiento del PIB y cuando la tasa de inversión privada supere el 20% del PIB. Si ponemos a crecer la economía a toda máquina, podemos tener menores impuestos.', 3, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(713, 'Ordenamiento territorial moderno y coordinado', 'Promover la actualización de los Planes de Ordenamiento con municipios y departamentos, acompañamiento técnico y financiero. Impulsar planeación a escala metropolitana y regional. Incluye actualización del catastro multipropósito.', 'Ordenamiento territorial moderno y coordinado: se promoverá la actualización de los Planes de Ordenamiento, con los municipios, departamentos y con acompañamiento técnico y financiero. Además se promoverá la planeación a escala metropolitana y regional, para fortalecer la asociatividad. Esto incluirá la actualización del catastro multipropósito para mejorar la gestión del suelo y la planificación del desarrollo.', 3, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(714, 'Apuestas productivas regionales con empresas ancla y crédito barato para campesinos', 'Definir de forma participativa apuestas productivas diferenciadas por región. La inversión pública garantizará infraestructura, asistencia técnica, crédito barato y precio de compra garantizado para cosechas. Atracción de empresas ancla globales que transfieran tecnología.', 'Desarrollar apuestas productivas regionales con inversión pública focalizada y empresas ancla: definir, de forma participativa, apuestas productivas diferenciadas para cada región, con máxima prioridad presupuestal. La inversión pública se orientará a habilitar y conectar a los productores por tipo de producto, articulando diversas fuentes de financiación y garantizando infraestructura, asistencia técnica, crédito barato y precio de compra garantizado para sus cosechas. Esta estrategia se complementará con la atracción de empresas ancla globales que transfieran tecnología a pymes locales y se alineen con la internacionalización basada en vocaciones regionales.', 4, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(715, 'Seguridad jurídica de la tierra y modelo agroindustrial con campesinos como socios', 'Implementar plan masivo de formalización predial y actualización del catastro multipropósito. Los campesinos y dueños de la tierra serán socios directos de proyectos agroindustriales, con asistencia técnica, crédito barato y precio de compra garantizado.', 'El Estado actuará como garante de la inversión mediante la seguridad jurídica de la tierra, implementando un plan masivo de formalización predial y la actualización del catastro multipropósito para facilitar el acceso al crédito y programas estatales. Las realidades productivas regionales y los modelos asociativos fiduciarios serán claves para dar escala a la inversión sin vulnerar derechos campesinos, quienes tendrán la calidad de socios en los proyectos de desarrollo agroindustrial. Asimismo, se implementará un modelo de asistencia técnica, crédito barato y precio de compra garantizado para las cosechas, asegurando que los campesinos y dueños de la tierra participen como socios directos de la creación de valor.', 4, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(716, 'Reformar la justicia en tres niveles', 'Reorganizar el sistema judicial en tres niveles: (1) Justicia contra mafias con mínimas garantías liderada por la Fiscalía Antimafia; (2) Justicia ordinaria con sanciones drásticas a la reincidencia; (3) Justicia restaurativa para conflictos sociales coordinada con alcaldías. Promover policías locales en grandes ciudades.', 'Reformar la justicia en tres niveles: no podemos seguir dándole las mismas garantías y procedimientos judiciales garantistas al narcotráfico y al crimen organizado, que a la delincuencia común. Para acabar con esa impunidad reorganizaremos el sistema judicial en tres niveles distintos: Justicia contra las mafias: un primer nivel de justicia implacable con mínimas garantías y máximos controles contra criminales de mafias organizadas de corrupción, narcotráfico y rentas criminales que será liderado y operado por la Fiscalía Antimafia. Justicia ordinaria: un segundo nivel de justicia ordinaria para la delincuencia común, donde se sancionará drásticamente la reincidencia y el uso de armas en cualquier tipo de delito. Justicia restaurativa: un tercer nivel de justicia restaurativa para conflictos sociales y faltas a la convivencia que estará muy coordinado con las Alcaldías. Promoveremos la creación de policías locales y sistemas de convivencia en Bogotá, Medellín, Cali, Barranquilla y Cartagena.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(717, 'Crear la Fiscalía Antimafia', 'Crear una Fiscalía Antimafia para someter mafias de corrupción, narcotráfico y crimen organizado, con mínimas garantías, máximas sanciones y aislamiento indefinido hasta que entreguen estructuras, armas y riqueza. El capital ilegal recuperado se reinvertirá en las regiones.', 'Crear la Fiscalía antimafia: estará a cargo del primer nivel de justicia, el de sometimiento de mafias de la corrupción, el narcotráfico y el crimen organizado. Ese nivel judicial tendrá mínimas garantías, máximas sanciones y aislamiento indefinido para los criminales de las mafias de corrupción, narcotráfico y crimen organizado hasta que lleguen a sentencias judiciales de entrega de sus estructuras criminales, armas, y riqueza. Todo el capital ilegal que se incaute y recupere se reinvertirá en las regiones.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(718, 'Retomar el control de las cárceles', 'Reforma penitenciaria integral con transformación del INPEC a gendarmería carcelaria y plan de expansión con tecnología y cero corrupción. Cárceles diferenciadas para cada uno de los tres niveles de justicia, con régimen especial para responsables de mafias.', 'Retomar el control de las cárceles: para garantizar la seguridad y vigilancia y evitar la comisión de delitos desde las cárceles, mediante una reforma penitenciaria integral, una transformación e integración del INPEC a una gendarmería carcelaria y hacer un plan de expansión del sistema carcelario con tecnología, cero corrupción, mayor capacidad y desarrollo de la industria penitenciaria, distinguiendo cárceles para cada uno de los tres niveles de justicia. Los responsables de mafias de corrupción, lavado de activos, narcotráfico y crimen organizado estarán sometidos a un régimen legal y penitenciario diferenciado, con máximo control, vigilancia efectiva y aislamiento de sus redes.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(719, 'Fortalecer el Ministerio de Defensa y Soberanía Nacional', 'Ampliar el pie de fuerza de Fuerzas Militares y Policía, capacidades operativas, de inteligencia, disuasivas, de combate, con tecnología y entrenamiento. Fortalecer cooperación internacional con OTAN y OTCA para combatir crimen organizado transnacional.', 'Fortalecer el Ministerio de Defensa y Soberanía Nacional: ampliar el pie de fuerza de las Fuerzas Militares y de Policía, así como sus capacidades operativas, de inteligencia, disuasivas, de combate, con adecuada tecnología, formación y entrenamiento. Fortalecer las capacidades de desarrollo industrial y tecnológico de las fuerzas militares, así como la cooperación internacional que tiene Colombia a nivel bilateral y con organismos multilaterales como la OTAN y la Organización del Tratado de Cooperación Amazónica (OTCA), entre otros, para perseguir y lograr el sometimiento del crimen organizado transnacional y sus rentas criminales, proteger nuestra biodiversidad y garantizar nuestra soberanía.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(720, 'Reducir las violencias basadas en género', 'Fortalecer capacidad de investigación y sanción de la justicia ordinaria para feminicidios, violencia intrafamiliar y crímenes de odio contra población LGBTIQ+ con castigos rápidos y ejemplares.', 'Reducir las violencias basadas en género: la impunidad en violencias basadas en género es inaceptable. Fortaleceremos la capacidad de investigación y sanción de la justicia ordinaria para que los feminicidios, la violencia intrafamiliar y los crímenes de odio contra la población LGBTIQ+ tengan castigos rápidos y ejemplares.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(721, 'Transformación productiva del Sur Oriente y Piedemonte Amazónico', 'Transición de ganadería expansiva a sistemas silvopastoriles sostenibles, agroindustria de calidad y ecoturismo. Fortalecer cadenas agroalimentarias de valor agregado a partir de frutales, arroz, piscicultura y café.', 'La apuesta central para el Piedemonte Amazónico y el Sur es la transformación productiva hacia un modelo de desarrollo ganadero silvopastoril y sostenible, agroindustrial de calidad y ecoturismo sostenible. Se priorizará la transición de una ganadería expansiva y deforestadora hacia sistemas silvopastoriles, integrando la productividad con la conservación de la naturaleza y el ingreso de las familias rurales. La región cuenta ya con una base productiva diversa, frutales, arroz, piscicultura y café, que debe fortalecerse mediante cadenas agroalimentarias de valor agregado y con potencial exportador. El desarrollo agropecuario impulsado en el sur del Tolima es de los pocos ejemplos de Programas de Desarrollo con Enfoque Territorial (PDET) exitosos que debe fortalecerse y llevarse a otras regiones.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(722, 'Retomar exploración de hidrocarburos y pilotos de fracking', 'Retomar la exploración de hidrocarburos y realizar pilotos de fracking bajo evidencia científica y riguroso licenciamiento ambiental, para asegurar precios bajos de energía y evitar desabastecimiento de recursos como el gas natural.', 'La industrialización del siglo XXI requiere energía abundante, confiable y barata, por lo que es fundamental para el país retomar la exploración de hidrocarburos y realizar pilotos de fracking bajo evidencia científica y riguroso licenciamiento ambiental para asegurar precios bajos y evitar el desabastecimiento de recursos clave para la economía de los hogares como el gas natural.', 6, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(723, 'Reducir las violencias basadas en género', 'Fortalecer capacidad de investigación y sanción de la justicia ordinaria para feminicidios, violencia intrafamiliar y crímenes de odio contra población LGBTIQ+ con castigos rápidos y ejemplares.', 'Reducir las violencias basadas en género: la impunidad en violencias basadas en género es inaceptable. Fortaleceremos la capacidad de investigación y sanción de la justicia ordinaria para que los feminicidios, la violencia intrafamiliar y los crímenes de odio contra la población LGBTIQ+ tengan castigos rápidos y ejemplares.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(724, 'Portafolios territoriales de proyectos y Fondo de Convergencia Regional', 'Cada región contará con un portafolio estructurado de proyectos de desarrollo productivo, financiado mediante alianzas público-privadas-comunitarias y gestionado a través del Fondo de Convergencia Regional.', 'Crear portafolios territoriales de proyectos y financiación unificada: cada región contará con un portafolio estructurado de proyectos de desarrollo productivo, financiado mediante alianzas público-privadas-comunitarias y gestionado a través del Fondo de Convergencia Regional, que unifica recursos del presupuesto nacional, cooperación internacional y fondos de inversión hoy dispersos.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(725, 'Caribe como epicentro de transición energética e inversión directa en infraestructura eléctrica', 'Consolidar región Caribe como epicentro de transición energética, diversificando matriz con renovables y gas natural como combustible de transición. Destinar regalías regionales para financiar modernización de infraestructura eléctrica, evitando cargar estos costos a las tarifas de las familias.', 'La región Caribe se consolidará como el epicentro de la transición energética y la reindustrialización de Colombia, al concentrar el portafolio nacional de energía solar de entrada rápida y el mayor potencial eólico en La Guajira. La apuesta productiva se centra en diversificar la matriz mediante la entrada de proyectos de fuentes renovables, utilizando el gas natural como combustible de transición estratégica para asegurar el respaldo térmico y la confiabilidad del sistema ante eventos de sequía. Para resolver estructuralmente el alto costo de las tarifas eléctricas, se implementará un modelo de inversión directa en la infraestructura. Se destinarán las regalías regionales para financiar la reposición y modernización de postes, transformadores y cableado obsoleto, garantizando que estos costos de infraestructura y mantenimiento no se carguen a las tarifas que pagan las familias y usuarios finales.', 9, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(726, 'Modelo de comunidades socias y obras por impuestos en proyectos energéticos', 'Las comunidades serán socias de los proyectos energéticos. Las empresas ejecutarán directamente infraestructura mediante obras por impuestos o participación en utilidades, eliminando la intermediación política corrupta de las regalías.', 'Para que esto se traduzca en bienestar regional y no en conflictos, planteamos un modelo donde las comunidades sean socias de los proyectos y las empresas ejecuten directamente la infraestructura necesaria (vías, acueductos, redes eléctricas) mediante mecanismos como obras por impuestos o participación en utilidades, eliminando así la intermediación política corrupta que suele apropiarse de las regalías y garantizando que la inversión llegue efectivamente a los municipios productores.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(727, 'Sistema Nacional de Cuidado y Protección Social a nivel municipal', 'Crear y operar un sistema con corresponsabilidad entre Estado, sector privado y comunidad para garantizar cuidado institucionalizado de niños en primera infancia, jóvenes fuera de jornada escolar, personas mayores y con discapacidad. Operará con manzanas de cuidado en zonas urbanas.', 'Crear y operar el Sistema Nacional de Cuidado y Protección Social a nivel municipal: con corresponsabilidad entre el Estado, el sector privado y la comunidad para garantizar el cuidado institucionalizado público-privado-comunitario de los niños en su primera infancia, de los jóvenes más allá de la jornada escolar, de las personas mayores y en condición de discapacidad, relevando a las mujeres de esa sobrecarga de cuidado no remunerado. El sistema operará con manzanas de cuidado en centros poblados y urbanos y con las modalidades pertinentes en zonas rurales. Los servicios institucionalizados de cuidado permitirán liberar tiempo y recarga de trabajo de cuidado no remunerado a las mujeres y cuidadores, y devolverles tiempo, servicios y oportunidades para descansar, estudiar, trabajar, tener autonomía económica y mejorar su calidad de vida.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(728, 'Mejorar asignación de subsidios para hogares en pobreza extrema y moderada', 'Crear paquetes diferenciados de apoyo y un censo nacional de ingresos, vivienda y población que reemplace la estratificación. Para pobreza moderada, combinar becas educativas con subsidios de empleo, servicios de cuidado y subsidios de pobreza, buscando autonomía económica.', 'Mejorar la asignación y coordinación de subsidios para hogares en pobreza extrema con servicios sociales y de cuidado: crear paquetes diferenciados de apoyo para hogares en pobreza extrema, pobreza moderada y vulnerables. Diseño y puesta en marcha de un censo nacional de ingresos, vivienda y población que reemplace la estratificación y permita la formalización de los predios y viviendas de las familias. Mejorar la asignación y coordinación de subsidios para hogares en pobreza moderada con subsidios de educación y empleabilidad: fortalecer la autonomía económica y la movilidad social de las personas a través de becas educativas y de entrenamiento laboral con subsidios para el empleo, combinándolos con los servicios de cuidado, y subsidios de pobreza. La ruta de protección social de todas las familias tendrá como objetivo su autonomía económica.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(729, 'Autonomía económica y mecanismos para mujeres', 'Fortalecer institucionalidad de género, impulsar autonomía económica de las mujeres ampliando acceso a empleo, crédito y oportunidades. Vida libre de violencias mediante línea 155, mayor capacidad de Fiscalía y promoción del liderazgo de mujeres en decisión pública.', 'Mecanismo/institucionalidad de género: fortalecer el mecanismo rector de género, con autonomía técnica y capacidad de articulación intersectorial, con financiación y seguimiento a resultados. Autonomía económica: impulsar la autonomía económica de las mujeres, ampliando su acceso a empleo, crédito y oportunidades en sectores estratégicos. Sistema de cuidado: implementar el Sistema Nacional de Cuidado como política central para reducir la sobrecarga de trabajo no remunerado y aumentar la participación laboral de las mujeres. Vida libre de violencias: fortalecer la Línea Nacional de atención, reducir la impunidad mediante mayor capacidad de la Fiscalía y asegurar protección integral a las víctimas. Participación: promover la participación y el liderazgo de las mujeres en espacios de decisión pública y en la vida económica.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(730, 'Instrumentos financieros alternativos para vivienda', 'Desarrollar nuevos mecanismos que amplíen las opciones de acceso a vivienda, como subsidios mixtos, coberturas de tasa de interés, esquemas de arriendo con opción de compra y microfinanzas para mejoramiento.', 'Instrumentos financieros alternativos para vivienda: se desarrollarán nuevos mecanismos que amplíen las opciones de acceso a vivienda, como subsidios mixtos, coberturas de tasa de interés, esquemas de arriendo con opción de compra y microfinanzas para mejoramiento, adaptados a las condiciones de los hogares de ingresos bajos y medios.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(731, 'Promover la cultura viva en los territorios', 'Impulsar festivales regionales, Fondo Regional de Estímulos, presupuestos participativos y Alianzas Público-Privadas culturales para fortalecer infraestructura cultural y empleo en el sector.', 'Promover la cultura viva en los territorios: festivales regionales, Fondo Regional de Estímulos, presupuestos participativos y APP culturales para fortalecer infraestructura y empleo cultural.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(732, 'Promover deporte, salud y bienestar como política pública - Transformación Social', 'Integrar actividad física a salud pública, ruta deportiva juvenil, Juegos Regionales de la Identidad y APP deportivas para ampliar infraestructura y acceso al deporte.', 'Promover el deporte, salud y bienestar: actividad física integrada a la salud pública, ruta deportiva juvenil, Juegos Regionales de la Identidad y APP deportivas para ampliar infraestructura y acceso.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(733, 'Inclusión de personas con discapacidad y rutas de justicia para mujeres', 'Garantizar inclusión de personas con discapacidad mediante acceso a servicios, educación, empleo y entornos accesibles. Ampliar línea 155, expandir comisarías, jueces de familia y casas refugio para garantizar prevención de violencias de género.', 'Inclusión de personas con discapacidad: garantizar la inclusión de personas con discapacidad mediante acceso efectivo a servicios, educación, empleo y entornos accesibles en todo el territorio. Fortalecer las rutas de justicia y protección oportunas para las mujeres y sus familias: ampliar la línea 155, crear sistemas integrados de información, atención y protección, expandir comisarías, jueces de familia y casas refugio y garantizar justicia oportuna y efectiva de prevención de violencias basadas en género y feminicidios.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(734, 'Promover empresas más productivas, innovadoras y con acceso justo a mercados', 'Ruta integral de apoyo empresarial desde los territorios. Eliminar privilegios normativos, cartelización y posiciones dominantes. Las micro, pequeñas y medianas empresas tendrán acceso preferente a compras públicas, pago a 30 días y subsidios al empleo para jóvenes, mujeres y mayores de 50 años.', 'Promover empresas más productivas, innovadoras y con acceso justo a mercados: se implementará una ruta integral de apoyo empresarial desde los territorios, articulando programas existentes para mejorar productividad, innovación y ventas. Se eliminarán los privilegios normativos, la cartelización y las posiciones dominantes para garantizar una competencia justa y sin barreras. Las micro, pequeñas y medianas empresas tendrán acceso preferente a compras públicas y mercados, pago a 30 días, menores costos, y subsidios al empleo con salario mínimo a poblaciones con mayor desempleo como jóvenes, mujeres y mayores de 50 años.', 8, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(735, 'Crear incentivos al empleo y apoyo a micronegocios', 'Fortalecer clústeres y cadenas productivas con alto potencial. Pasar de micronegocios de autoempleo a empresas con empleos formales. Líneas de crédito preferencial para economía popular liderada por mujeres, jóvenes emprendedores y población con discapacidad.', 'Crear incentivos al empleo y apoyo a micronegocios: fortalecer clústeres y cadenas productivas con alto potencial en productividad, competitividad y exportación, incentivos y cuotas de contratación para personas con discapacidad y poblaciones vulnerables, y una estrategia integral de fortalecimiento del tejido productivo regional, con énfasis en pasar de micronegocios de autoempleo a empresas con empleos formales y parte de cadenas productivas nacionales y de exportación. Se ofrecerán líneas de crédito preferencial, dirigidas específicamente a la economía popular liderada por mujeres, jóvenes emprendedores y población con discapacidad.', 8, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(736, 'Clúster Caribe de transición energética para industrialización', 'Fomentar relocalización de industrias mediante creación de un clúster Caribe de transición energética para fabricación local de paneles solares y turbinas eólicas, aprovechando articulación con sector minero y puertos.', 'En materia de industrialización, se fomentará la relocalización de industrias mediante la creación de un clúster Caribe de transición energética. El objetivo es atraer inversiones para la fabricación local de componentes como paneles solares y turbinas eólicas, aprovechando la articulación con el sector minero y la plataforma logística de los puertos de Cartagena y Barranquilla hasta Puerto Antioquia en Urabá.', 9, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(737, 'Fortalecer el sistema educativo y unificar educación posmedia', 'Avanzar hacia descentralización efectiva, implementar incentivos ligados a la calidad y unificar la educación posmedia en un solo sistema que conecte y garantice educación de calidad, empleo o emprendimiento formal.', 'Fortalecer el sistema educativo: avanzar hacia una descentralización efectiva, implementar incentivos ligados a la calidad, unificar la educación posmedia en un solo sistema que conecte y garantice educación de calidad, empleo o emprendimiento formal que mejore ingresos y patrimonio personal y familiar, y mayor productividad y competitividad.', 10, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(738, 'Todos a la U - Un millón de becas de educación y trabajo', 'Poner en marcha un programa nacional de acceso a educación posmedia con un millón de becas de educación y trabajo similar a Jóvenes a la U y Todos a la U realizado en la Alcaldía de Bogotá, adaptado a cada región.', 'Todos a la U - un millón de becas de educación y trabajo: poner en marcha un programa nacional de acceso a la educación posmedia con un millón de becas de educación y trabajo similar a Jóvenes a la U y Todos a la U, que hicimos en la Alcaldía de Bogotá, adaptada a cada región.', 10, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(739, 'Transformación educativa con aprendizajes de calidad y bienestar', 'Renovación curricular participativa con competencias del siglo XXI, fortalecimiento del rol docente con pedagogías innovadoras, educación socioemocional y ampliación de jornada con enfoque integral y modalidades flexibles.', 'Transformación con aprendizajes de calidad y bienestar: impulsar una renovación curricular participativa que integre competencias del siglo XXI, fortalecer el rol docente con pedagogías innovadoras, incorporar la educación socioemocional y ampliar la jornada con enfoque integral y modalidades flexibles.', 10, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(740, 'Equidad en condiciones y trayectorias educativas', 'Universalizar el preescolar de tres grados, mejorar la infraestructura de sedes oficiales, implementar canasta educativa integral y diseñar un plan especial para educación rural con pertinencia intercultural.', 'Equidad en las condiciones y trayectorias: universalizar el preescolar de tres grados, mejorar la infraestructura de las sedes oficiales, implementar una canasta educativa integral y diseñar un plan especial para la educación rural con pertinencia intercultural e incorporar el componente de salud mental y cuidado en las políticas educativas.', 10, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(741, 'Transformar SENA y crear Agencia Nacional de Educación Posmedia', 'Transformar el SENA para responder a necesidades regionales y unificar el sistema Posmedia en una nueva Agencia Nacional de Educación Posmedia, trabajo y emprendimiento.', 'Oportunidades para jóvenes y adultos: transformar el SENA para responder a las necesidades regionales, unificar el sistema Posmedia en una nueva Agencia Nacional de Educación Posmedia, trabajo y emprendimiento.', 10, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(742, 'Impulsar la empleabilidad de mujeres, jóvenes y mayores de 50 años', 'Formación para el trabajo y reconversión laboral hacia sectores de alta demanda en cada región: cuidado institucionalizado, servicios y tecnología, biotecnología, turismo y sostenibilidad ambiental.', 'Impulsar la empleabilidad: especialmente de las mujeres, los jóvenes y las personas mayores de 50 años con formación para el trabajo y reconversión laboral hacia sectores de alta demanda en cada región como cuidado institucionalizado, servicios y tecnología, biotecnología, turismo y sostenibilidad ambiental.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(743, 'Gran Acuerdo Nacional por la Educación', 'Promover un acuerdo nacional con participación social y política de todos los sectores para que la educación sea el corazón del nuevo contrato social de Colombia.', 'Promover un Gran Acuerdo Nacional: todos unidos en el propósito de la educación, para promover un acuerdo nacional con participación social y política de todos los sectores, para que la educación sea el corazón del nuevo contrato social de Colombia.', 11, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(744, 'Mejorar infraestructura para conectividad, inclusión y productividad', 'Transformar planificación y ejecución de infraestructura de transporte con visión multimodal, resiliente y productiva. Fortalecer participación de comunidades, ajustar procesos de licenciamiento ambiental y recuperar participación del sector privado.', 'Mejorar la infraestructura para la conectividad, la inclusión y la productividad: se transformará la forma de planificar, priorizar y ejecutar la infraestructura de transporte con una visión multimodal, resiliente y productiva, al servicio de las grandes apuestas de desarrollo regional. Con el propósito de fortalecer la participación de las comunidades como socias en la planificación, ejecución y beneficios de los proyectos; ajustar los procesos de licenciamiento ambiental para proteger la estructura ecológica y, al mismo tiempo, acelerar la infraestructura resiliente y adaptativa; recuperar la participación activa del sector privado en la gestión de infraestructura de calidad al servicio de la gente y de la agroindustria.', 11, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(745, 'Mejorar modelo de concesiones portuarias', 'Aprovechar la terminación de concesiones portuarias en 2030 para proponer una nueva asociación público-privada-comunitaria que concesione no solo el puerto sino dragado de canales, vías de acceso y suelos industriales en zonas económicas especiales.', 'Mejorar el modelo de concesiones portuarias: la terminación de las concesiones de las sociedades portuarias en 2030 presentan una oportunidad de aprender de esa excelente experiencia, y proponer una nueva asociación público-privada-comunitaria a la que se concesione no sólo el puerto y los muelles, sino el dragado de sus canales y sus vías terrestres de acceso, así como los suelos potenciales industriales y logísticos en unas zonas económicas especiales de alto valor agregado, logístico y exportador.', 11, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(746, 'Programa nacional de vías terciarias y secundarias atado a concesiones', 'Implementar un programa nacional de vías terciarias y secundarias mediante paquetes de obras atados a las concesiones de las grandes vías nacionales, asegurando su mantenimiento y reduciendo los costos de transporte para los productores rurales.', 'Se implementará un programa nacional de vías terciarias y secundarias mediante paquetes de obras atados a las concesiones de las grandes vías nacionales, asegurando su mantenimiento y reduciendo los costos de transporte para los productores rurales.', 11, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(747, '600 mil soluciones habitacionales para reducir déficit urbano y rural', 'Implementar una política integral de vivienda con 250.000 subsidios para compra de vivienda nueva o usada, 200.000 beneficiarios del programa de arrendamiento social, y 150.000 mejoramientos de vivienda para hogares vulnerables.', '600 mil soluciones habitacionales para reducir el déficit urbano y rural: se implementará una política integral de vivienda que contemple 250.000 subsidios para la compra de vivienda nueva o usada, 200.000 beneficiarios del programa nacional de arrendamiento social, como ruta de acceso progresivo a la vivienda propia, y 150.000 mejoramientos de vivienda para atender el déficit cualitativo, especialmente en hogares vulnerables.', 7, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(748, 'Promover deporte, salud y bienestar como política pública - Infraestructura', 'Integrar actividad física a salud pública, ruta deportiva juvenil, Juegos Regionales de la Identidad y APP deportivas para ampliar infraestructura y acceso al deporte.', 'Promover el deporte, salud y bienestar: actividad física integrada a la salud pública, ruta deportiva juvenil, Juegos Regionales de la Identidad y APP deportivas para ampliar infraestructura y acceso.', 11, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(749, 'Proyectos viales estratégicos por regiones', 'Continuidad de grandes proyectos: túnel del Toyo, vías Medellín-Urabá-Quibdó, corredor férreo del norte, corredor férreo Belencito-Bogotá-Soacha, próximas líneas del metro de Bogotá y Regiotram.', 'La continuidad de grandes proyectos carreteros como el túnel del Toyo y las vías de Medellín hasta Urabá y Quibdó, así como los proyectos férreos de carga como el corredor férreo del norte, mixtos como el corredor férreo de Belencito a Bogotá y Soacha, y de pasajeros como las próximas líneas del metro de Bogotá y los Regiotram de la Región Metropolitana de Bogotá y del Valle de Aburrá son proyectos estratégicos nacionales a los que daremos continuidad y estabilidad.', 11, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(750, 'Ejercer liderazgo político y estratégico en las Américas', 'Cuidar a los colombianos, defender la democracia, el territorio, las fronteras y la soberanía nacional. Acompañar esfuerzos para restablecer la democracia y la libertad en Venezuela.', 'Ejercer liderazgo político y estratégico en las Américas: para cuidar a los colombianos, defender la democracia, el territorio, las fronteras y en general la soberanía nacional, así como cuidar nuestra biodiversidad y ecosistemas estratégicos. Colombia acompañará los esfuerzos para restablecer la democracia y la libertad en Venezuela.', 12, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(751, 'Promover reforma del régimen internacional de drogas', 'Apoyar la desclasificación del cannabis y la hoja de coca, y fortalecer la cooperación internacional para la persecución del crimen organizado y el lavado de activos transnacional.', 'Promover la reforma del régimen internacional de drogas: apoyaremos la desclasificación del cannabis y la hoja de coca, y fortaleceremos la cooperación internacional para la persecución del crimen organizado y el lavado de activos transnacional, particularmente el relacionado con el tráfico de cocaína y sustancias similares, y otras rentas criminales.', 12, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(752, 'Diplomacia política y económica activa', 'Abrir mercados para bienes y servicios colombianos, atraer inversión extranjera directa de calidad y contribuir al desarrollo regional, fortaleciendo intercambios culturales, educativos, científicos y tecnológicos.', 'Impulsar una diplomacia política y económica activa: que abra mercados para los bienes y servicios colombianos, atraiga inversión extranjera directa de calidad y contribuya al desarrollo regional, fortaleciendo al mismo tiempo los intercambios culturales, educativos, científicos y tecnológicos.', 12, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(753, 'Consolidar política exterior orientada a la cooperación efectiva', 'Defensa de la democracia, lucha contra el crimen organizado y sus rentas ilícitas, y fortalecimiento de la autonomía estratégica en cadenas de suministro, industria y desarrollo regional y nacional.', 'Consolidar una política exterior orientada a la cooperación efectiva: para la defensa de la democracia, la lucha contra el crimen organizado y sus rentas ilícitas, y el fortalecimiento de la autonomía estratégica en las cadenas de suministro, la industria y el desarrollo regional y nacional.', 12, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(754, 'Recuperar control, protección e integridad del territorio nacional', 'Convertir las fronteras de periferias de abandono a polos de desarrollo económico e institucional. Garantizar protección efectiva de líderes sociales, ambientales y comunitarios.', 'Recuperar el control, protección e integridad de todo el territorio nacional: la mejor defensa y protección de las fronteras es que dejen de ser periferias de abandono y pasen a ser polos de desarrollo económico e institucional, garantizando oportunidades de desarrollo y florecimiento social, cultural y económico de sus pueblos. Se garantizará la protección efectiva de líderes sociales, ambientales y comunitarios como condición para la presencia legítima del Estado en los territorios.', 5, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(755, 'Sistema de información en salud unificado y transparente', 'Implementar un sistema de información unificado, público, interoperable y transparente, centrado en el paciente, que permita gobernar con evidencia, reducir costos, tiempos de espera y cerrar espacios a la corrupción, usando tecnologías presenciales y remotas.', 'Sistema de información en salud para la atención con calidad y confianza: implementaremos un sistema de información unificado, público, interoperable y transparente, centrado en el paciente. Este permitirá gobernar con evidencia, reducir costos, autorizaciones, tiempos de espera, aumentar la eficiencia y cerrar espacios a la corrupción. Medirá la salud no solo con indicadores biomédicos sino con criterios de equidad territorial y diversidad cultural, y permitirá el uso de tecnologías presenciales y remotas sin sacrificar calidad.', 13, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(756, 'Infraestructura digital para la productividad y GovTech', 'Impulsar gobierno digital interoperable con trámites automatizados, pagos integrados y eliminación de cargas notariales. Crear Portal Único Empresarial, garantizar acceso a internet y un sistema de finanzas y datos abiertos con Bre-B.', 'Apoyar la infraestructura digital para la productividad: se impulsará un gobierno digital interoperable, con trámites automatizados, pagos integrados y eliminación de cargas notariales innecesarias. Se creará un Portal Único Empresarial para simplificar procesos y reducir burocracia. Se garantizará el acceso a internet y una competencia efectiva en telecomunicaciones, y un sistema de finanzas y datos abiertos y transferencias gratuitas con Bre-B.', 13, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(757, 'Ecosistema GovTech desde la Región Central', 'Desarrollar para todo el país un ecosistema de GovTech para digitalizar trámites, automatizar pagos y eliminar requisitos notariales innecesarios, atrayendo empresas ancla globales que transfieran tecnología avanzada a pymes locales.', 'La Región Central, Antioquia, el Eje Cafetero y los Santanderes se proyectan como el motor de la economía del conocimiento, la tecnología, los servicios y la logística avanzada para superar el estancamiento de la productividad nacional. La apuesta productiva se basa en atraer empresas ancla globales que transfieran tecnología avanzada a las pequeñas y medianas empresas locales, fortaleciendo los clústeres regionales de tecnología, servicios, logística y exportación, que pueden desarrollar para todo el país un ecosistema de GovTech para digitalizar trámites, automatizar pagos y eliminar requisitos notariales innecesarios, facilitando un entorno de negocios ágil y transparente.', 13, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(758, 'Descentralizar el DNP creando Departamentos de Planeación Regional', 'Transformar el Departamento Nacional de Planeación en Departamento de Planeación Regional con tres esquemas: ciudades con esquema metropolitano, ciudades sin esquema metropolitano y resto de municipios por subregiones funcionales.', 'Descentralizar el Departamento Nacional de Planeación (DNP) para que pase a ser el Departamento de Planeación Regional (DPR). Con tres esquemas diferentes: Ciudades con esquema metropolitano: para las ciudades que cuentan con área o región metropolitana conformada, esta entidad hará las veces de DPR. Ciudades sin esquema metropolitano: para el resto de las ciudades del sistema de ciudades que no cuentan con esquema metropolitano, se promoverá su conformación asociativa para que estos asuman el rol del DPR. Resto de municipios de Colombia (cerca de mil municipios): el DPR se conformará y agrupará por subregiones funcionales.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(759, 'Crear presupuestos participativos regionales', 'Asambleas populares de presupuesto participativo en cada región con DPR, alcaldías, gobernaciones, concejales, diputados y congresistas. La ciudadanía votará mediante medios tecnológicos los proyectos viabilizados para ejecución.', 'Crear los presupuestos participativos regionales: el DPR de cada región, con sus respectivas Alcaldías y gobernaciones, concejales, diputados y congresistas harán asambleas populares de presupuesto participativo para explicar a la ciudadanía los proyectos estructurados y viabilizados de inversión. Mediante medios tecnológicos al alcance de la ciudadanía, la gente votará y decidirá la priorización de los proyectos viabilizados técnica y financieramente para definir cuáles pasan a ejecución en la vigencia y cuáles de los que están en prefactibilidad pasan a estructuración definitiva para la siguiente vigencia.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(760, 'Fomentar asociaciones municipales, áreas y regiones metropolitanas', 'Promover esquemas metropolitanos y de colaboración entre municipios y departamentos, preservando autonomía administrativa, presupuestal y fiscal, para coordinar inversiones nacionales regionalizadas con su DPR respectivo.', 'Fomentar la creación de asociaciones municipales, áreas y regiones metropolitanas: con el fin de promover la asociatividad, se promoverán esquemas metropolitanos y de colaboración entre municipios y departamentos, preservando la autonomía administrativa, presupuestal y fiscal de los entes territoriales municipales o departamentales que los compongan. Esto permitirá coordinar decisiones, acciones e inversiones en beneficio de la gente, y coordinar más efectivamente la inversión nacional regionalizada con su DPR respectivo.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL);
INSERT INTO `proposals` (`id`, `title`, `summary`, `full_text`, `category_id`, `candidate_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(761, 'Recursos SGP de libre inversión y participación comunitaria en desarrollo económico', 'Eliminar el SGP limitado: los recursos girados a entes territoriales serán de libre inversión con destino decidido mediante presupuesto participativo. Las organizaciones comunitarias podrán formular y ejecutar proyectos y participar en Alianzas Público-Privadas-Comunitarias.', 'Dado que ese será el destino de la inversión nacional regionalizada, los recursos girados directamente a los entes territoriales vía SGP serán de libre inversión, excepto los que tienen destino a subsidios de servicios públicos o sociales definidos por Ley, pero su destino e inversión debe hacerse mediante votación de presupuesto participativo con la ciudadanía de cada ente territorial. Se termina así con el SGP limitado, la gente y sus autoridades locales tendrán autonomía en su priorización, inversión y ejecución. Se promoverá la participación de las comunidades en el desarrollo económico local: las organizaciones comunitarias podrán no sólo proponer ideas sino formular y ejecutar proyectos con inversión pública, privada y comunitaria, en sus comunidades.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(762, 'Banco Nacional de Suelos', 'Crear un banco para la gestión de suelo público y estratégico en función del desarrollo regional, facilitando el acceso a tierra bien localizada y apta para proyectos de vivienda, infraestructura y equipamientos sociales.', 'Banco Nacional de Suelos: se creará banco para gestión suelo público y estratégico en función del desarrollo regional, facilitando el acceso a tierra bien localizada y apta para proyectos de vivienda, infraestructura y equipamientos sociales.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(763, 'Reglamentación de Entidades Territoriales Indígenas (ETI)', 'Operacionalizar las recientemente creadas entidades territoriales indígenas (ETIs) en la Amazonía, garantizando competencias claras y presupuesto condicionado a indicadores de resultados y transparencia.', 'Las recientemente creadas entidades territoriales indígenas, o ETIs, ofrecen una oportunidad única para la implementación efectiva de una visión diferente del desarrollo en la región amazónica, pero la autonomía sin presupuesto ni capacidad institucional es demagogia. Sea municipios o ETIs, es hora de que en todo el territorio pasemos del decreto a la gerencia pública, a través de una ruta de adecuación institucional donde las ETI tengan competencias claras y, sobre todo, presupuesto condicionado a indicadores de resultados y transparencia.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(764, 'Defensa de ecosistemas estratégicos con liderazgo regional y global', 'Ejercer liderazgo en Américas y a nivel global para protección de la Amazonía, el Pacífico biogeográfico, los mares, la reserva Seaflower y ecosistemas estratégicos.', 'Defensa de ecosistemas estratégicos: ejerceremos liderazgo regional en las Américas y a nivel global para la protección de la Amazonía, el Pacífico biogeográfico, nuestros mares, la reserva Seaflower y todos nuestros ecosistemas estratégicos, para la transición energética, la soberanía alimentaria, y el desarrollo científico y tecnológico.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(765, 'Gestión hídrica integral con acceso universal a agua y saneamiento', 'Cerrar brechas de acceso a agua potable y saneamiento básico priorizando zonas rurales, rurales dispersas y comunidades étnicas. Priorizar uso del agua según vocación regional. Promover reúso y ahorro de agua mediante mercado regulado.', 'Cerrar brechas de acceso a agua potable y saneamiento básico: agua para la vida y la equidad territorial en territorios históricamente excluidos, priorizando zonas rurales, rurales dispersas y comunidades étnicas, mediante inversiones regionalizadas, soluciones diferenciales y fortalecimiento de capacidades locales. Priorizar el uso y valoración del agua según vocación regional: las CAR definirán caudales para el abastecimiento humano. Promover el reúso y ahorro de agua: se incentivará la reducción de pérdidas y el reúso de aguas lluvias y residuales tratadas, creando un mercado regulado que dinamice economías circulares.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(766, 'Protección animal y bienestar', 'Endurecer sanciones contra maltrato animal, implementar programas masivos de esterilización y vacunación, combatir tráfico ilegal de fauna y regular comercio de animales promoviendo adopción responsable.', 'Endurecer sanciones y fortalecer la inspección y judicialización efectiva del maltrato animal, con canales de denuncia y respuesta oportuna. Implementar programas masivos de esterilización y vacunación, priorizando municipios con mayores problemas de abandono y riesgo sanitario. Combatir el tráfico ilegal de fauna como parte de la estrategia contra economías ilícitas, con control territorial y coordinación interinstitucional. Regular el comercio de animales y promover la adopción responsable, reduciendo la informalidad y el abandono.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(767, 'Mercado de bonos de carbono y justicia climática interregional', 'Implementar mercado robusto de bonos de carbono y Pagos por Servicios Ambientales (PSA). Mecanismo de justicia climática interregional donde regiones que dependen de la humedad amazónica retribuyan económicamente a comunidades indígenas por la protección de ecosistemas.', 'Para financiar la sostenibilidad de la región, se implementará un mercado robusto de bonos de carbono a nivel global y esquemas de Pagos por Servicios Ambientales (PSA). Se establecerá un mecanismo de justicia climática interregional donde, por ejemplo, la región Andina, cuyo suministro de agua depende un 24% de la humedad generada por la selva amazónica, retribuya económicamente a las comunidades indígenas por la protección de los servicios ecosistémicos. El Estado actuará como garante de estos flujos financieros, asegurando que se traduzcan en inversión directa para el bienestar social y la protección de la estructura ecológica principal y de las comunidades indígenas.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(768, 'Reforma del ordenamiento ambiental y licenciamiento', 'Poner fin a la fragmentación normativa y de competencias en gestión ambiental. Reducir presión sobre ecosistemas estratégicos protegiendo Amazonía, parques naturales y reservas. Ubicar agua, ecosistemas y participación comunitaria en el centro de la gestión ambiental.', 'Nuestra apuesta productiva pasa necesariamente por asegurar la sostenibilidad ambiental de los modelos productivos de las regiones de manera ágil y efectiva. En términos de gestión ambiental, pondremos fin a la fragmentación normativa y de competencias en la gestión ambiental, reduciremos la presión creciente sobre ecosistemas estratégicos a través de la protección de la Amazonía, los parques naturales y todas las reservas naturales de conservación y protección y en el resto del territorio una visión productiva y sostenible. Solucionaremos los conflictos derivados de procesos de licenciamiento poco efectivos y excesivamente centralizados.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(769, 'Protección de la Reserva Seaflower y economía azul', 'Proteger la Reserva de la Biósfera Seaflower que alberga el tercer arrecife de coral más grande del mundo. Desarrollo basado en economía azul, bioeconomía, turismo sostenible, pesca artesanal sostenible, investigación científica y servicios ecosistémicos marinos.', 'San Andrés, Providencia y Santa Catalina se consolidarán como un territorio estratégico para la protección del mar Caribe y la biodiversidad insular, con un modelo de desarrollo centrado en la economía azul, el turismo sostenible, la conservación ambiental, y el cierre de brechas históricas. Se protegerá la Reserva de la Biósfera Seaflower, que alberga el tercer arrecife de coral más grande del mundo, fortaleciendo el papel de las comunidades locales como guardianas del ecosistema marino. El desarrollo económico de las islas estará basado en la economía azul, la bioeconomía y un turismo sostenible, como ejes para generar empleo y diversificar ingresos sin comprometer la integridad ambiental.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(770, 'Protección de Parques Nacionales y restauración ecológica del piedemonte amazónico', 'Aumentar recursos para defensa de Parques Nacionales Naturales estratégicos. Implementar planes de restauración ecológica con participación comunitaria. Revisar Zonas de Reserva Forestal y consolidar corredores biológicos entre Andes y Amazonía.', 'Para enfrentar la crisis ambiental en los departamentos del piedemonte amazónico que registran algunas de las tasas de deforestación más altas del país, se aumentarán los recursos para la defensa de los Parques Nacionales Naturales estratégicos. Se implementarán planes de restauración ecológica para áreas degradadas con participación comunitaria y financiamiento mixto, además de una revisión de las Zonas de Reserva Forestal para asegurar su uso sostenible y protección efectiva. El objetivo es consolidar corredores biológicos que aseguren la conectividad ecológica entre los Andes y la Amazonía, protegiendo el patrimonio natural del sur colombiano.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(771, 'Sistema Mixto e Integral de Salud', 'Articular servicios de salud con cuidado, salud mental y prevención. Sistema mixto con gestoras y prestadoras, con límites a integración vertical y auditoría pública rigurosa. Tablas de precios unificadas por servicios, regiones y poblaciones.', 'Sistema Mixto e Integral de Salud: que articule los servicios de salud con servicios de cuidado, salud mental y preventiva. Este sistema acompañará a las personas en todo su ciclo vital, superando la fragmentación actual. El sistema será mixto, con gestoras y prestadoras, pero con límites y controles a la integración vertical y con regencia y auditoría pública rigurosa y transparente. Estableceremos tablas de precios unificadas por servicios, regiones y poblaciones, con planes de beneficios explícitos, por zona urbana, centro poblado y zona rural, con mecanismos de pago contra auditoría con tecnología transparente.', 16, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(772, 'Nuevo estudio actuarial y plan de beneficios explícito', 'Realizar nuevo estudio actuarial que refleje la realidad demográfica, epidemiológica y cultural de la población. Construir planes de beneficios explícitos que garanticen equidad, incorporando salud mental, discapacidad y envejecimiento como prioridades.', 'Nuevo estudio actuarial, tecnología en salud y plan de beneficios explícito: realizaremos un nuevo estudio actuarial que refleje la realidad demográfica, epidemiológica y cultural de toda la población del país. Este estudio debe darnos información actualizada sobre cómo somos, de qué nos enfermamos y qué tipo de cuidados necesitamos en los diferentes ciclos de la vida. A partir de esa información, construiremos planes de beneficios explícitos que garanticen equidad, incorporando la salud mental, la discapacidad y el envejecimiento como prioridades de atención.', 16, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(773, 'Mejorar uso de recursos parafiscales para salud y cuidado', 'Permitir uso de recursos parafiscales para prestar servicios del sistema nacional de salud, cuidado y protección social, y regionalizar dichos recursos para asegurar equidad y modelo de gestión basado en resultados.', 'Mejorar el uso de los recursos parafiscales: permitir el uso de recursos parafiscales para prestar servicios del sistema nacional de salud, cuidado y protección social para toda la población, y regionalizar dichos recursos para asegurar equidad y un modelo de gestión basado en resultados. Se deben priorizar y ejecutar proyectos a escala regional de servicios de salud y cuidado, primera infancia, educación de básica a posmedia con jornada ampliada, alimentación y cuidado, vivienda y productividad.', 16, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(774, 'Recuperar patrimonio y memoria territorial', 'Crear un Sistema Regional de Patrimonios, museos vivos y pilotos de gestión patrimonial con participación ciudadana para descentralizar la inversión cultural y garantizar derechos culturales en todo el territorio.', 'Recuperar el patrimonio y memoria territorial: Sistema Regional de Patrimonios, museos vivos y pilotos de gestión patrimonial con participación ciudadana.', 14, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(775, 'Promover deporte, salud y bienestar - Salud', 'Integrar la actividad física a la salud pública, crear una ruta deportiva juvenil, los Juegos Regionales de la Identidad y Alianzas Público-Privadas deportivas para ampliar infraestructura y acceso al deporte en todo el territorio.', 'Promover el deporte, salud y bienestar: actividad física integrada a la salud pública, ruta deportiva juvenil, Juegos Regionales de la Identidad y APP deportivas para ampliar infraestructura y acceso.', 16, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(776, 'Protección de Parques Nacionales y restauración ecológica - Salud', 'Aumentar recursos para defensa de Parques Nacionales Naturales estratégicos. Implementar planes de restauración ecológica para áreas degradadas del piedemonte amazónico con participación comunitaria y financiamiento mixto.', 'Para enfrentar la crisis ambiental en los departamentos del piedemonte amazónico que registran algunas de las tasas de deforestación más altas del país, se aumentarán los recursos para la defensa de los Parques Nacionales Naturales estratégicos. Se implementarán planes de restauración ecológica para áreas degradadas con participación comunitaria y financiamiento mixto, además de una revisión de las Zonas de Reserva Forestal para asegurar su uso sostenible y protección efectiva.', 15, 7, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(777, 'Fintech: Digitalización del Crédito Popular', 'Sistema fintech para transformar el crédito informal a formal, facilitando el acceso al sistema financiero a microempresarios y erradicando el gota a gota.', 'Fondo público de innovación para soluciones digitales de ahorro y crédito. Sistema para que los trabajadores informales tengan acceso a un historial crediticio digital real y puedan acceder a crédito formal.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(778, 'Regalías Transparentes: App Digital de Control Ciudadano', 'Plataforma digital para que cada ciudadano pueda hacer seguimiento en tiempo real a la ejecución de las regalías regionales, usando tecnología blockchain.', 'A través de la App Regalía Firme cada ciudadano podrá ser el interventor de su propia riqueza. Las regalías en 2024 sumaron $18 billones, en mi gobierno serán para el agua, las vías y los colegios, no para la burocracia.', 11, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(779, 'Seguridad: Vigilancia con Drones en Fronteras', 'Uso de drones y tecnología de vigilancia para controlar las fronteras y combatir el narcotráfico y el contrabando.', 'Es necesario regresar a las alianzas estratégicas con Estados Unidos y el Estado de Israel para recuperar la inteligencia militar, la tecnología de las armas. Modernización de las capacidades de la fuerza pública con drones de última generación y la ciberinteligencia para la lucha frontal contra el crimen.', 13, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(780, 'Educación Técnica y Emprendimiento para Jóvenes Rurales', 'Programa SENA en 50 municipios pequeños para capacitar jóvenes rurales en agricultura tecnificada y competitividad empresarial.', 'Con el SENA iniciaré un programa piloto en 50 municipios con una población menor a 30.000 habitantes para formar una nueva generación de agricultores emprendedores, tecnificados y competitivos.', 10, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(781, 'Formación Dual: Colegios y Empresas', 'Modelos de formación dual que conecten la educación media y técnica con el mundo empresarial.', 'Para todos ellos crearé un régimen especial con exenciones totales, declaraciones de renta ultra simplificada para quienes facturen hasta $400 millones al año; cursos de capacitación, internet fibra ilimitada, coworking, mentoría de élite y matchmaking.', 10, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(782, 'Medicina Preventiva y Atención Primaria en Salud', 'Fortalecimiento de los centros de atención primaria y prevención de enfermedades como eje del nuevo modelo de salud.', 'Nuestra labor será dignificar estas profesiones, pasar de contratos de prestación de servicios y las garantías laborales, eliminar la tramitomanía y las barreras administrativas.', 16, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(783, 'Atención Diferencial para Mujeres Embarazadas y Lactantes', 'Plan específico de atención prenatal y posnatal para garantizar la salud materno-infantil.', 'Haremos el milagro de poner en marcha el programa Colombia país de propietarios, en el que mujeres como ustedes podrán tener su casa propia con créditos al 2 % anual por 30 años.', 7, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(784, 'Reindustrialización y Exportación de Valor Agregado', 'Visión de industrialización para que Colombia deje de exportar fósiles e innove con la exportación de valor agregado en sectores como la bioeconomía y el agro procesado.', 'Primero, visión y reindustrialización para que Colombia deje de exportar fósiles e innove con la exportación de valor agregado. Eso incluye de manera inexorable el respeto a la libre empresa, la redistribución de brechas regionales, megaproyectos productivos, inserción de cadenas de valor estratégicas globales, especialmente en la bioeconomía.', 3, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(785, 'Becas y Subsidios para Mujeres Cabeza de Hogar', 'Programa integral de apoyo a mujeres cabeza de hogar con acceso a educación, vivienda y empleo.', 'Haremos el milagro de poner en marcha el programa Colombia país de propietarios, en el que mujeres como ustedes podrán tener su casa propia con créditos al 2 % anual por 30 años.', 7, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(786, 'Empleo Juvenil con Incentivos al Sector Privado', 'Subsidios y exenciones para empresas que contraten jóvenes menores de 28 años con contrato formal.', 'Para todos ellos crearé un régimen especial con exenciones totales, declaraciones de renta ultra simplificada para quienes facturen hasta $400 millones al año; créditos de hasta $150 millones para equipos de tecnología con 0 % interés.', 7, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(787, 'Erradicación de Cultivos Ilícitos con Bioherbicidas', 'Uso de bioherbicidas de última generación como alternativa a la fumigación con glifosato para acabar con los cultivos de coca.', 'En los primeros 90 días de mi gobierno implementaré acciones de choque que permitan capturar diez cabecillas de alto valor por cada región; iniciaré la aspersión con bioherbicidas para acabar con la invasión de cultivos ilícitos.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(788, 'Fortalecimiento del Pie de Fuerza y Beneficios a la Fuerza Pública', 'Aumento del pie de fuerza, mejoras salariales y garantías legales para miembros de la Fuerza Pública.', 'garantizamos mayor pie de fuerza, garantías y respaldo para nuestros héroes. El milagro de vivir tranquilos solo es posible si sometemos a los criminales, garantizamos mayor pie de fuerza, garantías y respaldo para nuestro héroes.', 5, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(789, 'Transición Energética con Estabilidad Fiscal', 'Estrategia de transición energética que no comprometa las finanzas públicas ni el empleo regional, usando los recursos de hidrocarburos para financiar la inversión en renovables.', 'Sin recursos, hablar de transición energética es imposible. Tenemos el potencial de producir 1,3 millones de barriles equivalentes, hoy desperdiciados por la desidia.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(790, 'Energías Renovables: Solar y Eólico con Inversión Privada', 'Impulso a la energía solar y eólica mediante incentivos a la inversión privada y subastas de largo plazo.', 'Noveno. Someteré a una reforma profunda las leyes 142 y 143 para tener nombramientos de comisionados CREG por periodos fijos y técnicos y licenciamiento ambiental ágil para proyectos estratégicos de seguridad nacional.', 9, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(791, 'Infraestructura para la Producción: Vías, Puertos y Energía', 'Plan integral de infraestructura productiva que conecte zonas agrícolas con los mercados nacionales e internacionales.', 'Colombia necesita obras con transparencia, inversión en infraestructura vial, navegabilidad del río Magdalena, corredores seguros, licencias de exploración y explotación sustentable y sostenible de los suelos, alianzas internacionales justas.', 11, 6, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(792, 'Protección a Defensores de Derechos Humanos y Líderes Sociales', 'Programa de protección integral para líderes sociales, reclamantes de tierras y defensores de derechos humanos con esquemas colectivos e individuales.', 'Se garantizará la protección efectiva de líderes sociales, ambientales y comunitarios como condición para la presencia legítima del Estado en los territorios.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(793, 'Erradicación Forzada y Política Antidrogas', 'Retomar la erradicación forzada con bioherbicidas, política antinarcóticos eficaz y control de precursores químicos.', 'En las zonas donde hay cultivos ilícitos industriales, reactivaremos la fumigación sin afectar la salud ni los ecosistemas. Se implementará una política antidrogas eficaz en incautación y control de precursores químicos.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(794, 'Política de Drogas: Cannabis y Hoja de Coca', 'Apoyar la desclasificación del cannabis y la hoja de coca en el régimen internacional de drogas, complementando la lucha contra el narcotráfico.', 'Apoyaremos la desclasificación del cannabis y la hoja de coca, y fortaleceremos la cooperación internacional para la persecución del crimen organizado y el lavado de activos transnacional, particularmente el relacionado con el tráfico de cocaína.', 5, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(795, 'Pensión para Adultos Mayores en Pobreza', 'Garantizar un subsidio mínimo de $230.000 pesos a todos los adultos mayores en situación de pobreza, incrementando gradualmente hasta la línea de pobreza.', 'Ningún adulto mayor pobre quedará sin subsidio, con un monto mínimo de $230.000 pesos que aumentará gradualmente hasta cubrir la línea de pobreza en cada territorio. Este compromiso es incondicional: no depende de reformas pendientes ni de procesos judiciales.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(796, 'Subsidio a 3 millones de adultos vulnerables', 'Ampliar cobertura del subsidio económico a adultos mayores vulnerables.', 'Subsidio a 3 millones de adultos vulnerables.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(797, 'Ahorro pensional desde la cuna', '500.000 pesos de capital semilla a cada niño que nazca en pobreza.', 'El ahorro pensional empieza desde la cuna: el niño que nace en pobreza recibirá una semilla de ahorro del Estado desde el primer día. 500.000 pesos de capital semilla a cada niño que nazca en situación de pobreza.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(798, 'Ahorro semanal entre vivienda o pensión', 'Convertir el ahorro pensional en activos reales permitiendo a cada colombiano ahorrar semanalmente eligiendo entre vivienda o pensión.', 'Cada colombiano podrá ahorrar semanalmente sin importar su ingreso, eligiendo entre vivienda o pensión. Convertiremos el ahorro pensional en activos reales: de pensionados a propietarios.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(799, 'Impulso a la economía plateada', 'Emprendimiento senior, retorno a las aulas y rentabilización de activos para que los adultos mayores sigan aportando al país.', 'Impulso a la economía plateada para que nuestros mayores sigan aportando al país: Emprendimiento y mentoría senior. De vuelta a las aulas. Rentabilización de activos.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(800, 'Cierre de brechas de género', 'Políticas focalizadas para mujeres cabeza de hogar con subsidio directo, crédito y apoyo en cuidado vía billetera digital.', 'Cerraremos las brechas de género con políticas focalizadas en mujeres cabeza de hogar, que tendrán subsidio directo, crédito y apoyo en el cuidado de sus hijos, llegando al bolsillo en segundos vía billetera digital.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(801, 'Mejoramiento del cuidado infantil', '10 centros en ZOMAC, 100 unidades mejoradas y reducción de brecha rural en 55%.', 'Mejoramiento del sistema de cuidado infantil: 10 centros en ZOMAC, 100 unidades mejoradas y reducción de la brecha de cobertura rural en al menos 55 %.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(802, 'Formalización de mujeres y cuidadoras', '20.000 mujeres formalizadas y 50.000 cuidadoras tituladas.', 'Conectando con la gestión comunitaria: 20.000 mujeres formalizadas a través de las organizaciones y 50.000 cuidadoras tituladas.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(803, 'Conciliación cuidado-vida laboral y licencia de paternidad', '100% de entidades públicas con flexibilidad y licencia de paternidad de al menos 4 semanas.', 'Conciliación del cuidado y la vida laboral: 100 % de entidades públicas con flexibilidad y licencia de paternidad de por lo menos 4 semanas.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(804, 'Salud mental', '30 centros de atención, 80% de consultas con tamizaje y telemedicina, y cobertura psicosocial en colegios.', '2 de cada 3 colombianos han enfrentado un problema de salud mental; tenemos que cuidar de todos los colombianos. 30 centros de atención (mejoramientos y adaptación de casas de justicia). 80 % de consultas con tamizaje y telemedicina. Cobertura psicosocial en colegios con 16 equipos.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(805, 'Autonomía económica para mujeres', '100.000 mujeres con acceso a crédito para eliminar la violencia.', 'Autonomía económica para la eliminación de la violencia: 100.000 mujeres con acceso a crédito y reducción de brecha de cuidado.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(806, 'Contrato, salud y pensión para cuidadoras comunitarias', 'Reconocer el cuidado como infraestructura social.', 'Contrato, salud y pensión para cuidadoras comunitarias: el cuidado es infraestructura social.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(807, 'Simplificación normativa', 'Una sola fuente de verdad jurídica.', 'Simplificaremos el lenguaje normativo compilando una sola fuente de verdad jurídica.', 14, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(808, 'Inversión sin filiación política', 'Servicios del Estado para todos según sus necesidades.', 'La filiación política no importa: la inversión y los servicios del Estado llegan a todos los ciudadanos en función de sus necesidades y sin importar sus condiciones. En esta Colombia cabemos todos.', 14, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(809, 'Actualización predial', '60% del territorio actualizado antes del catastro multipropósito.', '60 % del territorio actualizado en gestión predial (antes de catastro multipropósito).', 14, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(810, 'Logística multimodal', 'Proyectos viales, férreos, aéreos, portuarios y fluviales.', 'Estructuraremos y/o desarrollaremos proyectos de infraestructura e impulsaremos las iniciativas privadas en los modos vial, férreo, aéreo, portuario y fluvial, para mejorar la logística multimodal.', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(811, 'Movilidad sostenible', 'Buses eléctricos, líneas de metro y trenes de cercanía.', 'Desarrollaremos proyectos de movilidad sostenible para el transporte masivo de pasajeros en los grandes centros urbanos y ciudades intermedias: buses eléctricos, líneas de metro y trenes de cercanía.', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(812, 'Ampliación de jornadas extracurriculares', 'Deporte, música, arte y cultura.', 'Ampliaremos las jornadas extracurriculares de deporte, música, arte y cultura.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(813, 'Ascenso docente por mérito y becas', 'Profesores ascienden por mérito y no por antigüedad.', 'Los colegios están llamados a mejorar en todos los aspectos. Los incentivos serán aplicados a las instituciones y se verán reflejados en el mejoramiento de las condiciones de los docentes. Los profesores ascenderán por mérito (no por antigüedad). Contaremos con becas por mérito académico.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(814, 'Formación dual desde noveno grado', 'Programas con Instituciones Técnicas y Tecnológicas y empresas.', 'La educación y la formación para el trabajo deben ser la puerta de entrada a mejores oportunidades para todos. Los jóvenes desde noveno grado podrán ser parte de programas de formación dual entre Instituciones Técnicas y Tecnológicas (ITT) y empresas para que puedan iniciar su formación en oficios.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(815, 'Subsidio al primer empleo juvenil', '30% del salario mínimo por 12 meses (40% por 18 meses en PDET), priorizando mujeres jefas de hogar, víctimas y étnicos.', 'Subsidio al primer empleo juvenil: 30 % del salario mínimo durante 12 meses para empresas que vinculen jóvenes de 18 a 28 años. 40 % durante 18 meses en territorios PDET. Prioridad a mujeres jóvenes jefas de hogar, jóvenes en ZOMAC, víctimas del conflicto y jóvenes étnicos.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(816, 'Rescate de COLFUTURO', 'Formación de posgrado en universidades del mundo.', 'Rescataremos a COLFUTURO para que pueda cumplir su misión de formación en posgrado de profesionales de excelencia académica, apoyando la realización de maestrías y doctorados en las mejores universidades del mundo.', 10, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(817, 'Restauración de 1 millón de corales', 'Beneficiar pescadores y dinamizar turismo costero y economía azul.', 'Restauraremos 1 millón de corales, beneficiando a los pescadores y comunidades costeras en los dos océanos, dinamizando así el turismo costero y la economía azul.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(818, 'Ordenación de cuencas', '100% de cuencas priorizadas con instrumentos de manejo.', '100 % de las cuencas priorizadas con instrumento de ordenación y manejo implementados.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(819, 'Fortalecimiento de parques nacionales', 'Erradicar grupos ilegales de parques naturales y del Chocó biogeográfico.', 'Fortaleceremos los parques nacionales naturales. Erradicaremos a los grupos ilegales de los parques nacionales y de las áreas de reserva. Erradicaremos del Chocó biogeográfico a la guerrilla del ELN y a los clanes de la mafia que hoy controlan una parte sustancial de este territorio.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(820, 'Regalías para el sector ambiental', 'Recursos de minería, petróleo, energía y gas financiarán el cuidado de la naturaleza.', 'Las regalías vuelven al sector ambiental. Los recursos generados por la explotación legal de minas, petróleo, energía y gas deben financiar el cuidado de la naturaleza.', 15, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(821, 'Hospitales padrinos y telemedicina rural', '100.000 atenciones en zonas rurales con cobertura en 32 departamentos y 8 distritos.', 'Hospitales padrinos: el especialista llega al campo, no al revés. Ampliaremos este programa para cubrir los 32 departamentos y los 8 distritos, transfiriendo capacidades de centros de alta complejidad que atienden pacientes rurales. Generaremos 100.000 atenciones en zonas rurales por medio de hospitales padrinos, telemedicina.', 16, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(822, 'Mejores condiciones laborales para médicos y enfermeras', 'Pago a tiempo y mejores salarios.', 'Mejores condiciones laborales para médicos y enfermeras: pago a tiempo y mejores salarios.', 16, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(823, 'Compra de oro por el Banco de la República', 'Explorar que el Banco de la República compre oro y los pequeños mineros se organicen en empresas.', 'Exploraremos la posibilidad de que el Banco de la República, respetando su autonomía, compre el oro en Colombia y que los pequeños mineros se organicen en empresas productoras con la cooperación de empresas públicas o privadas.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(824, 'Plan Turismo 12M y cielos abiertos', '12 millones de visitantes para 2030 con vuelos desde Europa y Asia, gasto turístico de 7.000 a 14.000 millones de USD.', 'Implementaremos una política de cielos abiertos y redistribución. El Plan Turismo 12M busca abrir cielos para vuelos desde Europa y Asia y dar incentivos a regiones turísticas emergentes. Llegaremos a 12 millones de visitantes para 2030, aumentando el gasto turístico de 7.000 a 14.000 millones de dólares.', 3, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(825, 'Soberanía en la cooperación de seguridad', 'Autonomía operativa con financiamiento y capacitación internacional, manteniendo mando soberano.', 'Soberanía en la cooperación de seguridad: mantendremos la autonomía operativa total en la lucha contra el crimen transnacional. Bajo nuestro gobierno, la Fuerza Pública colombiana será la única responsable de ejecutar las operaciones en el territorio, contando con el financiamiento y la capacitación internacional, pero asegurando el mando soberano de nuestras instituciones.', 12, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(826, 'Comercio con China bajo libre competencia', 'Evaluar el acuerdo Franja y Ruta con condiciones de acceso real y licitaciones transparentes.', 'Comercio con China bajo libre competencia: fomentaremos una relación con China basada en la libre competencia y el beneficio mutuo en infraestructura y comercio. Evaluaremos rigurosamente el acuerdo de la Franja y la Ruta para garantizar que existan condiciones de acceso real para los productos colombianos.', 12, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(827, 'Marcos regulatorios flexibles para experimentación privada', 'Comisiones para aprobar contratos de estabilidad jurídica, PINES y nuevas zonas francas.', 'Adopción de marcos regulatorios basados en principios flexibles para permitir la experimentación privada. Crearemos comisiones con competencia total para aprobar contratos de estabilidad jurídica, PINES y nuevas zonas francas.', 13, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(828, 'Institucionalidad ágil para licenciamiento', 'Instancia de decisión rápida con liderazgo ministerial para licenciamiento ambiental, gestión predial, consultas previas y financiamiento.', 'Restablecimiento de una instancia de decisión rápida, con liderazgo ministerial, que articule, decida y haga seguimiento sobre el licenciamiento ambiental, la gestión predial, las consultas previas y el financiamiento de los proyectos de interés nacional y estratégicos para el progreso de los colombianos.', 11, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(829, 'Consulta previa como alianza, no veto', 'Comunidades étnicas como socias de proyectos en lugar de tener derecho a veto.', 'La consulta previa no puede ser un veto, sino un mecanismo para garantizar inversión en la región. Transitaremos hacia un modelo de alianza donde se consulte a las comunidades étnicas sobre la gestión de los impactos y la destinación de los recursos generados. Las comunidades deberán poder ser socias de los proyectos.', 14, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(830, 'Inversión en emprendimientos de mujeres', 'Capital semilla de 2 millones de pesos por mujer con acompañamiento integral y crédito blando.', 'La inversión para emprendimientos liderados por mujeres será en promedio de 2 millones de pesos por cada una, para capital semilla con acompañamiento integral para lograr formalización, generación de ingresos, transformación psicosocial junto con el aprendizaje técnico, productivo, financiero y administrativo.', 8, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(831, 'Deporte para la gente', 'Fortalecer participación comunitaria, ampliar oferta de programas y mejorar resultados deportivos.', 'La participación de todos los colombianos en el deporte, la recreación y la actividad física ayuda a crear las condiciones para el ejercicio efectivo de los derechos de la gente. Fortalecer la participación comunitaria. Incrementar la práctica del deporte, la recreación y la actividad física. Ampliar la oferta de programas y eventos. Mantener y mejorar los resultados deportivos.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL),
(832, 'Infraestructura deportiva', 'Sistema y censo nacional de infraestructura deportiva con responsabilidad ambiental.', 'Aumentar el número y las calidades físicas y ambientales de la infraestructura deportiva (parques, escenarios deportivos) y entornos que estimulen el uso adecuado y el desarrollo de programas deportivos, recreativos y de actividad física. Sistema nacional de infraestructura deportiva. Censo nacional de infraestructura deportiva. Responsabilidad ambiental de estos centros. Integración urbano-rural-regional.', 7, 8, '2026-05-18 16:48:25', '2026-05-18 16:48:25', NULL);
